(window.__APPSRC=window.__APPSRC||{})["orl"]="<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>ORL · Révision L3 · Daniel Noufe INFAS</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--bg:#EEF3F7;--card:#fff;--ink:#0F1E33;--mut:#5E6E82;--line:#D6E0EA;--b1:#0E2340;--b2:#15335C;--b3:#1F4A7E;--gold:#2EC4B6;--gold2:#7FE3D8;--goldink:#052B2A;--goldlt:#DDF4F1;--rasp:#E8684A;--prune:#3B3F8F;--brick:#1E7A78;--ok:#2E8B57;--bad:#C0392B;--mid:#D69A1C;--sh:0 6px 22px rgba(14,35,64,.10);--sh2:0 10px 30px rgba(14,35,64,.20);--r:24px}\n@media (prefers-color-scheme:dark){:root{--bg:#08121F;--card:#12223A;--ink:#E8F0F8;--mut:#97A8BE;--line:#22344F;--goldlt:#0F3634;--sh:0 6px 22px rgba(0,0,0,.35);--sh2:0 10px 30px rgba(0,0,0,.5)}}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{margin:0;background:var(--bg);color:var(--ink);font-family:\"Plus Jakarta Sans\",system-ui,-apple-system,\"Segoe UI\",Roboto,Arial,sans-serif;font-size:15px;line-height:1.5}\nbody{padding-bottom:calc(96px + env(safe-area-inset-bottom))}\n#app{max-width:560px;margin:0 auto;padding:0 14px}\nbutton{font:inherit;color:inherit;cursor:pointer;border:0;background:none}\nbutton:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--gold);outline-offset:2px}\n.hdr{margin:0 -14px;padding:calc(14px + env(safe-area-inset-top)) 18px 18px;background:linear-gradient(150deg,var(--b1),var(--b2) 55%,var(--b3));color:#fff;border-radius:0 0 28px 28px;box-shadow:var(--sh2);position:relative}\n.brand{display:flex;align-items:center;gap:12px}\n.logo{font-size:44px;font-weight:800;letter-spacing:-1px;line-height:1;background:linear-gradient(180deg,#C9F7F1,#2EC4B6 55%,#14857C);-webkit-background-clip:text;background-clip:text;color:transparent}\n.sub{font-size:13px;line-height:1.25;opacity:.92;max-width:220px}\n.sig{margin-top:8px;font-size:17px;font-weight:800;color:#fff}\n.sig b{color:var(--gold2)}\n.hback{position:absolute;right:14px;top:calc(14px + env(safe-area-inset-top));width:44px;height:44px;border-radius:50%;background:rgba(255,255,255,.12);color:#fff;font-size:20px}\n.foot{text-align:center;font-size:12px;color:var(--mut);margin:26px 0 8px}\n.foot b{color:var(--rasp)}\nh2.tt{font-size:20px;margin:20px 2px 10px;font-weight:800}\nh3.st{font-size:15px;margin:18px 2px 8px;font-weight:700;color:var(--mut)}\n.card{background:var(--card);border-radius:var(--r);box-shadow:var(--sh);padding:16px;margin:12px 0}\n.btn{min-height:48px;border-radius:16px;padding:0 18px;font-weight:700;display:inline-flex;align-items:center;justify-content:center;gap:8px}\n.btn.gold{background:linear-gradient(180deg,#62D8CC,var(--gold));color:var(--goldink);box-shadow:0 6px 16px rgba(46,196,182,.35)}\n.btn.dark{background:var(--b2);color:#fff}\n.btn.ghost{background:var(--goldlt);color:var(--ink)}\n.btn.line{border:2px solid var(--line);background:var(--card)}\n.btn.full{width:100%}\n.row{display:flex;gap:10px;align-items:center}\n.wrap{flex-wrap:wrap}\n.grow{flex:1}\n.chip{min-height:38px;border-radius:999px;padding:6px 14px;background:var(--card);border:2px solid var(--line);font-weight:600;font-size:13px;display:inline-flex;align-items:center;gap:6px}\n.chip.on{background:var(--b2);border-color:var(--b2);color:#fff}\n.pg{display:inline-flex;align-items:center;min-height:30px;padding:2px 10px;border-radius:999px;background:var(--goldlt);color:var(--ink);font-size:12px;font-weight:700;margin:2px 4px 2px 0}\n.badge{display:inline-flex;align-items:center;gap:4px;padding:3px 10px;border-radius:999px;font-size:12px;font-weight:700;background:var(--line);margin:2px 4px 2px 0}\n.mut{color:var(--mut)}.small{font-size:12.5px}\n/* profile card */\n.pcard{background:linear-gradient(140deg,var(--b2),var(--b3));color:#fff;border-radius:26px;padding:16px;margin-top:-6px;box-shadow:var(--sh2);display:block;width:100%;text-align:left}\n.av{width:58px;height:58px;border-radius:50%;background:rgba(255,255,255,.14);display:grid;place-items:center;font-size:32px;flex:none;border:2px solid var(--gold)}\n.xpbar{height:10px;border-radius:9px;background:rgba(255,255,255,.18);overflow:hidden;margin:10px 0 6px}\n.xpbar i{display:block;height:100%;background:linear-gradient(90deg,var(--gold),#9BEDE4);border-radius:9px}\n.stat3{display:flex;gap:6px;font-size:12.5px;flex-wrap:wrap}\n.stat3 span{background:rgba(255,255,255,.12);padding:3px 9px;border-radius:999px}\n.search{display:flex;gap:8px;background:var(--card);border-radius:18px;box-shadow:var(--sh);padding:6px 6px 6px 14px;margin:14px 0;align-items:center}\n.search input{flex:1;border:0;background:none;font:inherit;color:var(--ink);min-height:40px;outline:none}\n.hero{width:100%;display:flex;align-items:center;gap:12px;background:linear-gradient(180deg,#62D8CC,var(--gold));color:var(--goldink);border-radius:26px;padding:16px;box-shadow:0 10px 26px rgba(46,196,182,.38);text-align:left}\n.hero b{font-size:21px;display:block}\n.seg{display:flex;gap:3px;margin:6px 0 2px}\n.seg button{flex:1;height:16px;border-radius:5px;min-width:0}\n.tiles{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px}\n.tile{background:var(--card);border-radius:22px;box-shadow:var(--sh);padding:14px 8px;text-align:center;font-weight:700;font-size:13px;min-height:96px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px}\n.tile .ic{font-size:26px}\n.legend{display:flex;gap:10px;flex-wrap:wrap;font-size:12px;color:var(--mut);margin-top:8px}\n.legend i{display:inline-block;width:12px;height:12px;border-radius:3px;vertical-align:-2px;margin-right:4px}\n/* chapter cards */\n.cc{border-radius:24px;padding:14px;margin:10px 0;display:flex;gap:12px;align-items:center;box-shadow:var(--sh);width:100%;text-align:left}\n.cc.k0{background:var(--goldlt);color:var(--ink)}.cc.k1{background:var(--prune);color:#fff}.cc.k2{background:var(--brick);color:#fff}\n.cc .t{font-weight:800;font-size:15px;line-height:1.25}\n.cc .m{font-size:12px;opacity:.85}\n.star{font-size:22px;width:44px;height:44px;flex:none}\n.ring{flex:none}\n.pills{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}\n.pill{background:var(--card);border-radius:16px;padding:8px 12px;box-shadow:var(--sh);font-size:12px}\n.pill b{display:block;font-size:18px}\n/* sommaire */\n.bband{border-radius:20px;padding:12px 16px;color:#fff;font-weight:800;margin:16px 0 6px}\n.sline{background:var(--card);border-radius:18px;padding:12px 14px;margin:6px 0;box-shadow:var(--sh)}\n.sline .t{font-weight:800}\n/* course */\n.page{background:var(--card);border-radius:22px;box-shadow:var(--sh);padding:14px 16px;margin:14px 0}\n.pmark{display:inline-block;font-size:12px;font-weight:800;color:var(--goldink);background:var(--gold);border-radius:999px;padding:3px 10px;margin-bottom:6px}\n.pgtext h2{font-size:18px;margin:8px 0;color:var(--rasp)}\n.pgtext h3{font-size:15px;margin:12px 0 4px}\n.pgtext p{margin:6px 0}\n.pgtext ul{margin:4px 0;padding-left:20px}\n.pgtext .fig{font-style:italic;color:var(--mut);font-size:13px}\nmark.key{background:rgba(46,196,182,.30);color:inherit;border-radius:3px;padding:0 1px}\nmark.hl{color:inherit;border-radius:3px;cursor:pointer}\nmark.hl.y{background:#FFE066}mark.hl.g{background:#9BE5B0}mark.hl.p{background:#F7B6CF}mark.hl.b{background:#A9D3FF}\n@media (prefers-color-scheme:dark){mark.hl{color:#0b1220}}\n.figimg{display:block;max-width:100%;border-radius:14px;margin:10px auto 4px;cursor:zoom-in;background:#fff}\n.cap{font-size:12px;color:var(--mut);text-align:center}\n.note{background:var(--goldlt);border-radius:14px;padding:10px 12px;margin-top:10px;font-size:14px;white-space:pre-wrap}\n.annot{font-size:13px;font-weight:700;color:var(--rasp);min-height:40px;padding:0 6px}\n#hlbar{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(98px + env(safe-area-inset-bottom));background:var(--b1);border-radius:999px;padding:6px;display:none;gap:4px;z-index:60;box-shadow:var(--sh2)}\n#hlbar button{min-height:40px;padding:0 10px;border-radius:999px;font-size:12px;font-weight:700;color:#1b0b10}\n/* quiz */\n.qhead{margin:0 -14px;padding:16px 18px 18px;background:var(--b1);color:#fff;border-radius:0 0 26px 26px}\n.cnt3{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px}\n.cnt3 div{background:rgba(255,255,255,.1);border-radius:16px;padding:10px;text-align:center;font-size:12px}\n.cnt3 b{display:block;font-size:20px;color:var(--gold2)}\n.mode{display:flex;align-items:center;gap:12px;width:100%;text-align:left;background:var(--card);border-radius:22px;padding:14px;margin:10px 0;box-shadow:var(--sh)}\n.mode .ic{width:48px;height:48px;border-radius:16px;display:grid;place-items:center;font-size:24px;flex:none}\n.bar{height:8px;border-radius:8px;background:var(--line);overflow:hidden;margin-top:6px}\n.bar i{display:block;height:100%;border-radius:8px}\n.prog{height:8px;border-radius:8px;background:var(--line);overflow:hidden;margin:12px 0}\n.prog i{display:block;height:100%;background:var(--gold)}\n.qcard{background:var(--card);border-radius:24px;box-shadow:var(--sh);padding:16px;margin:10px 0}\n.qtext{font-size:17px;font-weight:700;margin:10px 0 12px}\n.situ{background:var(--goldlt);border-left:5px solid var(--gold);border-radius:14px;padding:12px;margin:8px 0;font-size:14.5px}\n.opt{display:flex;gap:10px;align-items:flex-start;width:100%;text-align:left;border:2px solid var(--line);background:var(--card);border-radius:18px;padding:12px;margin:8px 0;min-height:52px;font-size:15px}\n.opt .l{width:28px;height:28px;border-radius:50%;background:var(--line);display:grid;place-items:center;font-weight:800;font-size:13px;flex:none}\n.opt.ok{border-color:var(--ok);background:rgba(46,139,87,.12)}.opt.ok .l{background:var(--ok);color:#fff}\n.opt.ko{border-color:var(--bad);background:rgba(192,57,43,.12)}.opt.ko .l{background:var(--bad);color:#fff}\n.verdict{border-radius:16px;padding:12px;margin:12px 0;font-weight:700}\n.verdict.ok{background:rgba(46,139,87,.14);color:var(--ok)}.verdict.ko{background:rgba(192,57,43,.12);color:var(--bad)}\n.verdict span{display:block;font-weight:500;color:var(--ink);margin-top:4px}\n.oinput{width:100%;min-height:52px;border-radius:16px;border:2px solid var(--line);background:var(--card);color:var(--ink);font:inherit;padding:10px 14px}\n.why h4,.mem h4{margin:0 0 6px;font-size:15px}\n.mem .aid{display:flex;gap:10px;margin:10px 0;align-items:flex-start}\n.mem .aid .i{width:34px;height:34px;border-radius:12px;display:grid;place-items:center;flex:none;font-size:17px}\n.schema{font-weight:700;color:var(--rasp)}\n.tipline{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:12.5px;color:var(--mut);border-top:1px dashed var(--line);margin-top:12px;padding-top:8px}\n.tipline button{font-size:12px;font-weight:700;color:var(--rasp);min-height:36px;padding:0 8px}\n.qnav{display:flex;gap:8px;margin:14px 0}\n.qnav .btn{flex:1;padding:0 8px}\n/* config */\n.slider{width:100%;accent-color:var(--rasp)}\n.coll{display:flex;justify-content:space-between;align-items:center;width:100%;min-height:52px;font-weight:800;text-align:left}\n.blk{border-top:1px solid var(--line);padding:6px 0}\n.chk{display:flex;align-items:center;gap:10px;min-height:44px;width:100%;text-align:left;font-size:14px}\n.chk i{width:24px;height:24px;border-radius:8px;border:2px solid var(--line);display:grid;place-items:center;font-style:normal;flex:none;font-size:14px}\n.chk.on i{background:var(--rasp);border-color:var(--rasp);color:#fff}\n/* flash */\n.flash{min-height:300px;border-radius:26px;box-shadow:var(--sh2);padding:20px;display:flex;flex-direction:column;justify-content:center;background:var(--card);cursor:pointer;width:100%;text-align:left}\n.flash.front{background:linear-gradient(150deg,var(--b2),var(--b3));color:#fff}\n/* stats */\n.hist{display:flex;align-items:flex-end;gap:4px;height:150px;margin-top:12px}\n.hist div{flex:1;background:var(--rasp);opacity:.55;border-radius:6px 6px 2px 2px;position:relative;min-height:2px}\n.hist div.max{opacity:1;background:var(--gold)}\n.hist div span{position:absolute;top:-18px;left:50%;transform:translateX(-50%);font-size:10px;font-weight:800;color:var(--ink)}\n.hlab{display:flex;gap:4px;font-size:9.5px;color:var(--mut);margin-top:4px}.hlab span{flex:1;text-align:center}\n.mot{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}\n.mot div{background:var(--card);border-radius:20px;box-shadow:var(--sh);padding:12px;text-align:center;font-size:12px}\n.mot b{display:block;font-size:20px}\n.mrow{display:block;width:100%;text-align:left;padding:8px 0;border-bottom:1px solid var(--line)}\n/* tables */\n.tbl{overflow-x:auto;margin-top:8px}\n.tbl table{border-collapse:collapse;min-width:100%;font-size:13px}\n.tbl th{background:var(--b2);color:#fff;padding:8px;text-align:left}\n.tbl td{padding:8px;border-bottom:1px solid var(--line);vertical-align:top}\n.tbl td:first-child{font-weight:700}\n/* gallery */\n.gal{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.gal button{background:var(--card);border-radius:18px;box-shadow:var(--sh);padding:8px;text-align:left;font-size:12px}\n.gal img{width:100%;height:110px;object-fit:contain;background:#fff;border-radius:12px}\n/* nav */\n#nav{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(12px + env(safe-area-inset-bottom));width:min(532px,calc(100% - 24px));background:#0A1A30;border-radius:26px;display:flex;justify-content:space-around;padding:8px;z-index:50;box-shadow:0 12px 30px rgba(0,0,0,.35)}\n#nav button{flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;color:#B9C9DC;font-size:11px;font-weight:600;min-height:56px;justify-content:center}\n#nav .pi{width:44px;height:32px;border-radius:14px;display:grid;place-items:center}\n#nav button.on{color:var(--gold2)}\n#nav button.on .pi{background:var(--gold);color:var(--goldink)}\n#nav svg{width:22px;height:22px}\n/* overlays */\n#viewer{position:fixed;inset:0;background:rgba(4,10,20,.94);display:none;flex-direction:column;align-items:center;justify-content:center;z-index:100;padding:20px;color:#fff}\n#viewer img{max-width:100%;max-height:68vh;border-radius:12px;background:#fff}\n#viewer .vx{position:absolute;top:calc(14px + env(safe-area-inset-top));right:14px;width:48px;height:48px;border-radius:50%;background:rgba(255,255,255,.15);color:#fff;font-size:22px}\n#viewer .vn{display:flex;gap:10px;margin-top:14px}\n#modal{position:fixed;inset:0;background:rgba(5,12,25,.6);display:none;align-items:flex-end;justify-content:center;z-index:90}\n#modal .box{background:var(--card);width:100%;max-width:560px;border-radius:26px 26px 0 0;padding:18px 18px calc(18px + env(safe-area-inset-bottom))}\n#modal textarea,#modal input[type=text]{width:100%;min-height:110px;border-radius:16px;border:2px solid var(--line);padding:10px;font:inherit;background:var(--bg);color:var(--ink)}\n#modal input[type=text]{min-height:50px}\n#toast{position:fixed;top:calc(16px + env(safe-area-inset-top));left:50%;transform:translateX(-50%);background:var(--gold);color:var(--goldink);font-weight:800;padding:12px 18px;border-radius:999px;z-index:120;display:none;box-shadow:var(--sh2)}\n.res{text-align:center}\n.res .big{font-size:52px;font-weight:800;color:var(--rasp)}\n.list .it{padding:10px 0;border-bottom:1px solid var(--line)}\n.glet{font-weight:800;color:var(--rasp);margin:14px 0 4px;font-size:18px}\n@media (prefers-reduced-motion:no-preference){.hero,.tile,.cc,.mode,.opt{transition:transform .12s}.hero:active,.tile:active,.cc:active,.mode:active,.opt:active{transform:scale(.98)}}\n</style>\n</head>\n<body>\n<main id=\"app\"></main>\n<nav id=\"nav\"></nav>\n<div id=\"hlbar\"></div>\n<div id=\"viewer\" role=\"dialog\" aria-label=\"Visionneuse\"></div>\n<div id=\"modal\" role=\"dialog\"></div>\n<div id=\"toast\"></div>\n<script>\nconst D={\"blocks\": [{\"id\": \"A\", \"t\": \"Anatomie et physiologie\", \"c\": \"#1E9E92\"}, {\"id\": \"B\", \"t\": \"Oreille : pathologies\", \"c\": \"#3B3F8F\"}, {\"id\": \"C\", \"t\": \"Nez et sinus\", \"c\": \"#E8684A\"}, {\"id\": \"D\", \"t\": \"Pharynx, larynx et urgences\", \"c\": \"#1F4A7E\"}, {\"id\": \"E\", \"t\": \"Soins techniques ORL\", \"c\": \"#7A5AA6\"}], \"ch\": [{\"id\": \"a1\", \"b\": \"A\", \"t\": \"Anatomie et physiologie de l'oreille\", \"r\": \"1:3-5\"}, {\"id\": \"a2\", \"b\": \"A\", \"t\": \"Anatomie et physiologie du nez\", \"r\": \"1:6-7\"}, {\"id\": \"a3\", \"b\": \"A\", \"t\": \"Anatomie et physiologie des sinus\", \"r\": \"1:8\"}, {\"id\": \"a4\", \"b\": \"A\", \"t\": \"Anatomie et physiologie du pharynx\", \"r\": \"1:9-10\"}, {\"id\": \"a5\", \"b\": \"A\", \"t\": \"Larynx et trachée\", \"r\": \"1:11-13\"}, {\"id\": \"b1\", \"b\": \"B\", \"t\": \"Les otalgies\", \"r\": \"1:14-15\"}, {\"id\": \"b2\", \"b\": \"B\", \"t\": \"Les surdités\", \"r\": \"1:16-17\"}, {\"id\": \"b3\", \"b\": \"B\", \"t\": \"Les acouphènes\", \"r\": \"1:18\"}, {\"id\": \"b4\", \"b\": \"B\", \"t\": \"Pathologies de l'oreille externe\", \"r\": \"1:24-27\"}, {\"id\": \"b5\", \"b\": \"B\", \"t\": \"Otite moyenne aiguë du nourrisson\", \"r\": \"1:27-28\"}, {\"id\": \"c1\", \"b\": \"C\", \"t\": \"Les épistaxis\", \"r\": \"1:19-21\"}, {\"id\": \"c2\", \"b\": \"C\", \"t\": \"Les rhinites\", \"r\": \"1:29-31\"}, {\"id\": \"c3\", \"b\": \"C\", \"t\": \"Les sinusites aiguës\", \"r\": \"1:32-33\"}, {\"id\": \"c4\", \"b\": \"C\", \"t\": \"Les végétations adénoïdes\", \"r\": \"1:34-35\"}, {\"id\": \"d1\", \"b\": \"D\", \"t\": \"Les rhinopharyngites\", \"r\": \"2:1-2\"}, {\"id\": \"d2\", \"b\": \"D\", \"t\": \"Les pharyngites\", \"r\": \"2:3-5\"}, {\"id\": \"d3\", \"b\": \"D\", \"t\": \"Angines et amygdalites aiguës\", \"r\": \"2:6-7\"}, {\"id\": \"d4\", \"b\": \"D\", \"t\": \"La dyspnée laryngée\", \"r\": \"1:22-23\"}, {\"id\": \"d5\", \"b\": \"D\", \"t\": \"Corps étrangers des voies aéro-digestives\", \"r\": \"2:8-10\"}, {\"id\": \"e1\", \"b\": \"E\", \"t\": \"Lavage d'oreille\", \"r\": \"2:11-13\"}, {\"id\": \"e2\", \"b\": \"E\", \"t\": \"Lavage de nez\", \"r\": \"2:13-17\"}, {\"id\": \"e3\", \"b\": \"E\", \"t\": \"Méchage antérieur\", \"r\": \"2:18-19\"}, {\"id\": \"e4\", \"b\": \"E\", \"t\": \"Soins de trachéotomie\", \"r\": \"2:20\"}], \"pages\": [{\"d\": 1, \"p\": 3, \"i\": 2, \"ch\": \"a1\", \"t\": \"# ANATOMIE ET PHYSIOLOGIE DE L'OREILLE\\nObjectif général : reconnaître la constitution de l'oreille ainsi que son rôle.\\nObjectifs spécifiques : citer les différentes parties de l'oreille ; expliquer le rôle de la trompe d'Eustache ; décrire succinctement la physiologie de l'oreille externe et moyenne.\\n[Figure : schéma de l'oreille]\\n+++L'appareil auriculaire est divisé en deux : l'appareil de transmission (oreille externe et oreille moyenne) et l'appareil de perception qui constitue l'oreille interne.+++\\n## I- ANATOMIE\\n## 1-1 L'oreille externe\\nElle comprend le pavillon et le conduit auditif externe.\\n- Le pavillon : au niveau de sa face antérieure, il présente des saillies et des dépressions ; au niveau de la face postérieure, il est séparé de la mastoïde par le sillon rétro-auriculaire.\\n- Le conduit auditif externe (méat acoustique externe) : en forme d'entonnoir, il prend fin au niveau de la couche externe du tympan. +++Structure fibro-cartilagineuse dans son tiers (1/3) externe et osseuse dans ses deux tiers (2/3) internes.+++\"}, {\"d\": 1, \"p\": 4, \"i\": 3, \"ch\": \"a1\", \"t\": \"Sur le tiers externe, la peau du conduit possède des +++glandes cérumineuses+++ qui produisent le cérumen de couleur jaune, voire brune.\\nLe cérumen a pour rôle :\\n- de protéger les parois du conduit auditif ;\\n- de piéger les corps étrangers (poussière, petits insectes, etc.) ;\\n- de protéger l'oreille contre la prolifération des bactéries, éliminées grâce aux propriétés antibactériennes du cérumen ;\\n- d'éliminer des débris de peau qui desquame.\\nSur les deux tiers internes du CAE, la peau adhère directement à l'os.\\n## 1-2 L'oreille moyenne\\nCreusée dans le rocher, l'oreille moyenne est constituée par une suite de cavités :\\n- la caisse du tympan qui contient la chaîne des osselets ;\\n- la mastoïde ;\\n- la trompe d'Eustache.\\nCaisse du tympan : interposée entre l'oreille interne et l'oreille externe. Elle communique avec le pharynx par la trompe d'Eustache et avec la mastoïde. Elle contient les osselets : +++marteau – enclume – étrier+++. Ceux-ci forment avec le tympan la chaîne tympano-ossiculaire qui joue un rôle dans la transmission des vibrations sonores.\\n[Figure : vue otoscopique du tympan]\\nTrompe d'Eustache : +++conduit ostéo-cartilagineux qui fait communiquer la caisse du tympan avec le pharynx+++ ; elle participe à l'aération de l'oreille\"}, {\"d\": 1, \"p\": 5, \"i\": 4, \"ch\": \"a1\", \"t\": \"moyenne et +++sert d'équilibre de pression de part et d'autre du tympan+++.\\nLa mastoïde : composée de cellules aériennes creusées dans l'os temporal, dont la plus importante est l'antre mastoïdien.\\n## 2-3 L'oreille interne ou labyrinthe\\nSituée dans le rocher, structure osseuse et membraneuse. Chaque partie est composée d'une unité fonctionnelle :\\n- la cochlée : +++organe de Corti+++ ;\\n- le vestibule : la macule ;\\n- les canaux semi-circulaires : les crêtes ampullaires.\\n## II- PHYSIOLOGIE\\n## 2-1 L'oreille externe\\nElle localise et capte les sons grâce au pavillon ; le CAE focalise, amplifie et dirige les ondes sonores vers le tympan. Sous la vibration de la membrane du tympan, le son est transmis à l'oreille moyenne.\\n## 2-2 L'oreille moyenne\\nTrois fonctions essentielles :\\n- +++transmission des ondes sonores à l'oreille interne+++ (chaîne tympano-ossiculaire, qui transforme les vibrations aériennes en vibrations de pression) ;\\n- +++adaptation d'impédance+++ entre le milieu aérien et le milieu liquidien de l'oreille interne ;\\n- +++protection de l'oreille interne grâce au réflexe stapédien+++.\\n## 2-3 L'oreille interne\\nRôle dans l'audition grâce à la cochlée qui transforme le signal mécanique en signal électrique ; rôle dans l'équilibre grâce au vestibule et aux canaux semi-circulaires.\"}, {\"d\": 1, \"p\": 6, \"i\": 5, \"ch\": \"a2\", \"t\": \"# ANATOMIE ET PHYSIOLOGIE DU NEZ\\nObjectif général : connaître les différentes parties du nez et des sinus.\\nObjectifs spécifiques : citer les différentes parois d'une fosse nasale ; nommer les groupes de sinus de la face ; citer au moins 3 fonctions du nez et des sinus.\\n## I- ANATOMIE DU NEZ : le nez comprend deux (2) parties\\n## 1-1 La pyramide nasale\\n[Figure peu lisible : pyramide nasale]\\nPortion qui fait saillie au niveau de la partie médiane de la face, sur laquelle se greffent muscle et peau pour délimiter deux orifices symétriques.\\n+++Forme d'une pyramide triangulaire+++ avec une base inférieure au plan des orifices narinaires, un sommet supérieur (racine du nez) et deux faces antérolatérales. Squelette ostéo-cartilagineux recouvert en dedans par une muqueuse et en dehors par des muscles et de la peau.\\n## 1-2 Les fosses nasales\\n[Figures : fosses nasales, coupe de la région nasale]\\nAu nombre de 2, séparées par une +++cloison nasale ou septum nasal+++. On distingue :\"}, {\"d\": 1, \"p\": 7, \"i\": 6, \"ch\": \"a2\", \"t\": \"- en avant : le +++vestibule nasal+++, tapissé d'un épiderme garni de poils et de glandes sébacées à mucus ;\\n- en arrière : la cavité nasale proprement dite : +++paroi externe+++ (méats et cornets : externe, moyen, interne), +++paroi supérieure+++ ou toit, +++paroi inférieure+++ ou plancher, +++paroi interne+++ = cloison nasale.\\nLa muqueuse de la cavité nasale est de deux types :\\n- muqueuse respiratoire : occupe presque toute la fosse nasale ;\\n- muqueuse olfactive : partie supérieure de la fosse nasale, avec des éléments olfacto-sensoriels.\\nCloison nasale : squelette fait d'os en arrière et de cartilage en avant, essentiellement le cartilage septal dont l'altération retentit sur la morphologie du nez.\\n## II- PHYSIOLOGIE\\n- Fonction olfactive : le nez est l'organe de l'odorat.\\n- Fonction respiratoire : +++le nez est la seule voie physiologique de la respiration+++ ; ventilation et conditionnement de l'air inspiré (réchauffement, humidification, purification).\\n- Fonction de protection : appareil muco-ciliaire et sécrétions nasales contenant des facteurs de défense.\\n- Fonction phonatoire : le nez influence le timbre de la voix.\"}, {\"d\": 1, \"p\": 8, \"i\": 7, \"ch\": \"a3\", \"t\": \"# ANATOMIE ET PHYSIOLOGIE DES SINUS\\n[Figures : sinus de la face]\\nLes sinus sont des cavités creusées au sein du massif facial. Deux groupes : sinus antérieurs et sinus postérieurs.\\n- +++Sinus antérieurs : sinus maxillaire, frontal et cellules ethmoïdales antérieures+++. Points communs : ils entourent la cavité de l'orbite et +++se drainent tous dans le méat moyen+++ (fosse nasale).\\n- +++Sinus postérieurs : sinus ethmoïdal postérieur et sinus sphénoïdal.+++\\nIls jouent un rôle :\\n- dans le conditionnement de l'air intra-sinusien ;\\n- dans la ventilation ;\\n- dans le drainage des sécrétions.\"}, {\"d\": 1, \"p\": 9, \"i\": 8, \"ch\": \"a4\", \"t\": \"# ANATOMIE ET PHYSIOLOGIE DU PHARYNX\\nObjectif général : reconnaître les différentes parties du pharynx.\\nObjectifs spécifiques : énumérer les étages du pharynx ; décrire l'oropharynx ; citer les fonctions du pharynx.\\n## 1-1 Définition du pharynx\\n+++Conduit musculo-membraneux qui s'étend de la base du crâne au bord inférieur de la 6e vertèbre cervicale (C6)+++ (ou bord supérieur de C7) et se continue par l'œsophage.\\nIl mesure +++13 cm de longueur environ+++ ; 5 cm de large en position nasale ; 4 cm en position orale ; 4 cm en position laryngée.\\n## 1-2 Anatomie : trois étages\\n- Tiers supérieur : +++nasopharynx ou cavum ou rhinopharynx+++, situé en arrière des fosses nasales et du voile du palais ; communique avec les fosses nasales par les +++choanes+++.\\n- Tiers moyen : +++oropharynx+++ (bucco-pharynx, mésopharynx), en arrière de la cavité buccale, au-dessus du larynx et de l'hypopharynx.\\n[Figures : coupe sagittale médiane tête et cou ; cavité buccale ouverte]\"}, {\"d\": 1, \"p\": 10, \"i\": 9, \"ch\": \"a4\", \"t\": \"## L'oropharynx comprend :\\n- la région amygdalienne (amygdales palatines, piliers antérieur et postérieur) ;\\n- le voile du palais mou ;\\n- la base de langue et les vallécules ;\\n- les parois oropharyngées postérieure et latérale.\\n- Tiers inférieur : +++hypopharynx+++, qui constitue avec le larynx le +++carrefour aérodigestif+++ et se termine à la bouche œsophagienne.\\n## 1-3 Physiologie : fonctions fondamentales\\n- la ventilation ;\\n- la déglutition ;\\n- la phonation (résonateur) ;\\n- l'élaboration des défenses immunitaires par ses nombreuses formations lymphoïdes ;\\n- la digestion par ses annexes : les glandes salivaires ;\\n- le goût par les papilles linguales ;\\n- l'audition.\"}, {\"d\": 1, \"p\": 11, \"i\": 10, \"ch\": \"a5\", \"t\": \"# ANATOMIE ET PHYSIOLOGIE DU LARYNX ET DE LA TRACHÉE\\n## II- Le larynx – 3-1 Anatomie\\n[Figure : le larynx, vues antérieure et postérieure]\\nOrgane du système respiratoire situé dans la gorge entre le pharynx et la trachée, constituant la partie supérieure de la trachée.\\nSon squelette comprend cinq principaux cartilages :\\n- +++cartilage thyroïde+++ en forme de livre ouvert en arrière, relief antérieur plus prononcé chez l'homme (pomme d'Adam) ;\\n- +++cartilage épiglottique+++ impliqué dans la déglutition et la respiration par ouverture et fermeture du larynx ;\\n- +++cartilages aryténoïdes+++ articulés avec le bord supérieur du cricoïde, sur lesquels s'insèrent les deux cordes vocales ; leurs mouvements déterminent la position et la tension des cordes ;\\n- +++cartilage cricoïde+++ : base du larynx.\\nLes cartilages sont reliés par des ligaments et entourés de membranes qui assurent la rigidité du larynx.\\n- Tenseur des cordes vocales (crico-thyroïdien) ; dilatateur de la glotte (crico-aryténoïdien latéral, selon le cours) ; ils rapprochent les cordes vocales pour la phonation.\\nTous ces muscles sont sous la commande des +++nerfs récurrents droit et gauche (branches du pneumogastrique)+++ sauf le crico-\"}, {\"d\": 1, \"p\": 12, \"i\": 11, \"ch\": \"a5\", \"t\": \"thyroïdien, tenseur des cordes vocales, +++innervé par le nerf laryngé supérieur+++.\\n[Figure : vue de la glotte]\\n## 3-2 Fonction du larynx\\n- Rôle dans la +++déglutition+++ : empêcher le passage d'aliments ou de liquides dans la trachée et les poumons ; l'épiglotte ferme le larynx et les cordes vocales se rapprochent.\\n- Rôle +++respiratoire+++ : laisse passer l'air (glotte ouverte).\\n- Rôle +++phonatoire+++ : émission et modulation des sons (glotte fermée, cordes plus ou moins tendues).\\n## III- La trachée\\n[Figure : trachée, faces antérieure et postérieure]\\nDéfinition : conduit fibro-cartilagineux qui fait suite au larynx, formé de plusieurs +++anneaux trachéaux+++ séparés par du tissu fibro-musculaire.\\nAnatomie : limitée en haut par le larynx, en bas par deux orifices qui s'abouchent aux bronches souches. Tube cylindrique aplati en arrière (muscle T) ; +++longueur de la trachée cervicale 5 à 6 cm chez l'adulte, 4 cm chez l'enfant+++. Longueur variable selon la position de la tête et la respiration (élasticité). Le calibre est également variable :\"}, {\"d\": 1, \"p\": 13, \"i\": 12, \"ch\": \"a5\", \"t\": \"- +++6 mm chez l'enfant de 1 à 4 ans+++ ;\\n- 8 mm de 4 à 8 ans ;\\n- 10 mm de 8 à 12 ans ;\\n- +++12 mm chez l'adulte+++.\\n## 2-3 Physiologie\\nLa trachée n'est pas un tube inerte : muqueuse de type respiratoire, appareil musculaire important ; trois fonctions essentielles :\\n- +++fonction ciliaire+++ : les cils de l'épithélium assurent le drainage des sécrétions ;\\n- +++fonction sécrétoire+++ : film fin de mucus (appelé « surfactant » dans le cours) qui protège les voies respiratoires ;\\n- +++fonction tonique+++ : permet au larynx de monter et descendre (surtout lors de la déglutition).\"}, {\"d\": 1, \"p\": 14, \"i\": 13, \"ch\": \"b1\", \"t\": \"# LES OTALGIES\\nObjectif général : distinguer une otalgie vraie d'une otalgie fausse.\\nObjectifs spécifiques : définir l'otalgie ; énumérer les causes d'otalgie.\\n## I- Définition\\n+++L'otalgie est une douleur de l'oreille.+++\\n- +++Primitive ou vraie+++ : liée à une lésion de l'oreille, encore appelée +++otodynie+++.\\n- +++Secondaire ou fausse+++ : en rapport avec une lésion extra-auriculaire de voisinage, appelée +++otalgie réflexe+++.\\n## II- Examen clinique\\nD'abord l'examen de l'oreille par +++otoscopie+++ (pavillon, CAE, tympan), puis le reste de l'examen ORL : oropharyngoscopie, rhinoscopie antérieure et postérieure. Étendu à : cavité buccale (denture, langue, gencive), oropharynx et nasopharynx, hypopharynx et larynx, articulation temporo-mandibulaire, sinus, paires crâniennes, œsophage.\\n+++Le traitement de l'otalgie est le traitement de sa cause.+++\\n## III- Étiologies\\n## 3-1 Otalgies primitives (otodynies, otalgies vraies) – Oreille externe\\n- Bouchon de cérumen ou épidermique ;\\n- corps étranger du CAE ;\\n- infection : otite externe, furoncle du conduit, eczéma surinfecté, périchondrite du pavillon, othématome, zona.\"}, {\"d\": 1, \"p\": 15, \"i\": 14, \"ch\": \"b1\", \"t\": \"- Traumatismes : plaie du conduit, fracture du conduit osseux.\\n- Tumeurs : malignes du conduit (otalgie précoce et intense) ; bénignes.\\n- Tympan : myringite aiguë virale ; traumatisme du tympan.\\n## 3-1-2 Oreille moyenne\\n- Otites moyennes aiguës suppurées, barotraumatisme et leurs complications ;\\n- otites moyennes chroniques simples ou cholestéatomateuses ;\\n- cancers de l'oreille moyenne ; traumatismes de l'oreille moyenne.\\n## 3-2 Otalgies secondaires (réflexes, fausses)\\n- Cavité buccale : +++origine dentaire (caries, accidents de la dent de sagesse) avec très souvent otalgie homolatérale+++ ; glossites, stomatites ; cancers de la langue.\\n- Oropharynx : pharyngites aiguës, amygdalites, angines ; phlegmons amygdaliens et rétro-pharyngés ; apophyses styloïdes anormalement longues ; cancers.\\n- Larynx et hypopharynx (sinus piriforme) : cancers.\\n- Articulation temporo-mandibulaire : arthrite, dysfonctionnement.\\n- Sinusites aiguës ou chroniques en poussée.\\n- Causes œsophagiennes : corps étranger, œsophagite, cancer, hernie hiatale et reflux gastro-œsophagien.\\n- Autres : thyroïdite aiguë, lésion du rachis cervical.\"}, {\"d\": 1, \"p\": 16, \"i\": 15, \"ch\": \"b2\", \"t\": \"# LES SURDITÉS\\nObjectif général : être capable de prendre en charge une surdité.\\nObjectifs spécifiques : définir la surdité ; citer les différents types ; énumérer les causes de chaque type.\\n## I- Définition\\n+++Trouble de l'audition sans présumer l'intensité, allant de la baisse de l'acuité auditive (hypoacousie) à la disparition totale de l'ouïe (cophose).+++\\n## II- Classification\\n## 2-1 Surdités de transmission\\n+++Altération de l'oreille externe ou de l'oreille moyenne.+++\\nOreille externe :\\n- bouchon de cérumen : les glandes cérumineuses du CAE sécrètent une substance jaunâtre molle ; +++les nettoyages au coton-tige entraînent l'accumulation de cérumen qui devient noirâtre et dur+++ ;\\n- bouchon épidermique : lamelles de desquamation de la peau du CAE ;\\n- corps étrangers du CAE ; otites externes ; ostéomes du conduit ; tumeurs bénignes et malignes ; atrésie congénitale du conduit.\\nOreille moyenne :\\n- otites moyennes aiguës ; otites moyennes chroniques ;\\n- traumatismes de l'oreille moyenne (spontanés et chirurgicaux) ; tumeurs de l'oreille moyenne.\"}, {\"d\": 1, \"p\": 17, \"i\": 16, \"ch\": \"b2\", \"t\": \"## 2-2 Surdités de perception\\n+++Altération de l'oreille interne. C'est une surdité à tympan normal.+++\\n- Surdités toxiques : +++dominées par les antibiotiques de la famille des aminosides+++ ; à redouter en cas d'association à une insuffisance rénale.\\n- +++Presbyacousie+++ ou surdité de la sénescence : vers 50 à 60 ans.\\n- Surdités de perception traumatiques : sonores, opératoires et accidentelles.\\n- Surdités d'origine congénitale.\\n## Surdités mixtes (numérotée « 2-1 » par erreur dans le cours)\\nL'atteinte est au niveau des deux appareils.\\nSurdités congénitales ou héréditaires : évolution discrète à la naissance, s'aggravent avec le temps.\\n+++Symptômes à surveiller de 0 à 3 mois : absence de sursaut aux bruits forts, sommeil imperturbable, cri modifié.+++\\n## Points importants\\nDiminution de l'acuité auditive légère, moyenne, profonde ou sévère ; groupes : transmission (oreille externe et moyenne), perception (oreille interne), mixtes (les deux).\"}, {\"d\": 1, \"p\": 18, \"i\": 17, \"ch\": \"b3\", \"t\": \"# LES ACOUPHÈNES\\nObjectif général : appréhender les acouphènes.\\nObjectifs spécifiques : définir les acouphènes ; décrire les formes cliniques en insistant sur l'étiologie.\\n## 1. Définition\\n+++Bruits que l'on entend dans une oreille ou dans sa tête sans qu'ils aient été émis par une source extérieure ; perçus seulement par le sujet malade.+++\\n## 2. Aspect clinique\\n- Souvent d'origine pathologique ; permanents, intermittents ou temporaires.\\n- Selon le son perçu : +++tintement, chuintement, bourdonnement, sifflement+++.\\n- Uni- ou bilatéraux.\\n## 3. Étiologies\\n- Surdité brusque ;\\n- traumatisme auditif (concert, boîte de nuit, pétard) ;\\n- traumatisme crânien ;\\n- hypertension artérielle ;\\n- anémie sévère et insuffisance rénale ;\\n- stress ou dépression mentale.\\n## 4. Traitement d'urgence\\n- +++Vasodilatateurs, corticoïdes, oxygénothérapie+++ ;\\n- écouter de la musique pour oublier ses acouphènes ;\\n- traitement étiologique.\"}, {\"d\": 1, \"p\": 19, \"i\": 18, \"ch\": \"c1\", \"t\": \"# LES ÉPISTAXIS\\nObjectif général : apprécier le type d'épistaxis pour une prise en charge.\\nObjectifs spécifiques : définir l'épistaxis ; citer au moins cinq causes ; énumérer la CAT devant une épistaxis bénigne ; indiquer l'attitude devant une épistaxis grave.\\n## I- Définition\\n+++Saignement d'origine endonasale+++, tantôt antérieur extériorisé par la narine, tantôt postérieur extériorisé dans le rhinopharynx, ou mixte. +++C'est une urgence fréquente.+++\\n+++Dans 90 % des cas, il provient de la tache vasculaire (Kisselbach, zone sur-vascularisée) sur la cloison nasale, à un centimètre environ de l'entrée narinaire.+++\\nÉpistaxis bénigne : saignement minime ou moyen. Épistaxis grave : par son abondance ou sa répétition, avec perturbation hémodynamique.\\n## II- Causes\\n## 2-1 L'hypertension artérielle\\n+++Prendre la TA chez tout malade adulte ayant une épistaxis.+++\\n## 2-2 Causes traumatiques\\nFracture des os propres du nez ; traumatisme de la face (disjonction crânio-faciale) ; après chirurgie (rhinoseptoplastie, septoplastie, polypectomie).\\n## 2-3 Maladies hémorragiques\\nMaladie de Rendu-Osler (angiomatose hémorragique familiale) ; thrombopénies, thrombopathies, leucoses, aplasies ; hémophilie, insuffisance hépatique, fibrinolyses, CIVD ; patients sous anticoagulants ; insuffisance rénale.\"}, {\"d\": 1, \"p\": 20, \"i\": 19, \"ch\": \"c1\", \"t\": \"## 2-4 Causes tumorales\\nBénignes : angiofibromes de l'ethmoïde et de la cloison ; +++l'angiofibrome juvénile est une tumeur de l'adolescent de sexe masculin très hémorragique (fibrome nasopharyngien)+++.\\nMalignes : tumeurs malignes des fosses nasales, des sinus, du cavum ; tumeurs nerveuses des fosses nasales.\\n## 2-5 Causes infectieuses et inflammatoires\\nEnfant : rhinopharyngites aiguës, rhinosinusites à répétition. Adulte : sinusites aiguës ou chroniques, rhinites allergiques. Typhoïde ; grippe.\\n## 2-6 Autres causes\\nCorps étrangers chez l'enfant ; perforation septale avec croûte ; grossesse.\\n## III- Conduite à tenir\\n## 3-1 Épistaxis bénigne (faible abondance, sans retentissement hémodynamique)\\n- Mouchage des caillots et pulvérisation de +++lidocaïne 5 % à la naphazoline+++ ;\\n- examen complet des fosses nasales : origine du saignement sur la cloison antérieure ;\\n- +++compression bidigitale des ailes du nez pendant 10 minutes, tête penchée en avant+++, après mise en place d'un tampon de coton imbibé d'eau oxygénée ou de thrombase ;\\n- en cas d'échec : +++méchage ou tamponnement antérieur+++, mèche grasse placée en accordéon dans les deux fosses nasales ;\\n- +++mèche enlevée au plus tard 48 h après pour prévenir tout risque de nécrose septale.+++\"}, {\"d\": 1, \"p\": 21, \"i\": 20, \"ch\": \"c1\", \"t\": \"- Couverture antibiotique pour éviter une suppuration.\\n- Une fois le tamponnement effectué, vérifier par le pharynx l'arrêt total du saignement.\\n- En cas de nouvel échec ou de succès incomplet : bilan sanguin et examen en milieu spécialisé ORL.\\n## 3-2 Épistaxis de moyenne ou de grande abondance\\n+++Hospitalisation+++, prise en urgence de la +++TA+++, +++voie veineuse+++ pour corriger un éventuel choc, +++groupage+++ pour une éventuelle transfusion, +++tamponnement antérieur voire postérieur+++, avec couverture antibiotique et hémostatique par voie parentérale.\\n(Moitié inférieure de la page blanche.)\"}, {\"d\": 1, \"p\": 22, \"i\": 21, \"ch\": \"d4\", \"t\": \"# LA DYSPNÉE LARYNGÉE\\nObjectif général : reconnaître une dyspnée laryngée.\\nObjectifs spécifiques : définir la D.L ; citer au moins deux causes chez le nourrisson, l'enfant et l'adulte ; décrire les stades d'évolution de la laryngite aiguë sous-glottique.\\n## Définition\\n+++Bradypnée inspiratoire avec tirage sus-sternal, cornage et trouble de la voix.+++ +++Toute dyspnée obstructive de l'enfant est une urgence+++ car elle peut se décompenser rapidement et mettre en jeu le pronostic vital. Un examen clinique méthodique apprécie la gravité et l'étiologie probable.\\n## Causes\\nChez le nourrisson :\\n- malformation ; spasmes (contraction involontaire des muscles lisses) ; corps étrangers ;\\n- +++stridor+++ : affection bénigne du nouveau-né, inspiration bruyante aiguë sans gêne respiratoire ni cyanose.\\nChez l'enfant :\\n- +++laryngites aiguës sous-glottiques+++ ; corps étrangers méconnus ; papillomatose ou autre tumeur ; traumatisme.\\nChez l'adulte :\\n- corps étrangers ; traumatisme ; laryngites diverses ; lésions nerveuses (spasmes et paralysies) ; tumeurs bénignes et malignes.\"}, {\"d\": 1, \"p\": 23, \"i\": 22, \"ch\": \"d4\", \"t\": \"## Classification des laryngites aiguës sous-glottiques en 4 stades de gravité croissante\\n[Tableau : stades 1 à 4]\\n- État de l'enfant : calme / agité / angoissé / +++inconscient+++.\\n- Tirage : modéré / net / intense / +++absent+++ ; type : sus-sternal / sus-sternal + xiphoïdien / + intercostal.\\n- Cornage : modéré / net / intense / absent.\\n- TA : normale / normale / élevée / +++effondrée+++. Pouls : normal / accéléré / accéléré / +++filant+++.\\n- Extrémités : normales / normales / cyanose / cyanose. Rythme : bradypnée inspiratoire (stades 1-3) / +++irrégulier+++ (stade 4).\\n## C.A.T\\n+++Il ne faut jamais faire attendre un client atteint de dyspnée laryngée.+++\\nStades I et II :\\n- évaluer les signes décrits plus haut ;\\n- +++maintien en position assise, tête en hyperextension+++ ;\\n- oxygénation ; +++corticoïde en IVD+++ ;\\n- allergie ou œdème : +++1 mg d'adrénaline dans 5 ml de NaCl 0,9 % en aérosol+++ ;\\n- appeler le médecin ou évacuer le patient.\\nStades III et IV :\\n- +++intubation nasotrachéale+++ ;\\n- +++trachéotomie lorsqu'il s'agit d'un obstacle mécanique interdisant l'intubation+++.\\nDans tous les cas, traiter la cause.\"}, {\"d\": 1, \"p\": 24, \"i\": 23, \"ch\": \"b4\", \"t\": \"# LES PATHOLOGIES DE L'OREILLE EXTERNE ET DE L'OREILLE MOYENNE\\nObjectif général : reconnaître une affection de l'oreille externe ou moyenne et la prendre en charge.\\nObjectifs spécifiques : citer au moins 2 pathologies infectieuses et inflammatoires ; décrire les signes d'un furoncle du CAE, de l'otite externe diffuse et de l'OMA du nourrisson ; traiter chaque affection.\\n## II- Pathologies de l'oreille externe\\n## 2-1 Pathologies traumatiques\\n- Plaies.\\n- +++Othématome : collection de sang entre le périchondre et le cartilage du pavillon.+++\\n- Corps étrangers fréquents chez l'enfant, relevant du spécialiste : +++extraction par lavage ou au crochet, la pince est à éviter+++.\\n## 2-2 Pathologie du cérumen\\nBouchon : cérumen mou et jaunâtre qui noircit et devient dur ; +++extraction par lavage après instillation pendant quelques minutes d'un antiseptique moussant destiné à le ramollir+++.\\nManifestations : hypoacousie, bourdonnement, acouphènes ou vertiges ; oreille bouchée, pleine, pression ; irritation, prurit ou douleur du conduit.\\nRôle du cérumen : lubrifie le CAE, freine la progression des corps étrangers vers le tympan, propriétés antimicrobiennes.\\n## 2-3 Pathologie inflammatoire et infectieuse\\nEczéma de l'oreille : +++prurit souvent intense+++ ; tuméfaction rouge, éruption\"}, {\"d\": 1, \"p\": 25, \"i\": 24, \"ch\": \"b4\", \"t\": \"vésiculeuse rarement visible ou desquamation abondante. +++Évolue par poussées ; complication habituelle : surinfection réalisant une otite externe diffuse.+++\\nTraitement : nettoyage soigneux du conduit ; gouttes auriculaires antibiotique-corticoïde ; antibiotique général si surinfection ; rechercher une association mycosique.\\n## Le furoncle du conduit\\n+++Inflammation des follicules sébacés du CAE due au staphylocoque.+++ Siège dans le +++1/3 externe+++, secondaire à des traumatismes discrets (allumette, épingle à cheveux, doigts sales) ou à des déficiences du terrain.\\nSymptomatologie :\\n- +++la douleur est le signe le plus important+++ : précoce, intense, troubles du sommeil ; à la mobilisation du pavillon, à la mastication, à la pression du tragus ;\\n- hypoacousie par obstruction ; bourdonnements moins constants.\\nOtoscopie : peau du CAE infiltrée ; furoncle.\\n[Figure : furoncle du conduit]\\nTraitement : antalgique, anti-inflammatoire et +++antibiotique général (amoxicilline + acide clavulanique, oxacilline, pristinamycine)+++.\\n## L'otite externe diffuse\\n+++Infection du revêtement cutané du CAE+++, déclenchée par une +++baignade en piscine+++, un traumatisme local, ou compliquant un eczéma. Intéresse la totalité du CAE.\"}, {\"d\": 1, \"p\": 26, \"i\": 25, \"ch\": \"b4\", \"t\": \"Symptomatologie :\\n- +++otalgie exacerbée par la pression du tragus et la traction du pavillon+++ ;\\n- évolution lente : prurit, chaleur, tension, puis douleur lancinante ; +++otorrhée d'odeur fétide+++ ; hypoacousie si conduit tuméfié et plein de débris.\\nExamen : inflammation diffuse du CAE aux parois œdématiées (lumière diminuée) ; +++tympan généralement normal+++, parfois un peu rouge.\\nTraitement :\\n- nettoyage du CAE au sérum physiologique, aspiration si nécessaire ;\\n- +++gouttes antibiotique-corticoïde (Panotile, Polydexa, Colicort)+++ ;\\n- +++méchage du conduit s'il est rétréci, mèche changée quotidiennement+++ ;\\n- antalgique per os.\\n+++Perforation tympanique : seuls la rifamycine (Otofa) et la lincomycine (Lincocine) sont utilisables en instillation.+++\\n## La périchondrite aiguë\\nAtteinte inflammatoire infectieuse ou traumatique du pavillon : tuméfié, rouge, puis fistule avec pus contenant le plus souvent du +++pyocyanique+++. Traitement : antibiotique.\\n## L'otomycose\\n+++Otite externe fongique : dépôt blanchâtre associé à un prurit.+++ Antimycosiques locaux (Pevaryl 1 % lait ou lotion, Kétoderm crème…) pendant +++2 à 3 semaines+++.\\nLes malformations de l'oreille externe sont de gravité variable :\"}, {\"d\": 1, \"p\": 27, \"i\": 26, \"ch\": \"b5\", \"t\": \"- une oreille décollée.\\n## III- Pathologies de l'oreille moyenne\\nAtteintes infectieuses, inflammatoires, traumatiques ou malformatives.\\n## 3-1 Les otites moyennes aiguës du nourrisson\\nDéfinition : +++inflammation de la muqueuse des cavités de l'oreille moyenne évoluant sur moins de trois semaines.+++ Les OMA microbiennes constituent la majorité des otites de l'enfant. +++Elle survient la plupart du temps au décours d'une rhinopharyngite.+++\\nGermes : +++Haemophilus influenzae, Streptococcus pneumoniae, Moraxella catarrhalis, mais le plus souvent virale.+++\\nSignes cliniques : fièvre, diarrhée, pleurs inexpliqués, vomissements, rhinite aiguë, +++porte le doigt à l'oreille+++.\\n+++Le diagnostic repose sur l'otoscopie.+++ Le CAE doit être bien nettoyé sans traumatisme.\\n[Figures : aspects du tympan]\\n- +++Otite congestive+++ : tympan rouge et épaissi, hypervascularisation du manche du marteau.\\n- +++OMA suppurée collectée+++ : tympan opaque, terne, +++bombé+++ ; reliefs du manche du marteau peu visibles.\\n- +++OMA suppurée perforée+++ : le pus s'écoule, parfois de façon pulsatile, par une perforation ponctiforme ou linéaire postérieure.\"}, {\"d\": 1, \"p\": 28, \"i\": 27, \"ch\": \"b5\", \"t\": \"+++Chez le nourrisson, les otites sont bilatérales dans plus de la moitié des cas.+++\\nFaire un examen digestif à la recherche du pli cutané de déshydratation.\\nDiagnostic différentiel : otite externe, otite séromuqueuse, otite moyenne chronique.\\nÉvolution : bien traitée, favorable (apyrexie, s'alimente, prend du poids).\\nComplications :\\n- OMA récidivantes : +++si hypertrophie des végétations adénoïdes, adénoïdectomie+++ ;\\n- mastoïdites aiguës ; paralysies faciales otitiques ; méningite.\\n## Conduite à tenir\\n- Désobstruction nasale par un vasoconstricteur +++de moins de 5 jours+++ ;\\n- désinfection rhinopharyngée par solution physiologique ;\\n- +++antibiotique (amoxicilline + acide clavulanique) 80 à 100 mg/kg/jour+++ ;\\n- +++Célestine solution 10 gouttes/kg/jour+++ ;\\n- +++paracentèse au stade suppuré collecté+++ ;\\n- prévention : limiter les infections naso-sinusiennes (hygiène nasale, sérum physiologique, mouchage) ; rechercher et traiter les allergies respiratoires et alimentaires ; +++vaccination contre le pneumocoque et l'Haemophilus influenzae+++.\"}, {\"d\": 1, \"p\": 29, \"i\": 28, \"ch\": \"c2\", \"t\": \"# LES RHINITES\\nObjectif général : assurer la liberté des fosses nasales.\\nObjectifs spécifiques : décrire les signes cliniques d'une rhinite allergique ; citer au moins trois causes de rhinite.\\n## I- Définition\\n+++Les rhinites sont des inflammations des fosses nasales.+++ L'interrogatoire (durée, caractère infectieux, épidémique, facteurs déclenchants, périodicité, uni- ou bilatéralité) et l'examen de la cavité nasale (septum, polypes, œdème, sécrétions séreuses ou purulentes) permettent la classification.\\n## II- Classification\\n## 2-1 Rhinites allergiques\\n+++Triade brutale : obstruction nasale, éternuements en salve, rhinorrhée aqueuse.+++\\n- +++Intermittentes : moins de 4 jours par semaine ou moins de 4 semaines consécutives par an.+++\\n- +++Persistantes : plus de 4 jours par semaine et plus de 4 semaines dans l'année.+++\\nChacune est divisée en deux groupes selon l'intensité de la gêne.\"}, {\"d\": 1, \"p\": 30, \"i\": 29, \"ch\": \"c2\", \"t\": \"+++Formes modérées+++ : le patient ne présente aucun des symptômes suivants : troubles du sommeil ; diminution des activités quotidiennes, de loisirs ou sportives ; diminution de l'activité professionnelle ou scolaire ; symptômes invalidants.\\n+++Formes sévères+++ : au moins un de ces symptômes.\\nSoit 4 formes : intermittente modérée, intermittente sévère, persistante modérée, persistante sévère.\\n## 2-2 Pathologies infectieuses\\nVirales, bactériennes, mycosiques, parasitaires : +++aiguës si symptômes < 12 semaines, chroniques au-delà de 12 semaines+++.\\n## 2-4 Rhinites médicamenteuses (pas de « 2-3 » dans le cours)\\nAspirine, réserpine, guanéthidine, inhibiteurs de l'enzyme de conversion. +++Les vasoconstricteurs au long cours et à forte dose retentissent sur la vasomotricité de la muqueuse nasale.+++\\n## 2-5 Rhinites des troubles endocriniens\\nHyperthyroïdie, acromégalie ; +++3e trimestre de la grossesse+++ (œstrogènes les plus élevés).\\n## 2-6 Rhinites inflammatoires non allergiques\\n+++Éosinophiles > 20 % dans les sécrétions et enquête allergique négative : NARES+++ (rhinite non allergique à éosinophiles).\"}, {\"d\": 1, \"p\": 31, \"i\": 30, \"ch\": \"c2\", \"t\": \"Il y a aussi les anomalies induites par des produits chimiques ou des conditions climatiques ou environnementales.\\n## 2-7 Rhinites idiopathiques (étiologie non encore précisée)\\n## Traitement\\n- libérer les fosses nasales par mouchage ;\\n- +++vasoconstricteur de courte durée+++ ;\\n- lavage nasal pour désinfecter ;\\n- +++antihistaminique+++ contre l'allergie ;\\n- +++éviction de l'allergène+++ ;\\n- lutter contre les symptômes invalidants.\\n(Moitié inférieure de la page blanche.)\"}, {\"d\": 1, \"p\": 32, \"i\": 31, \"ch\": \"c3\", \"t\": \"# LES SINUSITES AIGUËS\\nObjectifs spécifiques : décrire le tableau clinique d'une sinusite maxillaire aiguë ; donner son traitement.\\n## Définition\\n+++Atteinte infectieuse de la muqueuse des sinus de la face dont la durée d'évolution est de moins de trois semaines.+++ Au cours d'une rhinite, d'un épisode grippal, parfois après un bain en piscine.\\nGermes : Haemophilus influenzae, S. pneumoniae, S. aureus, anaérobies.\\n## 1-1 La sinusite maxillaire aiguë\\n+++La plus fréquente+++, souvent secondaire à un coryza, une infection virale des VAS ou un bain. Germes : H. influenzae, pneumocoque, staphylocoque doré. +++Habituellement unilatérale+++ ; si tous les sinus homolatéraux sont atteints : +++pansinusite aiguë+++.\\nTableau caractéristique :\\n- +++douleur faciale unilatérale, sous-orbitaire, pulsatile, augmentée par la position penchée en avant et la toux+++ ;\\n- céphalée diffuse ; obstruction nasale ;\\n- rhinorrhée purulente parfois striée de sang du côté de la douleur ;\\n- +++cacosmie+++ subjective ; +++anosmie+++.\\nExamen après rétraction de la muqueuse : +++pus au niveau du méat moyen+++ ; muqueuse inflammatoire, cornets tuméfiés ; douleur à la pression du nerf sous-orbitaire.\"}, {\"d\": 1, \"p\": 33, \"i\": 32, \"ch\": \"c3\", \"t\": \"+++La radiographie en incidence de Blondeau montre une opacité constante du sinus maxillaire.+++\\n## Traitement\\n- décongestionner les ostiums (lavage du nez) ;\\n- antalgiques ;\\n- +++antibiothérapie générale pendant 10 jours+++ : amoxicilline-acide clavulanique, C3G (Orelox, Texodil) ou pristinamycine (Pyostacine) ;\\n- +++corticothérapie en cure courte de 5 jours à 0,5–1 mg/kg/j (Cortancyl)+++ ;\\n- soins locaux : lavage au sérum physiologique ; antibiotique, anti-inflammatoire et antalgique en aérosol sonique ;\\n- antihistaminique +++après+++ le traitement antibiotique.\\n+++Ce traitement bien conduit évitera le passage à la chronicité.+++\"}, {\"d\": 1, \"p\": 34, \"i\": 33, \"ch\": \"c4\", \"t\": \"# LES VÉGÉTATIONS ADÉNOÏDES\\nObjectifs spécifiques : énumérer les signes cliniques ; citer au moins trois complications.\\n## I- Définition\\n+++Hypertrophie du tissu lymphoïde de la paroi postéro-supérieure du rhinopharynx due aux infections respiratoires répétées : hypertrophie de l'amygdale pharyngée de Luschka.+++\\n## 2-1 Signes cliniques\\n+++Obstruction nasale bilatérale+++ entraînant : respiration buccale ; ronflement nocturne ; troubles du sommeil.\\n+++Rhinorrhée muco-purulente = surinfection adénoïdienne.+++\\n## 2-2 Examen clinique\\nEn obstruant fermement la bouche du nourrisson, on teste la perméabilité nasale : des végétations obstructives rendent la respiration nasale impossible. Mucopus sur la paroi postérieure du pharynx = infection adénoïdienne.\\n## 2-3 Signes radiologiques\\n+++Cliché de profil du cavum en inspiration et bouche fermée+++ : l'espace clair normal entre les végétations et le voile du palais est comblé.\\n## III- Complications\\n3-1 Tubotympaniques : +++otites moyennes aiguës récidivantes+++ ; otites séro-muqueuses.\"}, {\"d\": 1, \"p\": 35, \"i\": 34, \"ch\": \"c4\", \"t\": \"3-2 Laryngo-trachéo-bronchiques : laryngites aiguës sous-glottiques à répétition ; trachéites récidivantes (toux sèche) ; bronchopneumopathies récidivantes traînantes.\\n3-3 Rhinosinusiennes : rhinosinusites récidivantes ; +++ethmoïdite aiguë+++ ; adénites cervicales aiguës ; détresse respiratoire aiguë du nouveau-né et du nourrisson.\\n## IV- Traitement\\n+++Adénoïdectomie si rhonchopathie invalidante avec apnée du sommeil.+++\\n(Numéro de page imprimé illisible ; moitié inférieure blanche.)\"}, {\"d\": 2, \"p\": 1, \"i\": 35, \"ch\": \"d1\", \"t\": \"# LES RHINOPHARYNGITES\\nObjectif général : soigner une rhinopharyngite non compliquée.\\nObjectifs spécifiques : énumérer les signes cliniques ; décrire l'examen clinique ; donner la CAT ; citer au moins trois complications.\\n## I- Définition\\n+++Les rhinopharyngites aiguës de l'enfant sont les plus fréquentes. Inflammation aiguë de la muqueuse des fosses nasales et du rhinopharynx, le plus souvent d'origine virale.+++\\n## 2-1 Signes de début\\n- +++Fièvre brutale souvent élevée (39 à 40 °C)+++ ; irritabilité, agitation ; parfois vomissements ou diarrhée ; adénopathies cervicales bilatérales.\\n- Signes rhinologiques : +++obstruction nasale bilatérale+++ ; rhinorrhée d'abord séreuse puis muco-purulente bilatérale ; éternuements.\\n- Signes oculaires fréquents : rougeur conjonctivale, larmoiement, sécrétion purulente à l'angle interne.\\n- Signes laryngo-trachéaux : toux d'irritation rauque ; cri modifié.\\n## 2-2 Examen clinique\\nRhinoscopie : muqueuse nasale très rouge ; obstruction par du +++mucopus+++ (mucus jaunâtre contenant polynucléaires et macrophages).\"}, {\"d\": 2, \"p\": 2, \"i\": 36, \"ch\": \"d1\", \"t\": \"Oropharyngoscopie : muqueuse très rouge surtout au niveau des piliers du voile et des amygdales. +++Otoscopie : congestion de la membrane tympanique.+++\\n## III- Traitement\\nSoins locaux : +++désinfection rhinopharyngée pluriquotidienne au sérum physiologique+++ ; aspiration des sécrétions (mouche-bébé) ; grand enfant : éducation au mouchage, lutter contre le reniflement.\\nSoins généraux : acide acétylsalicylique 80 mg/kg/jour (anti-inflammatoire, antipyrétique, antalgique) [notion datée : l'aspirine est aujourd'hui évitée chez l'enfant].\\n+++Dans une rhinopharyngite non compliquée, l'antibiothérapie est inutile.+++\\n## IV- Évolution\\n+++Guérison complète habituellement en 5 jours.+++ Surveillance régulière pour dépister une complication :\\n- +++otite moyenne aiguë, la plus fréquente+++ ;\\n- laryngite aiguë sus-glottique ou trachéo-bronchites ;\\n- adénophlegmon du cou ou phlegmon rétro-pharyngé ;\\n- sinusite maxillaire, ethmoïdite aiguë.\\nTraitement (en cas de complication) : désinfection au sérum physiologique ; anti-inflammatoire et +++antibiotique (amoxicilline, amoxicilline + acide clavulanique) pendant 8 jours+++ ; contrôle une semaine après.\"}, {\"d\": 2, \"p\": 3, \"i\": 37, \"ch\": \"d2\", \"t\": \"# LES PHARYNGITES\\n(Chapitre absent du sommaire imprimé.)\\nDéfinition : +++inflammation de la gorge ou du pharynx liée à une bactérie type streptococcique, à un virus ou à une cause fongique.+++ Affection bénigne la plupart du temps ; peut atteindre fosses nasales, amygdales. Types : aiguë, chronique.\\n+++Pharyngite aiguë : dure de quelques jours à une semaine ; d'origine infectieuse surtout virale.+++\\nSymptômes :\\n- +++odynophagie+++ (douleur à la déglutition) ; +++dysphonie+++ (enrouement) ;\\n- fièvre modérée à 38 °C ; parfois céphalées, asthénie ; ganglions cervicaux ; toux parfois persistante ;\\n- rhinite associée (obstruction, rhinorrhée muco-purulente) : on parle de rhinopharyngite.\\nCauses de la rhinopharyngite : presque toutes infectieuses, +++virales dans 90 % des cas+++ ; traitement symptomatique ; +++antibiotiques inutiles et déconseillés (résistance)+++.\\nOropharyngoscopie : inflammation ; un +++TROD (test rapide d'orientation diagnostique)+++ détermine le germe.\\nFacteurs de risque : cigarette ou fumée du tabac ; alcool en excès ;\"}, {\"d\": 2, \"p\": 4, \"i\": 38, \"ch\": \"d2\", \"t\": \"facteurs environnementaux (poussière, air trop sec ou trop froid, climatisation, gouttes nasales répétées).\\n## La pharyngite chronique\\n+++S'installe progressivement et dure plus de trois semaines+++ ; symptômes moins marqués, localisés à la gorge ; +++fièvre seulement en cas de surinfection+++.\\n- sécheresse constante de la gorge ; raclage ; douleur pharyngée ;\\n- +++odynodysphagie+++ : difficulté douloureuse à avaler salive, nourriture ou liquide.\\nCauses : +++plus fréquente chez l'adulte+++ : tabagisme actif et passif, alcool, environnement, rhinite, rhinosinusite chronique, RGO, métier d'enseignant, de chanteur.\\nDiagnostic : interrogatoire ; oropharyngoscopie ; palpation cervicale (adénopathies) ; prélèvement de gorge (germe bactérien, viral ou mycosique).\\nÉvolution : +++provoquée par une bactérie dans 30 % des cas : le streptocoque bêta-hémolytique du groupe A+++. Complications :\\n- abcès péri-pharyngé ; otites moyennes ; sinusites ;\"}, {\"d\": 2, \"p\": 5, \"i\": 39, \"ch\": \"d2\", \"t\": \"- laryngites ; trachéo-bronchites ; pneumonies ;\\n- +++glomérulonéphrite aiguë post-streptococcique+++ ;\\n- +++rhumatisme articulaire aigu+++.\\nTraitement : lavage de nez et mouchage ; boissons chaudes ; sprays, paracétamol ou antipyrétique ; +++antibiotiques si origine bactérienne+++.\\n## La pharyngite mycosique\\nSensations de brûlures ou de coton dans la bouche, dysphagies, parfois agueusie, sécheresse buccale, petits saignements. +++Plaques blanc crème à l'examen.+++\\nTraitement : antifongiques : +++nystatine (Mycostatine) en comprimé à sucer+++, amphotéricine (Fungizone) ou miconazole (Daktarin) en gel.\\n(Moitié inférieure de la page blanche.)\"}, {\"d\": 2, \"p\": 6, \"i\": 40, \"ch\": \"d3\", \"t\": \"# LES ANGINES OU AMYGDALITES AIGUËS\\nObjectif général : prendre en charge une angine.\\nObjectifs spécifiques : énumérer les germes ; décrire les signes cliniques et paracliniques ; citer 3 complications.\\n## I- Définition\\n+++Inflammation de l'oropharynx et des amygdales palatines.+++\\n## II- Étiopathogénie\\n+++Streptocoque bêta-hémolytique du groupe A+++ (écrit « B hémolytique » dans le cours), staphylocoque, pneumocoque, Haemophilus influenzae. +++Surtout les adolescents et les adultes jeunes.+++\\n## III- Signes cliniques\\n- frissons ; irritation de la gorge ; douleur pharyngée ;\\n- +++odynophagie irradiant vers l'oreille : otalgie réflexe+++ ;\\n- fièvre élevée, céphalées, douleurs articulaires, asthénie.\\nExamen ORL : +++amygdales hypertrophiées recouvertes d'un enduit blanchâtre : angine érythémato-pultacée+++. Adénopathies cervicales sensibles et mobiles.\\n+++Sans traitement : phlegmon péri-amygdalien, complication la plus courante.+++\"}, {\"d\": 2, \"p\": 7, \"i\": 41, \"ch\": \"d3\", \"t\": \"[Figure : aspect de l'angine]\\n## IV- Signes biologiques\\n- NFS : +++hyperleucocytose à polynucléaires+++.\\n- Prélèvement de gorge pour identifier le germe (streptocoque bêta-hémolytique du groupe A) mais +++pas indispensable+++.\\n## V- Traitement\\n- +++Pénicillinothérapie : 3 à 4 millions d'unités par jour pendant 8 jours+++ ;\\n- acide acétylsalicylique ;\\n- antiseptiques locaux pharyngés ;\\n- repos au lit.\"}, {\"d\": 2, \"p\": 8, \"i\": 42, \"ch\": \"d5\", \"t\": \"# LES CORPS ÉTRANGERS DES VOIES AÉRO-DIGESTIVES\\nObjectif général : reconnaître un corps étranger dans la sphère ORL.\\nObjectifs spécifiques : citer au moins trois CE ; indiquer le motif de consultation de chaque voie ; décrire la CAT.\\nIntroduction : orifices de la face fréquemment siège de pénétrations. +++Accident relativement fréquent chez l'enfant, à l'évolution parfois catastrophique+++ (tendance à porter à la bouche). Chez l'adulte : surtout CE alimentaires (arête, os) et bol alimentaire trop gros et mal mastiqué.\\n## I- Définition\\n+++Présence d'un objet ou d'un être vivant dans un endroit inhabituel.+++\\n## 2-1 CE des fosses nasales\\nVolontaires : mousse de matelas, craie, boulette de papier, gomme, perle, maïs, haricot, arachide… Involontaires : balle, +++mèche oubliée+++.\\nMotif de consultation : +++obstruction nasale avec rhinorrhée muco-purulente UNILATÉRALE+++ ; odeur nauséabonde ; découverte d'un objet.\\nCAT : interrogatoire (caractéristiques et existence réelle du CE) ;\"}, {\"d\": 2, \"p\": 9, \"i\": 43, \"ch\": \"d5\", \"t\": \"rhinoscopie :\\n- CE visible : +++mouchage en force en fermant la narine libre, après rétraction des cornets+++ ; extraction au crochet ou à la pince ;\\n- CE invisible : évacuer le malade.\\n## 2-2 CE du pharynx\\nArête, os, épingle… Motif : douleur à l'arrière-gorge, dysphagie, odynophagie, +++au cours d'un repas+++ pour les CE alimentaires.\\nExamen : bon éclairage et abaisse-langue. +++Visible : extraire à la pince ; non visible : évacuer.+++\\n## 2-3 CE laryngés et trachéaux\\nCE laryngé :\\n- +++volumineux et plein : asphyxie aiguë rapidement mortelle+++ ;\\n- moins volumineux ou creux : enclavé, dyspnée laryngée avec tirage, voix souvent éteinte ;\\n- +++y penser devant un syndrome de pénétration survenu dans la journée et sans fièvre+++ (élimine une laryngite aiguë).\\nCE trachéal : +++souvent mobile+++ ; troubles respiratoires intermittents : quintes de toux,\"}, {\"d\": 2, \"p\": 10, \"i\": 44, \"ch\": \"d5\", \"t\": \"accès de spasmes laryngés ou de dyspnée expiratoire lors des changements de position.\\nTraitement : +++extraction par bronchoscopie au tube rigide avec optiques sous anesthésie générale+++.\\n## 2-4 CE de l'œsophage\\nPièce de monnaie, arête, os, prothèses dentaires, bol alimentaire trop volumineux et mal mastiqué.\\nTableau clinique selon l'âge :\\n- Adulte : douleur rétrosternale, odynophagie, gêne respiratoire, +++dysphagie d'apparition brutale+++ au cours d'un repas (CE alimentaire) ou de la nuit (+++prothèse dentaire+++).\\n- Enfant : troubles moins marqués ; dysphagie sans contexte infectieux.\\nDiagnostic (numéroté « 3-4-2 ») : +++la radiologie montre le CE s'il est radio-opaque+++.\\nTraitement : +++seul traitement : l'extraction dans les 2-3 jours+++, sous couverture antibiotique, antispasmodique, réhydratation parentérale (formulation ambiguë « sans couverture » dans le cours).\"}, {\"d\": 2, \"p\": 11, \"i\": 45, \"ch\": \"e1\", \"t\": \"# LAVAGE D'OREILLE\\nObjectif général : maîtriser la technique.\\nObjectifs spécifiques : définir ; citer les indications ; citer le matériel ; décrire la technique et les incidents.\\n## 1. Définition\\n+++Mise en état de vacuité du conduit auditif externe dans un but thérapeutique.+++\\n## 2. Indications\\n- +++bouchon de cérumen+++ ; +++bouchon épidermique+++ ; +++corps étranger accessible+++.\\n## 3. Matériel\\n+++Seringue stérile (50 ml)+++, poire à lavage à défaut, cupule stérile, compresses, coton, serviette ou champ, alèze imperméable, gants stériles, tablier imperméable, réniforme.\\n## 4. Technique\\n- prévenir le patient ;\\n- +++vérifier la température de l'eau en la versant sur le revers de la main+++ ;\\n- installer confortablement ; protection autour du cou et sur les épaules ;\\n- préparer la solution dans la cupule stérile ;\"}, {\"d\": 2, \"p\": 12, \"i\": 46, \"ch\": \"e1\", \"t\": \"- prélever la solution ; +++le patient maintient le haricot sous l'oreille+++ ;\\n- +++injecter doucement pour ne pas surprendre, puis augmenter la pression qui doit rester modérée+++ ;\\n- pencher la tête pour l'écoulement ; nettoyer et sécher l'oreille ;\\n- +++contrôler la vacuité du CAE par otoscopie+++ ; réinstaller ;\\n- noter bouchon/CE, aspect du liquide, réaction du patient.\\n## 5. Surveillance\\nEfficacité (CE ou bouchon dans le liquide) ; aspect du liquide ; douleur, vertiges ; perforation tympanique.\\n## 6. Critères de qualité\\nMaintien correct du nourrisson/enfant ; +++étirement correct du pavillon : CAE rectiligne+++ ; extraction du CE ou du bouchon ; absence de vertiges et nausées.\\n## 7. Prévention des risques\\nLavage des mains avant et après au savon doux ; lavage antiseptique en présence d'infection.\\n## 8. Incidents et accidents\\n- +++vertiges et nausées : eau trop froide ou trop chaude+++ ;\\n- +++douleur : arrêter le lavage+++ ;\\n- +++traumatisme : introduction trop profonde de la seringue+++.\"}, {\"d\": 2, \"p\": 13, \"i\": 47, \"ch\": \"e1\", \"t\": \"## 9. Conseils pratiques\\n- +++Ne jamais faire de lavage dans une otorrhée de l'oreille moyenne+++ : risque de surinfecter la caisse du tympan avec l'eau et les débris souillés du CAE.\\n- +++Ne jamais laver avec de l'eau froide, glacée ou chaude.+++\\n# LE LAVAGE DE NEZ\\nObjectifs : citer les indications, les intérêts ; décrire la technique.\\nPrincipe : +++faire passer un liquide légèrement salé (eau ou sérum physiologique) dans les fosses nasales pour les nettoyer et en évacuer les impuretés+++, à la pipette (sérum du commerce) ou à la seringue.\\n## II- Indications\\n- +++rhinite atrophique avec rhinorrhées purulentes et croûtes+++ ; encombrement nasal ; +++après chirurgie endonasale+++.\\n## III- But\\nDégager le nez (respiration libre).\\n## III- Intérêts\\n- prévient et soulage les symptômes des infections rhinopharyngées ;\\n- améliore le bien-être respiratoire (élimine les particules) ;\\n- limite le dépôt des allergènes ;\\n- restaure l'activité physiologique nasale : filtration, drainage, immunité.\"}, {\"d\": 2, \"p\": 14, \"i\": 48, \"ch\": \"e2\", \"t\": \"- évite que les mucosités descendent dans la gorge (raclement) et sur les bronches ;\\n- renforce les défenses (effet décongestionnant du sel) ; assainit le rhinopharynx ;\\n- redonne du grain à la voix ; prévient les refroidissements, garde sain le nerf olfactif ; aide au drainage et à la ventilation.\\n## Matériel\\n1 plateau, +++1 seringue de 60 cc+++, 1 canule, sérum physiologique froid (selon le cours), cupule stérile, gants, mouchoirs, alèse imperméable, bassin réniforme, serviette.\\n## Réalisation : nourrisson de moins de six mois\\nGeste +++indolore+++ mais désagréable. Se laver les mains ; +++dosettes de sérum physiologique à usage unique+++ : eau minérale ou du robinet déconseillées (pas assez salées, germes). Cinq étapes :\\n1. +++allonger bébé sur le dos ou sur le côté, tête maintenue sur le côté+++ pour éviter la +++fausse route+++ (passage involontaire de\"}, {\"d\": 2, \"p\": 15, \"i\": 49, \"ch\": \"e2\", \"t\": \"sérum dans les voies respiratoires) ; se faire aider si besoin ;\\n2. embout de la dosette à l'entrée de la +++narine située le plus haut+++ ;\\n3. presser la dosette en entier ; +++fermer la bouche de l'enfant+++ : le sérum ressort par l'autre narine avec les sécrétions ;\\n4. attendre que bébé ait dégluti ;\\n5. essuyer le nez avec un mouchoir jetable.\\nRépéter pour l'autre narine avec +++une autre dosette+++, tête tournée de l'autre côté.\\n+++Le lavage de nez est préférable au mouche-bébé+++, moins efficace car il débouche moins bien.\\n## Bébé à partir de six mois\\nMême technique ; possible pulvérisateur de solution saline (eau de mer). +++Sprays et solutions nasales avec vasoconstricteurs proscrits avant l'âge de 15 ans+++ (effets secondaires graves). Spray : pulvérisations sans pression trop forte ; nettoyer l'embout à l'eau chaude ; flacon à usage personnel.\\nSi seul(e), maintenir le bébé selon la technique suivante :\"}, {\"d\": 2, \"p\": 16, \"i\": 50, \"ch\": \"e2\", \"t\": \"- s'asseoir sur un lit, jambes allongées ;\\n- placer l'enfant entre ses jambes, tête au niveau des cuisses, bras sous les cuisses ;\\n- tourner la tête sur le côté, puis nettoyer.\\n## L'enfant qui sait se moucher\\nSérum physiologique ou solution à pulvériser +++sans vasoconstricteurs+++ ; l'enfant participe activement :\\n- assis, tête inclinée sur le côté ; embout dans la +++narine la plus haute+++ ;\\n- pression sur la dosette ou pulvérisation courte ; +++se moucher fort+++ ; répéter de l'autre côté.\\nLavage à la pipette ou à la seringue : +++tête à l'horizontale, tournée sur le côté+++ ; le sérum mis dans la narine du haut ressort par l'autre après la fosse nasale haute, le cavum, puis la fosse nasale basse. Puis souffler fortement par la narine basse en fermant l'autre avec le pouce.\\nIl faut d'abord tester : la première fois, possible désagrément, voire mal de tête : arrêter, réessayer le lendemain, à petites doses.\"}, {\"d\": 2, \"p\": 17, \"i\": 51, \"ch\": \"e2\", \"t\": \"## Lavage de nez chez l'adulte\\n- +++position verticale+++, tête inclinée sur le côté, embout dans la +++narine supérieure+++ ;\\n- +++pression franche+++ : le liquide s'écoule par l'autre narine ; laisser agir quelques secondes ;\\n- renouveler de l'autre côté ; puis moucher.\\n## Produits\\nEau du robinet (solutions du commerce chères) ; si doute : eau bouillie ou minérale [divergence avec le paragraphe nourrisson]. Température : +++froid/tiède = renforcement des défenses ; tiède/chaud = dilatation et dégagement+++. Sérum physiologique ; eau de mer diluée (1/3) ; eau de mer 100 %.\\n## Préparation (1 litre d'eau)\\n+++Gros sel (pas le sel fin de table, qui contient des additifs) : 2 cuillères à café par litre+++ ; option : pincée de bicarbonate ; remuer, laisser reposer 1 min.\\n## Fréquence\\n+++Cures d'une semaine tous les mois+++ ; de manière saisonnière ou en cas d'alerte.\"}, {\"d\": 2, \"p\": 18, \"i\": 52, \"ch\": \"e3\", \"t\": \"# MÉCHAGE ANTÉRIEUR OU TAMPONNEMENT ANTÉRIEUR\\nObjectif : réaliser un méchage antérieur ; décrire la technique.\\n## I- Définition\\n+++Pratiqué surtout dans les épistaxis : combler en accordéon les fosses nasales à l'aide d'une mèche, depuis les choanes jusqu'au vestibule, dans le but de faire l'hémostase.+++\\n## II- Indications\\n- +++épistaxis+++ ; contention d'une réduction des OPN (os propres du nez) ; cavoscopie ; après chirurgie (cautérisation des cornets, turbinectomie, plastie…).\\n## III- Matériel\\nPlateau ; +++spéculum de Palmer+++ ; +++pince coudée de Lubet-Barbon+++ ou de Politzer ; ciseaux droits ; miroir de Clar ; +++mèche de gaze de 2 à 3 cm de large+++ ou compresse découpée ; compresses stériles ; pulvérisateur de xylocaïne ; +++xylocaïne 5 % à la naphazoline+++ ; pommade HEC ; gants d'examen ; bavettes ; haricot ; champ ; sparadrap.\\n## Préparation psychologique\\n- rassurer ; +++l'acte n'est pas douloureux+++ ; +++sous anesthésie locale+++ ; +++déméchage dans 48 heures+++.\"}, {\"d\": 2, \"p\": 19, \"i\": 53, \"ch\": \"e3\", \"t\": \"## IV- Technique\\n- +++position assise ou demi-assise+++ ; protéger d'un champ ; haricot sous le menton ;\\n- faire moucher pour évacuer les caillots ;\\n- +++pulvérisation ou premier méchage à la xylocaïne, attendre 5 à 10 min+++ (rétracte les cornets, anesthésie les FN) ;\\n- imbiber la mèche d'hémostatique ; mettre en place le spéculum de Palmer ;\\n- saisir la mèche à 10 cm (« 10 m » dans le texte) de son extrémité et l'introduire au fond de la fosse nasale ;\\n- poursuivre tantôt vers le haut, tantôt vers le bas jusqu'à combler la FN : +++mèche tassée en accordéon+++ ;\\n- maintenir avec compresses devant le nez et sparadrap ;\\n- +++traitement général : ATB, antalgique, hémostatique+++ ;\\n- +++déméchage au bout de 48 h+++.\\n[Figure : mèche en accordéon dans la fosse nasale]\\n## Conseils de sortie\\n- FN bouchées : +++respirer par la bouche pendant 48 h+++ ;\\n- manger et boire lentement, par petites gorgées ;\\n- +++sans traitement, les FN vont se surinfecter+++ ;\\n- revenir s'il saigne à nouveau ; rassurer.\"}, {\"d\": 2, \"p\": 20, \"i\": 54, \"ch\": \"e4\", \"t\": \"# SOINS DE TRACHÉOTOMIE\\nObjectifs : citer au moins 3 indications ; citer 2 complications immédiates ; décrire l'entretien de la canule (indications et complications non développées dans le texte).\\n## I- Définition\\n+++Ouverture de la trachée cervicale afin d'y introduire une canule ; elle sert à court-circuiter les voies aériennes supérieures lors d'un obstacle.+++\\n## D- Soins post-opératoires\\n- +++aspiration des sécrétions+++ ;\\n- +++humidification de l'air inspiré+++ ;\\n- prévention de l'infection de la plaie et lutte contre l'infection broncho-pulmonaire par des soins de trachéotomie ;\\n- +++canule à changer tous les 3 jours si possible+++ ;\\n- +++sonde d'aspiration dans un bocal d'eau additionnée d'antiseptique (ex. Bétadine jaune)+++.\\n(Reste de la page blanc.)\"}], \"fiches\": [{\"id\": \"f1\", \"ch\": \"a1\", \"rub\": \"anat\", \"pg\": \"1:3\", \"f\": \"Citez les parties de l'oreille et l'appareil auquel chacune appartient.\", \"b\": \"Oreille externe (pavillon + CAE) et oreille moyenne = appareil de transmission ; oreille interne (labyrinthe) = appareil de perception.\", \"mn\": \"« EXTERNE capte, MOYENNE transmet, INTERNE perçoit. »\", \"kid\": \"L'oreille, c'est une maison : l'entrée (le pavillon et le couloir), le salon avec un petit tambour et trois minuscules os, puis la chambre secrète où le bruit devient un message pour le cerveau.\", \"ref\": \"Transmission = dehors + milieu ; perception = dedans.\", \"sch\": \"Pavillon → CAE → Tympan → Osselets → Oreille interne (cochlée) → Nerf auditif\"}, {\"id\": \"f2\", \"ch\": \"a1\", \"rub\": \"anat\", \"pg\": \"1:4,1:5\", \"f\": \"Quel est le rôle de la trompe d'Eustache ?\", \"b\": \"Conduit ostéo-cartilagineux reliant la caisse du tympan au pharynx : il aère l'oreille moyenne et équilibre la pression de part et d'autre du tympan.\", \"mn\": \"« EustachE = ÉgalisE » la pression.\", \"kid\": \"C'est un petit tuyau entre ta gorge et ton oreille : quand tu avales en avion, il s'ouvre et ton oreille arrête de « siffler ».\", \"ref\": \"Trompe = tuyau d'aération et de pression de l'oreille moyenne.\", \"sch\": \"Pharynx → Trompe d'Eustache → Caisse du tympan → Pression égale des deux côtés du tympan\"}, {\"id\": \"f3\", \"ch\": \"a1\", \"rub\": \"anat\", \"pg\": \"1:5\", \"f\": \"Quelles sont les trois fonctions de l'oreille moyenne ?\", \"b\": \"Transmission des ondes sonores (chaîne tympano-ossiculaire), adaptation d'impédance entre milieu aérien et liquidien, protection de l'oreille interne par le réflexe stapédien.\", \"mn\": \"TAP : Transmission – Adaptation – Protection.\", \"kid\": \"Le tympan et les trois petits os passent le son comme un relais, l'adaptent pour qu'il entre dans l'eau de l'oreille interne et le freinent quand il est trop fort.\", \"ref\": \"Oreille moyenne = relais + adaptateur + bouclier.\", \"sch\": \"Vibration aérienne → Tympan → Marteau → Enclume → Étrier → Liquide de l'oreille interne\"}, {\"id\": \"f4\", \"ch\": \"a1\", \"rub\": \"anat\", \"pg\": \"1:3,1:4\", \"f\": \"Où est produit le cérumen et quels sont ses rôles ?\", \"b\": \"Par les glandes cérumineuses du 1/3 externe du CAE ; il protège les parois, piège les corps étrangers, est antibactérien et élimine les débris de peau.\", \"mn\": \"Les 4 P du cérumen : Protège, Piège, Purifie, Pousse dehors les débris.\", \"kid\": \"La cire de l'oreille est comme de la colle magique : elle attrape la poussière et les petites bêtes et tue les microbes.\", \"ref\": \"Cérumen = barrière naturelle du conduit.\", \"sch\": \"Glandes du 1/3 externe → Cérumen → Piège poussières/insectes → Élimination vers l'extérieur\"}, {\"id\": \"f5\", \"ch\": \"a1\", \"rub\": \"anat\", \"pg\": \"1:5\", \"f\": \"Citez les unités fonctionnelles de l'oreille interne et leur rôle.\", \"b\": \"Cochlée → organe de Corti (audition : signal mécanique → électrique) ; vestibule → macule ; canaux semi-circulaires → crêtes ampullaires (équilibre).\", \"mn\": \"« CORTI pour l'OUÏE ; MACULE et CRÊTES pour tenir DEBOUT. »\", \"kid\": \"Dans la partie la plus profonde, l'escargot (cochlée) entend, et les petits tuyaux en anneaux t'empêchent de tomber.\", \"ref\": \"Oreille interne = audition (cochlée) + équilibre (vestibule, canaux).\", \"sch\": \"Son mécanique → Cochlée (Corti) → Signal électrique → Nerf auditif → Cerveau\"}, {\"id\": \"f6\", \"ch\": \"a2\", \"rub\": \"anat\", \"pg\": \"1:6,1:7\", \"f\": \"Citez les parois d'une fosse nasale.\", \"b\": \"Paroi externe (cornets et méats), paroi supérieure (toit), paroi inférieure (plancher), paroi interne (cloison nasale). En avant : le vestibule nasal.\", \"mn\": \"« Toit – Plancher – Cloison – Cornets » : une pièce avec un plafond, un sol, un mur commun et un mur à étagères.\", \"kid\": \"Chaque narine ouvre sur une petite pièce : un plafond, un sol, un mur du milieu (la cloison) et un mur avec des étagères (les cornets).\", \"ref\": \"4 parois : externe, supérieure, inférieure, interne.\", \"sch\": \"Narine → Vestibule → Cavité nasale (4 parois) → Choanes → Rhinopharynx\"}, {\"id\": \"f7\", \"ch\": \"a2\", \"rub\": \"anat\", \"pg\": \"1:7\", \"f\": \"Citez au moins trois fonctions du nez.\", \"b\": \"Olfactive (odorat), respiratoire (seule voie physiologique ; réchauffe, humidifie, purifie l'air), protection (appareil muco-ciliaire, sécrétions), phonatoire (timbre de la voix).\", \"mn\": \"ORPP : Odorat – Respiration – Protection – Phonation.\", \"kid\": \"Ton nez sent, chauffe et nettoie l'air comme un petit climatiseur, et il change le son de ta voix.\", \"ref\": \"Le nez sent, conditionne l'air, protège et colore la voix.\", \"sch\": \"Air froid et sale → Fosses nasales → Réchauffé + humidifié + purifié → Poumons\"}, {\"id\": \"f8\", \"ch\": \"a2\", \"rub\": \"anat\", \"pg\": \"1:6,1:7\", \"f\": \"Décrivez la pyramide nasale, la cloison et les muqueuses nasales.\", \"b\": \"Pyramide triangulaire ostéo-cartilagineuse ; cloison : os en arrière, cartilage septal en avant ; muqueuse respiratoire (presque toute la FN) et olfactive (partie supérieure).\", \"mn\": \"« L'odeur monte » : la muqueuse olfactive est en haut.\", \"kid\": \"Le nez a une charpente d'os et de cartilage ; tout en haut il y a un petit coin spécial pour sentir.\", \"ref\": \"Pyramide + 2 fosses ; muqueuse respiratoire partout, olfactive en haut.\", \"sch\": \"Squelette ostéo-cartilagineux → Muqueuse en dedans → Muscles et peau en dehors\"}, {\"id\": \"f9\", \"ch\": \"a3\", \"rub\": \"anat\", \"pg\": \"1:8\", \"f\": \"Nommez les groupes de sinus de la face et leurs rôles.\", \"b\": \"Antérieurs : maxillaire, frontal, ethmoïdal antérieur (entourent l'orbite, drainent dans le méat moyen). Postérieurs : ethmoïdal postérieur, sphénoïdal. Rôles : conditionnement de l'air, ventilation, drainage des sécrétions.\", \"mn\": \"Antérieurs = « MFE autour de l'œil → Méat Moyen » ; postérieurs = « ES » (Ethmoïde post., Sphénoïde).\", \"kid\": \"Ce sont des petites grottes d'air dans les os du visage, autour des yeux ; celles de devant se vident toutes par la même porte.\", \"ref\": \"2 groupes ; les antérieurs se drainent au méat moyen.\", \"sch\": \"Sinus antérieurs → Ostium → Méat moyen → Fosse nasale\"}, {\"id\": \"f10\", \"ch\": \"a4\", \"rub\": \"anat\", \"pg\": \"1:9\", \"f\": \"Définissez le pharynx et donnez ses dimensions.\", \"b\": \"Conduit musculo-membraneux de la base du crâne au bord inférieur de C6, continué par l'œsophage ; 13 cm de long ; 5 cm de large en position nasale, 4 cm en position orale et laryngée.\", \"mn\": \"« 13-5-4-4 » et « de la base du crâne à C6 ».\", \"kid\": \"C'est un tuyau d'environ la longueur d'un crayon de couleur, derrière ton nez et ta bouche, qui descend vers l'œsophage.\", \"ref\": \"Pharynx = carrefour tubulaire crâne → C6.\", \"sch\": \"Base du crâne → Nasopharynx → Oropharynx → Hypopharynx → Œsophage (C6)\"}, {\"id\": \"f11\", \"ch\": \"a4\", \"rub\": \"anat\", \"pg\": \"1:9,1:10\", \"f\": \"Énumérez les étages du pharynx et décrivez l'oropharynx.\", \"b\": \"Nasopharynx (cavum, rhinopharynx : communique avec les FN par les choanes) ; oropharynx (amygdales palatines et piliers, voile du palais, base de langue et vallécules, parois postérieure et latérale) ; hypopharynx (avec le larynx = carrefour aérodigestif, jusqu'à la bouche œsophagienne).\", \"mn\": \"NASO – ORO – HYPO : « Nez, Oral, en Bas ».\", \"kid\": \"Le tuyau a trois étages : celui du nez, celui de la bouche (où sont les amygdales) et celui du bas, où l'air et la nourriture se séparent.\", \"ref\": \"3 étages superposés ; l'oropharynx contient les amygdales.\", \"sch\": \"Choanes → Nasopharynx → Oropharynx → Hypopharynx → Bouche œsophagienne\"}, {\"id\": \"f12\", \"ch\": \"a4\", \"rub\": \"anat\", \"pg\": \"1:10\", \"f\": \"Citez les fonctions du pharynx.\", \"b\": \"Ventilation, déglutition, phonation (résonateur), défenses immunitaires (formations lymphoïdes), digestion (glandes salivaires), goût (papilles linguales), audition.\", \"mn\": \"« VDP-IDGA » : Ventiler, Déglutir, Parler, Immuniser, Digérer, Goûter, Audition.\", \"kid\": \"La gorge sert à respirer, avaler, parler, défendre contre les microbes et même à aider l'oreille.\", \"ref\": \"Pharynx = 7 fonctions, du souffle au goût.\", \"sch\": \"Air + aliments → Pharynx → Tri (trachée ou œsophage) + défense lymphoïde\"}, {\"id\": \"f13\", \"ch\": \"a5\", \"rub\": \"anat\", \"pg\": \"1:11,1:12\", \"f\": \"Citez les cartilages du larynx et l'innervation de ses muscles.\", \"b\": \"Thyroïde (pomme d'Adam), épiglottique, aryténoïdes (portent les cordes vocales), cricoïde (base). Muscles innervés par les nerfs récurrents (branches du pneumogastrique), sauf le crico-thyroïdien (nerf laryngé supérieur).\", \"mn\": \"« TEAC » : Thyroïde, Épiglotte, Aryténoïdes, Cricoïde ; « le crico-thyroïdien fait bande à part ».\", \"kid\": \"La boîte à voix est faite de petits boucliers : un devant (pomme d'Adam), un couvercle (épiglotte) et des pièces qui tendent les cordes.\", \"ref\": \"4 cartilages majeurs ; nerfs récurrents sauf crico-thyroïdien.\", \"sch\": \"Pneumogastrique → Nerfs récurrents → Muscles du larynx (sauf crico-thyroïdien ← laryngé supérieur)\"}, {\"id\": \"f14\", \"ch\": \"a5\", \"rub\": \"anat\", \"pg\": \"1:12\", \"f\": \"Quelles sont les fonctions du larynx ?\", \"b\": \"Déglutition (épiglotte ferme le larynx, cordes rapprochées), respiration (glotte ouverte), phonation (glotte fermée, cordes plus ou moins tendues).\", \"mn\": \"DRP : Déglutir – Respirer – Parler.\", \"kid\": \"Le larynx est un portail : il se ferme quand tu manges, s'ouvre quand tu respires et vibre quand tu parles.\", \"ref\": \"Glotte ouverte = respirer ; fermée = parler ; épiglotte = protéger.\", \"sch\": \"Aliment → Épiglotte ferme → Pas de fausse route ; Air → Glotte ouverte → Trachée\"}, {\"id\": \"f15\", \"ch\": \"a5\", \"rub\": \"anat\", \"pg\": \"1:12,1:13\", \"f\": \"Décrivez la trachée (définition, longueur, calibre).\", \"b\": \"Conduit fibro-cartilagineux d'anneaux trachéaux, aplati en arrière ; trachée cervicale 5-6 cm (adulte), 4 cm (enfant) ; calibre 6 mm (1-4 ans), 8 mm (4-8 ans), 10 mm (8-12 ans), 12 mm (adulte).\", \"mn\": \"Calibre « 6-8-10-12 » : +2 mm par tranche d'âge.\", \"kid\": \"La trachée est un tuyau fait d'anneaux ; il est tout fin chez les petits (comme une paille) et plus large chez les grands.\", \"ref\": \"Tube annelé dont le calibre grandit avec l'âge.\", \"sch\": \"Larynx → Trachée (anneaux) → Bifurcation → Bronches souches\"}, {\"id\": \"f16\", \"ch\": \"a5\", \"rub\": \"anat\", \"pg\": \"1:13\", \"f\": \"Citez les trois fonctions de la trachée.\", \"b\": \"Ciliaire (drainage des sécrétions), sécrétoire (film de mucus protecteur, appelé « surfactant » dans le cours), tonique (permet au larynx de monter et descendre, surtout lors de la déglutition).\", \"mn\": \"CST : Cils – Sécrétion – Tonus.\", \"kid\": \"Les petits poils de la trachée balaient la saleté vers le haut comme un tapis roulant.\", \"ref\": \"Trachée active : balaie, sécrète, bouge.\", \"sch\": \"Poussières → Mucus → Cils → Remontée vers le pharynx → Dégluties/crachées\"}, {\"id\": \"f17\", \"ch\": \"b1\", \"rub\": \"def\", \"pg\": \"1:14\", \"f\": \"Définissez l'otalgie vraie et l'otalgie fausse.\", \"b\": \"Otalgie = douleur de l'oreille. Vraie/primitive (otodynie) : lésion de l'oreille. Fausse/secondaire (otalgie réflexe) : lésion extra-auriculaire de voisinage. Traitement = celui de la cause.\", \"mn\": \"« OtoDYnie = DYsfonction DE l'oreille ; RÉFLEXE = REFLET d'ailleurs. »\", \"kid\": \"Parfois l'oreille fait mal parce qu'elle est malade ; parfois c'est une dent ou la gorge qui envoie la douleur vers l'oreille.\", \"ref\": \"Vraie = l'oreille ; fausse = le voisin.\", \"sch\": \"Lésion de voisinage (dent, gorge) → Nerfs communs → Douleur ressentie à l'oreille\"}, {\"id\": \"f18\", \"ch\": \"b1\", \"rub\": \"cause\", \"pg\": \"1:14,1:15\", \"f\": \"Citez des causes d'otalgie primitive.\", \"b\": \"Oreille externe : bouchon, CE, otite externe, furoncle, eczéma surinfecté, périchondrite, othématome, zona, traumatismes, tumeurs ; tympan : myringite ; oreille moyenne : OMA, barotraumatisme, OMC, cancers, traumatismes.\", \"mn\": \"« BICTT » : Bouchon, Infection, Corps étranger, Traumatisme, Tumeur.\", \"kid\": \"Quand c'est vraiment l'oreille : un bouchon, un microbe, un objet coincé, un coup ou une boule anormale.\", \"ref\": \"Otalgie vraie = lésion visible à l'otoscopie.\", \"sch\": \"Otoscopie → Lésion visible (oreille externe/moyenne) → Otalgie vraie\"}, {\"id\": \"f19\", \"ch\": \"b1\", \"rub\": \"cause\", \"pg\": \"1:15\", \"f\": \"Citez des causes d'otalgie réflexe.\", \"b\": \"Dentaire (caries, dent de sagesse : otalgie homolatérale), glossites, stomatites, cancer de langue ; oropharynx (pharyngites, angines, phlegmons, apophyse styloïde longue, cancers) ; larynx/hypopharynx (cancers) ; ATM ; sinusites ; œsophage (CE, RGO, hernie hiatale, cancer) ; thyroïdite, rachis cervical.\", \"mn\": \"« DOLASO-T » : Dents, Oropharynx, Larynx, ATM, Sinus, Œsophage, Thyroïde.\", \"kid\": \"Une dent cariée peut faire mal à l'oreille du même côté, comme un écho.\", \"ref\": \"Otalgie à tympan normal → chercher chez les voisins.\", \"sch\": \"Otoscopie normale → Examen ORL complet → Dents/gorge/ATM/sinus/œsophage\"}, {\"id\": \"f20\", \"ch\": \"b1\", \"rub\": \"exam\", \"pg\": \"1:14\", \"f\": \"Décrivez l'examen clinique d'un patient otalgique.\", \"b\": \"Otoscopie d'abord (pavillon, CAE, tympan), puis examen ORL complet : oropharyngoscopie, rhinoscopie antérieure et postérieure ; étendu à la cavité buccale, oro/nasopharynx, hypopharynx-larynx, ATM, sinus, paires crâniennes, œsophage.\", \"mn\": \"« L'oreille d'abord, puis tout le voisinage. »\", \"kid\": \"Le soignant regarde d'abord dans l'oreille avec une petite lampe, puis vérifie la bouche, les dents et la gorge.\", \"ref\": \"Otoscopie + tour complet ORL.\", \"sch\": \"Otoscopie → Oropharyngoscopie → Rhinoscopie → Bouche, ATM, sinus, nerfs, œsophage\"}, {\"id\": \"f21\", \"ch\": \"b2\", \"rub\": \"def\", \"pg\": \"1:16\", \"f\": \"Définissez la surdité.\", \"b\": \"Trouble de l'audition sans présumer l'intensité, allant de l'hypoacousie (baisse de l'acuité) à la cophose (disparition totale de l'ouïe).\", \"mn\": \"« Hypo = un peu moins ; Cophose = zéro. »\", \"kid\": \"Être sourd, c'est entendre moins bien, un peu ou complètement.\", \"ref\": \"Surdité = de l'hypoacousie à la cophose.\", \"sch\": \"Audition normale → Hypoacousie → Cophose\"}, {\"id\": \"f22\", \"ch\": \"b2\", \"rub\": \"def\", \"pg\": \"1:16,1:17\", \"f\": \"Citez les types de surdité et leur siège.\", \"b\": \"Transmission (oreille externe ou moyenne), perception (oreille interne, tympan normal), mixte (les deux appareils).\", \"mn\": \"« Transmission = Tuyaux ; Perception = Capteur. »\", \"kid\": \"Soit le son est bloqué sur le chemin (tuyau bouché), soit le capteur au fond est abîmé, soit les deux.\", \"ref\": \"3 types selon l'appareil touché.\", \"sch\": \"Externe/moyenne → Transmission ; Interne → Perception ; Les deux → Mixte\"}, {\"id\": \"f23\", \"ch\": \"b2\", \"rub\": \"cause\", \"pg\": \"1:16\", \"f\": \"Énumérez les causes des surdités de transmission.\", \"b\": \"Oreille externe : bouchon de cérumen (coton-tige), bouchon épidermique, CE, otites externes, ostéomes, tumeurs, atrésie congénitale. Oreille moyenne : OMA, OMC, traumatismes (spontanés, chirurgicaux), tumeurs.\", \"mn\": \"« Tout ce qui bouche ou abîme le chemin du son. »\", \"kid\": \"Un bouchon de cire ou de l'eau sale derrière le tympan empêche le son de passer, comme un coton dans l'oreille.\", \"ref\": \"Transmission = obstacle avant l'oreille interne.\", \"sch\": \"Coton-tige → Cérumen tassé, noir et dur → Bouchon → Surdité de transmission\"}, {\"id\": \"f24\", \"ch\": \"b2\", \"rub\": \"cause\", \"pg\": \"1:17\", \"f\": \"Énumérez les causes des surdités de perception et les signes d'alerte du nourrisson.\", \"b\": \"Toxiques (aminosides, surtout avec insuffisance rénale), presbyacousie (50-60 ans), traumatiques (sonores, opératoires, accidentelles), congénitales. 0-3 mois : pas de sursaut aux bruits forts, sommeil imperturbable, cri modifié.\", \"mn\": \"« ATPC » : Aminosides, Traumatisme, Presbyacousie, Congénitale.\", \"kid\": \"Certains médicaments, le bruit très fort ou l'âge abîment le capteur du son ; un bébé qui ne sursaute jamais doit être vérifié.\", \"ref\": \"Perception = oreille interne ; tympan normal.\", \"sch\": \"Aminosides + insuffisance rénale → Accumulation → Atteinte de l'oreille interne → Surdité de perception\"}, {\"id\": \"f25\", \"ch\": \"b3\", \"rub\": \"def\", \"pg\": \"1:18\", \"f\": \"Définissez les acouphènes et leurs formes cliniques.\", \"b\": \"Bruits perçus dans l'oreille ou la tête sans source extérieure, perçus seulement par le malade ; permanents, intermittents ou temporaires ; tintement, chuintement, bourdonnement, sifflement ; uni- ou bilatéraux.\", \"mn\": \"« TCBS » : Tintement, Chuintement, Bourdonnement, Sifflement.\", \"kid\": \"C'est un bruit fantôme : toi seul l'entends, alors qu'il n'y a rien autour.\", \"ref\": \"Acouphène = bruit subjectif sans source.\", \"sch\": \"Pas de son extérieur → Perception d'un bruit → Seul le malade l'entend\"}, {\"id\": \"f26\", \"ch\": \"b3\", \"rub\": \"trt\", \"pg\": \"1:18\", \"f\": \"Citez les causes et le traitement d'urgence des acouphènes.\", \"b\": \"Causes : surdité brusque, traumatisme auditif (concert, boîte de nuit, pétard), traumatisme crânien, HTA, anémie sévère et insuffisance rénale, stress/dépression. Urgence : vasodilatateurs, corticoïdes, oxygénothérapie, musique, traitement étiologique.\", \"mn\": \"Traitement « VCO » : Vasodilatateurs – Corticoïdes – Oxygène.\", \"kid\": \"Après un pétard ou un concert trop fort, l'oreille peut siffler : il faut vite voir un soignant.\", \"ref\": \"Causes auditives, vasculaires, générales ; traitement VCO + cause.\", \"sch\": \"Traumatisme sonore → Souffrance de l'oreille interne → Acouphène → VCO en urgence\"}, {\"id\": \"f27\", \"ch\": \"b4\", \"rub\": \"def\", \"pg\": \"1:24\", \"f\": \"Définissez l'othématome et la conduite devant un CE de l'oreille externe.\", \"b\": \"Othématome : collection de sang entre le périchondre et le cartilage du pavillon. CE fréquents chez l'enfant, relèvent du spécialiste : extraction par lavage ou au crochet, pince à éviter.\", \"mn\": \"« CE de l'oreille : LAVE ou CROCHETTE, ne PINCE pas. »\", \"kid\": \"Si un petit objet est dans l'oreille, on ne l'attrape pas avec une pince : on risque de le pousser plus loin.\", \"ref\": \"Othématome = sang sous le périchondre ; CE = lavage/crochet.\", \"sch\": \"CE du CAE → Spécialiste → Lavage ou crochet (pas de pince → risque d'enfoncer)\"}, {\"id\": \"f28\", \"ch\": \"b4\", \"rub\": \"clin\", \"pg\": \"1:24\", \"f\": \"Bouchon de cérumen : signes et traitement.\", \"b\": \"Cérumen mou jaunâtre qui noircit et durcit ; hypoacousie, bourdonnements, acouphènes, vertiges, oreille bouchée, prurit, douleur. Extraction par lavage après instillation quelques minutes d'un antiseptique moussant pour le ramollir.\", \"mn\": \"« Ramollir puis rincer. »\", \"kid\": \"La cire dure bouche l'oreille ; on met d'abord un liquide qui la ramollit, puis on rince avec de l'eau tiède.\", \"ref\": \"Bouchon = ramollir, puis laver.\", \"sch\": \"Cérumen dur → Antiseptique moussant (quelques min) → Lavage d'oreille → CAE libre\"}, {\"id\": \"f29\", \"ch\": \"b4\", \"rub\": \"clin\", \"pg\": \"1:25\", \"f\": \"Furoncle du CAE : définition, signes et traitement.\", \"b\": \"Inflammation des follicules (sébacés) du 1/3 externe du CAE due au staphylocoque, après grattage ; douleur précoce, intense, à la mobilisation du pavillon, à la mastication et à la pression du tragus ; hypoacousie. Traitement : antalgique, anti-inflammatoire, antibiotique général (amoxicilline-ac. clavulanique, oxacilline, pristinamycine).\", \"mn\": \"« FuroncLE = STaphylocoque du Tiers Externe ».\", \"kid\": \"C'est un gros bouton douloureux à l'entrée du conduit, souvent après s'être gratté avec une allumette.\", \"ref\": \"Furoncle = staph + 1/3 externe + douleur intense.\", \"sch\": \"Grattage → Staphylocoque → Furoncle du 1/3 externe → Douleur au tragus → ATB générale\"}, {\"id\": \"f30\", \"ch\": \"b4\", \"rub\": \"clin\", \"pg\": \"1:25,1:26\", \"f\": \"Otite externe diffuse : signes et traitement.\", \"b\": \"Infection du revêtement cutané de tout le CAE (piscine, traumatisme, eczéma) ; otalgie exacerbée par la pression du tragus et la traction du pavillon, prurit, otorrhée fétide, CAE œdématié, tympan normal. Traitement : nettoyage au SP, gouttes ATB-corticoïde (Panotile, Polydexa, Colicort), méchage si conduit rétréci (changé chaque jour), antalgique ; si perforation : rifamycine (Otofa) ou lincomycine.\", \"mn\": \"« Oreille du nageur : Tragus douloureux, Tympan normal. »\", \"kid\": \"Après la piscine, la peau du conduit s'enflamme : ça gratte puis ça fait très mal quand on touche l'oreille.\", \"ref\": \"Tout le conduit est infecté, le tympan est sain.\", \"sch\": \"Piscine → Peau du CAE infectée → Œdème + otorrhée fétide → Nettoyage + gouttes ATB-corticoïde\"}, {\"id\": \"f31\", \"ch\": \"b4\", \"rub\": \"clin\", \"pg\": \"1:24,1:25,1:26\", \"f\": \"Eczéma, périchondrite et otomycose : signes et traitement.\", \"b\": \"Eczéma : prurit intense, poussées, complication = otite externe diffuse ; périchondrite : pavillon tuméfié, rouge, fistule, pus à pyocyanique → antibiotique ; otomycose : dépôt blanchâtre + prurit → antimycosiques locaux 2-3 semaines.\", \"mn\": \"« Blanc qui gratte = champignon. »\", \"kid\": \"Quand on voit comme de la poudre blanche dans l'oreille qui gratte, c'est souvent un champignon.\", \"ref\": \"3 inflammations externes, 3 traitements ciblés.\", \"sch\": \"Otomycose → Dépôt blanchâtre + prurit → Antimycosique local 2 à 3 semaines\"}, {\"id\": \"f32\", \"ch\": \"b5\", \"rub\": \"def\", \"pg\": \"1:27\", \"f\": \"OMA du nourrisson : définition, circonstance et germes.\", \"b\": \"Inflammation de la muqueuse des cavités de l'oreille moyenne évoluant sur moins de 3 semaines, au décours d'une rhinopharyngite ; H. influenzae, S. pneumoniae, M. catarrhalis, mais le plus souvent virale.\", \"mn\": \"Germes « HPM » : Haemophilus, Pneumocoque, Moraxella.\", \"kid\": \"Après un gros rhume, les microbes montent par le petit tuyau jusqu'à l'oreille et l'enflamment.\", \"ref\": \"OMA = complication de la rhinopharyngite.\", \"sch\": \"Rhinopharyngite → Trompe d'Eustache → Oreille moyenne → OMA (< 3 semaines)\"}, {\"id\": \"f33\", \"ch\": \"b5\", \"rub\": \"clin\", \"pg\": \"1:27,1:28\", \"f\": \"Signes cliniques et formes otoscopiques de l'OMA.\", \"b\": \"Fièvre, diarrhée, pleurs, vomissements, rhinite, porte le doigt à l'oreille ; diagnostic par otoscopie : congestive (tympan rouge épaissi, vascularisation du manche du marteau), suppurée collectée (tympan opaque, terne, bombé), suppurée perforée (pus parfois pulsatile, perforation postérieure). Bilatérale > 1 fois sur 2.\", \"mn\": \"« Rouge → Bombé → Percé. »\", \"kid\": \"Le tympan devient rouge, puis gonfle comme un ballon plein de pus, puis il peut se percer et couler.\", \"ref\": \"3 stades otoscopiques successifs.\", \"sch\": \"Otite congestive → Suppurée collectée (bombée) → Suppurée perforée (otorrhée)\"}, {\"id\": \"f34\", \"ch\": \"b5\", \"rub\": \"cat\", \"pg\": \"1:28\", \"f\": \"Conduite à tenir devant une OMA du nourrisson.\", \"b\": \"Vasoconstricteur < 5 jours, désinfection rhinopharyngée au SP, amoxicilline-acide clavulanique 80-100 mg/kg/j, Célestine 10 gouttes/kg/j, paracentèse au stade suppuré collecté ; prévention : hygiène nasale, traiter les allergies, vaccins pneumocoque et Haemophilus.\", \"mn\": \"« Nez propre – Augmentin – Célestine – Paracentèse si bombé. »\", \"kid\": \"On nettoie le nez, on donne un antibiotique et un médicament anti-inflammatoire ; si le tympan est très gonflé, le médecin fait un petit trou pour faire sortir le pus.\", \"ref\": \"Traiter le nez + ATB + corticoïde ; paracentèse si collectée.\", \"sch\": \"OMA → SP + vasoconstricteur court → Amox-clav 80-100 mg/kg/j + Célestine → Paracentèse si bombée\"}, {\"id\": \"f35\", \"ch\": \"b5\", \"rub\": \"comp\", \"pg\": \"1:28\", \"f\": \"Complications et diagnostic différentiel de l'OMA.\", \"b\": \"OMA récidivantes (adénoïdectomie si végétations), mastoïdite aiguë, paralysie faciale otitique, méningite. Diagnostic différentiel : otite externe, otite séromuqueuse, otite moyenne chronique.\", \"mn\": \"« RMPM » : Récidive, Mastoïdite, Paralysie faciale, Méningite.\", \"kid\": \"Mal soignée, l'infection peut aller dans l'os derrière l'oreille, toucher le nerf du visage ou même le cerveau.\", \"ref\": \"Complications locales et cérébro-méningées.\", \"sch\": \"OMA non traitée → Mastoïde → Nerf facial → Méninges\"}, {\"id\": \"f36\", \"ch\": \"c1\", \"rub\": \"def\", \"pg\": \"1:19\", \"f\": \"Définissez l'épistaxis et précisez son origine habituelle.\", \"b\": \"Saignement d'origine endonasale, antérieur (narine), postérieur (rhinopharynx) ou mixte ; urgence fréquente. 90 % : tache vasculaire de Kisselbach sur la cloison, à ~1 cm de l'entrée narinaire. Bénigne (minime/moyenne) vs grave (abondance/répétition + retentissement hémodynamique).\", \"mn\": \"« 90 % – 1 cm – Kisselbach. »\", \"kid\": \"Le saignement de nez vient presque toujours d'un petit coin plein de vaisseaux, juste à l'entrée du nez, sur le mur du milieu.\", \"ref\": \"Épistaxis = saignement du nez, le plus souvent antérieur.\", \"sch\": \"Tache vasculaire (cloison antérieure) → Rupture → Saignement par la narine\"}, {\"id\": \"f37\", \"ch\": \"c1\", \"rub\": \"cause\", \"pg\": \"1:19,1:20\", \"f\": \"Citez au moins cinq causes d'épistaxis.\", \"b\": \"HTA (prendre la TA chez tout adulte), traumatiques (fracture OPN, disjonction crânio-faciale, chirurgie), maladies hémorragiques (Rendu-Osler, thrombopénies, hémophilie, anticoagulants, IR, IH), tumorales (angiofibrome juvénile du garçon adolescent, cancers), infectieuses (rhinopharyngites, sinusites, typhoïde, grippe), autres (CE de l'enfant, perforation septale, grossesse).\", \"mn\": \"« HTM-TIA » : HTA, Traumatisme, Maladie hémorragique, Tumeur, Infection, Autres.\", \"kid\": \"Le nez peut saigner à cause d'un coup, d'une tension trop forte, d'un sang qui coagule mal, d'une infection ou d'un objet mis dans le nez.\", \"ref\": \"6 familles de causes ; toujours la TA chez l'adulte.\", \"sch\": \"Épistaxis → TA (HTA ?) → Trauma ? → Hémostase ? → Tumeur ? → Infection ?\"}, {\"id\": \"f38\", \"ch\": \"c1\", \"rub\": \"cat\", \"pg\": \"1:20,1:21\", \"f\": \"Conduite à tenir devant une épistaxis bénigne.\", \"b\": \"Mouchage des caillots, pulvérisation lidocaïne 5 % naphazoline, examen des FN, compression bidigitale des ailes du nez 10 min tête penchée en avant (coton à l'eau oxygénée/thrombase) ; si échec : méchage antérieur en accordéon (mèche grasse) retiré au plus tard 48 h (nécrose septale) ; couverture ATB ; vérifier l'arrêt par le pharynx ; si échec : bilan sanguin + ORL.\", \"mn\": \"« Mouche – Pulvérise – Pince 10 min tête EN AVANT – Mèche 48 h. »\", \"kid\": \"On fait souffler le nez, on met un spray, puis on pince le nez 10 minutes en penchant la tête en avant pour ne pas avaler le sang.\", \"ref\": \"Compression d'abord, méchage si échec.\", \"sch\": \"Mouchage → Spray xylo/naphazoline → Compression 10 min tête en avant → Échec → Méchage (≤ 48 h)\"}, {\"id\": \"f39\", \"ch\": \"c1\", \"rub\": \"cat\", \"pg\": \"1:21\", \"f\": \"Conduite à tenir devant une épistaxis grave.\", \"b\": \"Hospitalisation, prise de la TA en urgence, voie veineuse (correction d'un choc), groupage (transfusion), tamponnement antérieur voire postérieur, couverture antibiotique et hémostatique parentérale.\", \"mn\": \"« H-TA-VV-G-T » : Hospitaliser, TA, Voie veineuse, Groupage, Tamponner.\", \"kid\": \"Quand le nez saigne beaucoup, on garde la personne à l'hôpital, on surveille sa tension et on prépare du sang au cas où.\", \"ref\": \"Grave = réanimer + tamponner.\", \"sch\": \"Épistaxis abondante → Hospitalisation → TA + VVP + Groupage → Tamponnement ant./post. → ATB + hémostatique IV\"}, {\"id\": \"f40\", \"ch\": \"c2\", \"rub\": \"def\", \"pg\": \"1:29,1:30,1:31\", \"f\": \"Définissez les rhinites et citez au moins trois causes.\", \"b\": \"Inflammations des fosses nasales. Causes/formes : allergiques, infectieuses (aiguës < 12 sem, chroniques au-delà), médicamenteuses, endocriniennes, inflammatoires non allergiques (NARES), chimiques/environnementales, idiopathiques.\", \"mn\": \"« AIMENI » : Allergique, Infectieuse, Médicamenteuse, Endocrinienne, NARES, Idiopathique.\", \"kid\": \"Le nez peut être enflammé à cause d'une allergie, d'un microbe, d'un médicament ou des hormones.\", \"ref\": \"Rhinite = inflammation des FN, causes multiples.\", \"sch\": \"Interrogatoire + examen de la cavité nasale → Classification de la rhinite\"}, {\"id\": \"f41\", \"ch\": \"c2\", \"rub\": \"clin\", \"pg\": \"1:29,1:30\", \"f\": \"Rhinite allergique : signes cliniques et classification.\", \"b\": \"Triade brutale : obstruction nasale, éternuements en salve, rhinorrhée aqueuse. Intermittente : < 4 j/semaine ou < 4 semaines/an ; persistante : > 4 j/semaine et > 4 semaines/an. Modérée : aucun des 4 critères (sommeil, activités, travail/école, symptômes invalidants) ; sévère : au moins un.\", \"mn\": \"« Bouché – Atchoum en rafale – Coule comme de l'eau. » Seuil : 4 jours / 4 semaines.\", \"kid\": \"Avec une allergie, le nez se bouche d'un coup, on éternue plein de fois et le nez coule comme un robinet.\", \"ref\": \"Triade + 2 axes : durée (4/4) et gravité (sévère si ≥ 1 critère).\", \"sch\": \"Allergène → Triade brutale → Durée (intermittente/persistante) × Gravité (modérée/sévère)\"}, {\"id\": \"f42\", \"ch\": \"c2\", \"rub\": \"cause\", \"pg\": \"1:30\", \"f\": \"Rhinites médicamenteuses, endocriniennes et NARES.\", \"b\": \"Médicamenteuses : aspirine, réserpine, guanéthidine, IEC ; vasoconstricteurs au long cours à forte dose. Endocriniennes : hyperthyroïdie, acromégalie, 3e trimestre de grossesse (œstrogènes). NARES : éosinophiles > 20 % et enquête allergique négative.\", \"mn\": \"NARES = « Non Allergique, Riche en Éosinophiles (> 20 %) ».\", \"kid\": \"Certains médicaments ou les hormones de la grossesse peuvent aussi boucher le nez.\", \"ref\": \"Penser aux médicaments, aux hormones et aux éosinophiles.\", \"sch\": \"Vasoconstricteur prolongé → Perturbation de la vasomotricité → Rhinite médicamenteuse\"}, {\"id\": \"f43\", \"ch\": \"c2\", \"rub\": \"trt\", \"pg\": \"1:31\", \"f\": \"Traitement des rhinites.\", \"b\": \"Mouchage, vasoconstricteur de courte durée, lavage nasal, antihistaminique, éviction de l'allergène, traitement des symptômes invalidants.\", \"mn\": \"« MOVLAE » : Moucher, Vasoconstricteur court, Laver, Antihistaminique, Éviction.\", \"kid\": \"On mouche, on lave le nez et on évite ce qui donne l'allergie.\", \"ref\": \"Libérer + laver + anti-allergie + éviction.\", \"sch\": \"Rhinite → Mouchage → Lavage → Vasoconstricteur court → Antihistaminique + éviction\"}, {\"id\": \"f44\", \"ch\": \"c3\", \"rub\": \"def\", \"pg\": \"1:32\", \"f\": \"Définissez la sinusite aiguë et citez ses germes.\", \"b\": \"Atteinte infectieuse de la muqueuse des sinus de la face évoluant depuis moins de 3 semaines ; après rhinite, grippe, bain en piscine ; H. influenzae, pneumocoque, S. aureus, anaérobies.\", \"mn\": \"« Moins de 3 semaines = aiguë. »\", \"kid\": \"Les petites grottes d'air du visage se remplissent de microbes après un rhume.\", \"ref\": \"Sinusite aiguë = infection sinusienne < 3 semaines.\", \"sch\": \"Rhinite/grippe → Ostium bouché → Infection du sinus → Sinusite aiguë\"}, {\"id\": \"f45\", \"ch\": \"c3\", \"rub\": \"clin\", \"pg\": \"1:32,1:33\", \"f\": \"Tableau clinique d'une sinusite maxillaire aiguë.\", \"b\": \"La plus fréquente, unilatérale (pansinusite si tous les sinus homolatéraux) ; douleur sous-orbitaire unilatérale pulsatile, augmentée tête penchée en avant et à la toux ; céphalée, obstruction, rhinorrhée purulente parfois striée de sang, cacosmie, anosmie ; pus au méat moyen, cornets tuméfiés, douleur à la pression du nerf sous-orbitaire ; Blondeau : opacité du sinus maxillaire.\", \"mn\": \"« Joue qui bat quand je me penche. »\", \"kid\": \"Ça fait mal sous l'œil, d'un seul côté, et encore plus quand on se baisse.\", \"ref\": \"Douleur sous-orbitaire unilatérale + pus au méat moyen + opacité Blondeau.\", \"sch\": \"Infection maxillaire → Pus → Méat moyen → Rhinorrhée purulente unilatérale\"}, {\"id\": \"f46\", \"ch\": \"c3\", \"rub\": \"trt\", \"pg\": \"1:33\", \"f\": \"Traitement de la sinusite maxillaire aiguë.\", \"b\": \"Décongestionner les ostiums (lavage du nez) ; antalgiques ; antibiotique général 10 jours (amoxicilline-ac. clavulanique, C3G : Orelox, Texodil, ou pristinamycine : Pyostacine) ; corticothérapie 5 jours à 0,5-1 mg/kg/j (Cortancyl) ; soins locaux (lavage SP, aérosol sonique) ; antihistaminique après l'ATB. Évite la chronicité.\", \"mn\": \"« ATB 10 jours, Cortico 5 jours. »\", \"kid\": \"On ouvre les petites portes des sinus en lavant le nez, puis on donne un antibiotique pendant 10 jours.\", \"ref\": \"Drainer + ATB 10 j + cortico 5 j.\", \"sch\": \"Lavage → Ostium ouvert → Drainage du pus + ATB 10 j + Cortico 5 j → Guérison sans chronicité\"}, {\"id\": \"f47\", \"ch\": \"c4\", \"rub\": \"def\", \"pg\": \"1:34\", \"f\": \"Définissez les végétations adénoïdes.\", \"b\": \"Hypertrophie du tissu lymphoïde de la paroi postéro-supérieure du rhinopharynx due aux infections respiratoires répétées : hypertrophie de l'amygdale pharyngée de Luschka.\", \"mn\": \"« Végétations = amygdale de LUSCHKA en haut derrière le nez. »\", \"kid\": \"Derrière le nez, il y a une petite éponge de défense qui grossit trop après beaucoup de rhumes et bouche le passage.\", \"ref\": \"Végétations = amygdale pharyngée hypertrophiée.\", \"sch\": \"Infections répétées → Hypertrophie lymphoïde du cavum → Obstruction nasale\"}, {\"id\": \"f48\", \"ch\": \"c4\", \"rub\": \"clin\", \"pg\": \"1:34\", \"f\": \"Signes cliniques et radiologiques des végétations adénoïdes.\", \"b\": \"Obstruction nasale bilatérale : respiration buccale, ronflement nocturne, troubles du sommeil ; rhinorrhée mucopurulente = surinfection ; test bouche fermée du nourrisson ; mucopus sur la paroi pharyngée postérieure ; radio de profil du cavum (inspiration, bouche fermée) : espace clair comblé.\", \"mn\": \"« Bouche ouverte, ronfle, dort mal. »\", \"kid\": \"L'enfant respire par la bouche, ronfle la nuit et dort mal parce que son nez est bouché par derrière.\", \"ref\": \"Obstruction bilatérale + radio de profil du cavum.\", \"sch\": \"Végétations → Obstruction bilatérale → Respiration buccale + ronflement → Troubles du sommeil\"}, {\"id\": \"f49\", \"ch\": \"c4\", \"rub\": \"comp\", \"pg\": \"1:34,1:35\", \"f\": \"Complications et traitement des végétations adénoïdes.\", \"b\": \"Tubotympaniques (OMA récidivantes, otites séromuqueuses) ; laryngo-trachéo-bronchiques (laryngites sous-glottiques à répétition, trachéites, bronchopneumopathies) ; rhinosinusiennes (rhinosinusites, ethmoïdite aiguë, adénites cervicales, détresse respiratoire du NN/nourrisson). Traitement : adénoïdectomie si rhonchopathie invalidante avec apnée du sommeil.\", \"mn\": \"« Oreille – Bronches – Sinus » ; « opérer si ronfle + apnée ».\", \"kid\": \"Cette éponge trop grosse peut abîmer les oreilles, les sinus et les poumons ; on l'enlève si l'enfant arrête de respirer en dormant.\", \"ref\": \"3 familles de complications ; adénoïdectomie si apnée.\", \"sch\": \"Végétations → Trompe bouchée → OMA récidivantes ; → Apnée du sommeil → Adénoïdectomie\"}, {\"id\": \"f50\", \"ch\": \"d1\", \"rub\": \"clin\", \"pg\": \"2:1\", \"f\": \"Rhinopharyngite : définition et signes de début.\", \"b\": \"Inflammation aiguë de la muqueuse des FN et du rhinopharynx, surtout virale, très fréquente chez l'enfant ; fièvre brutale 39-40 °C, irritabilité, vomissements/diarrhée, adénopathies cervicales bilatérales, obstruction nasale bilatérale, rhinorrhée séreuse puis mucopurulente, éternuements, rougeur conjonctivale, larmoiement, toux rauque, cri modifié.\", \"mn\": \"« Fièvre forte + nez bouché + yeux rouges. »\", \"kid\": \"C'est le gros rhume de l'enfant : il a beaucoup de fièvre, le nez qui coule et les yeux qui pleurent.\", \"ref\": \"Rhinopharyngite = rhume fébrile viral de l'enfant.\", \"sch\": \"Virus → Muqueuse nasale + rhinopharynx → Fièvre + rhinorrhée séreuse → mucopurulente\"}, {\"id\": \"f51\", \"ch\": \"d1\", \"rub\": \"exam\", \"pg\": \"2:1,2:2\", \"f\": \"Examen clinique de la rhinopharyngite.\", \"b\": \"Rhinoscopie : muqueuse très rouge, mucopus (mucus jaunâtre à polynucléaires et macrophages) ; oropharyngoscopie : muqueuse rouge surtout aux piliers et amygdales ; otoscopie : congestion tympanique.\", \"mn\": \"« Nez – Gorge – Oreille » : regarder les trois.\", \"kid\": \"Le soignant regarde dans le nez, dans la gorge et dans l'oreille : tout est rouge.\", \"ref\": \"Examen ORL complet : nez, gorge, tympan.\", \"sch\": \"Rhinoscopie → Oropharyngoscopie → Otoscopie (dépister une OMA)\"}, {\"id\": \"f52\", \"ch\": \"d1\", \"rub\": \"trt\", \"pg\": \"2:2\", \"f\": \"Traitement et évolution d'une rhinopharyngite non compliquée.\", \"b\": \"Désinfection rhinopharyngée pluriquotidienne au SP, aspiration (mouche-bébé), éducation au mouchage ; aspirine 80 mg/kg/j dans le cours (notion datée) ; antibiothérapie inutile ; guérison en 5 jours ; surveillance des complications.\", \"mn\": \"« Sérum, pas d'antibiotique, 5 jours. »\", \"kid\": \"On lave le nez plusieurs fois par jour ; l'antibiotique ne sert à rien contre un virus ; ça passe en 5 jours.\", \"ref\": \"Traitement symptomatique, pas d'ATB.\", \"sch\": \"Virus → Lavage SP + antipyrétique → Guérison en 5 jours (sinon chercher une complication)\"}, {\"id\": \"f53\", \"ch\": \"d1\", \"rub\": \"comp\", \"pg\": \"2:2\", \"f\": \"Citez trois complications de la rhinopharyngite et leur traitement.\", \"b\": \"OMA (la plus fréquente), laryngite aiguë sus-glottique, trachéobronchite, adénophlegmon du cou, phlegmon rétropharyngé, sinusite maxillaire, ethmoïdite aiguë ; traitement : SP, anti-inflammatoire + antibiotique (amoxicilline ± ac. clavulanique) 8 jours, contrôle à une semaine.\", \"mn\": \"« L'OMA arrive en premier. »\", \"kid\": \"Si le rhume dure ou si l'oreille fait mal, c'est peut-être une complication : là, l'antibiotique peut être utile.\", \"ref\": \"Complication → ATB 8 jours.\", \"sch\": \"Rhinopharyngite → OMA / Sinusite / Laryngite / Phlegmon → ATB 8 j + contrôle J7\"}, {\"id\": \"f54\", \"ch\": \"d2\", \"rub\": \"clin\", \"pg\": \"2:3,2:4\", \"f\": \"Pharyngite aiguë : définition, signes et facteurs de risque.\", \"b\": \"Inflammation de la gorge/pharynx (streptocoque, virus, champignon), bénigne ; aiguë : quelques jours à 1 semaine, surtout virale ; odynophagie, dysphonie, fièvre modérée 38 °C, céphalées, asthénie, ganglions cervicaux, toux. TROD pour le germe. Facteurs : tabac, alcool, environnement (poussière, air sec/froid, climatisation, gouttes nasales répétées).\", \"mn\": \"« Odynophagie = Odieux d'avaler ; Dysphonie = voix Dérangée. »\", \"kid\": \"La gorge brûle quand on avale et la voix devient rauque.\", \"ref\": \"Pharyngite aiguë = gorge douloureuse, souvent virale.\", \"sch\": \"Virus/strepto → Muqueuse pharyngée → Odynophagie + dysphonie + 38 °C → TROD\"}, {\"id\": \"f55\", \"ch\": \"d2\", \"rub\": \"clin\", \"pg\": \"2:4\", \"f\": \"Pharyngite chronique : définition, signes et causes.\", \"b\": \"Installation progressive, > 3 semaines, symptômes localisés à la gorge, fièvre seulement si surinfection ; sécheresse, raclage, douleur, odynodysphagie ; plus fréquente chez l'adulte : tabac (actif/passif), alcool, environnement, rhinite, rhinosinusite chronique, RGO, enseignant, chanteur.\", \"mn\": \"« Chronique = > 3 semaines, Chanteur, Cigarette. »\", \"kid\": \"Chez les grands qui fument ou qui parlent beaucoup, la gorge peut rester irritée très longtemps.\", \"ref\": \"Chronique = longue, localisée, sans fièvre.\", \"sch\": \"Irritants (tabac, RGO, voix) → Inflammation > 3 semaines → Sécheresse + raclage\"}, {\"id\": \"f56\", \"ch\": \"d2\", \"rub\": \"comp\", \"pg\": \"2:4,2:5\", \"f\": \"Complications et traitement des pharyngites.\", \"b\": \"Bactérienne dans 30 % (streptocoque β-hémolytique A) : abcès péripharyngé, otites, sinusites, laryngites, trachéobronchites, pneumonies, glomérulonéphrite aiguë post-streptococcique, RAA. Traitement : lavage de nez, mouchage, boissons chaudes, sprays, paracétamol, ATB seulement si bactérienne.\", \"mn\": \"« Strepto A → Rein (GNA) + Cœur/articulations (RAA). »\", \"kid\": \"Si un microbe spécial de la gorge n'est pas soigné, il peut ensuite abîmer les reins ou le cœur.\", \"ref\": \"Strepto A = complications générales graves.\", \"sch\": \"Strepto β-hémolytique A → Réaction immunitaire → GNA post-strepto / RAA\"}, {\"id\": \"f57\", \"ch\": \"d2\", \"rub\": \"trt\", \"pg\": \"2:5\", \"f\": \"Pharyngite mycosique : signes et traitement.\", \"b\": \"Brûlures ou sensation de coton dans la bouche, dysphagie, agueusie, sécheresse, petits saignements ; plaques blanc crème ; antifongiques : nystatine (Mycostatine) comprimé à sucer, amphotéricine (Fungizone) ou miconazole (Daktarin) gel.\", \"mn\": \"« Crème blanche = champignon → Myco-statine. »\", \"kid\": \"Un champignon dans la gorge fait des taches blanches comme du lait caillé.\", \"ref\": \"Plaques blanches → antifongique local.\", \"sch\": \"Champignon → Plaques blanc crème → Nystatine / Amphotéricine / Miconazole\"}, {\"id\": \"f58\", \"ch\": \"d3\", \"rub\": \"def\", \"pg\": \"2:6\", \"f\": \"Angine : définition et germes responsables.\", \"b\": \"Inflammation de l'oropharynx et des amygdales palatines ; streptocoque β-hémolytique du groupe A, staphylocoque, pneumocoque, H. influenzae ; adolescents et adultes jeunes.\", \"mn\": \"Germes « SSPH » : Strepto A, Staph, Pneumo, Haemophilus.\", \"kid\": \"Les amygdales, ces deux boules au fond de la bouche, deviennent rouges et gonflées à cause d'un microbe.\", \"ref\": \"Angine = amygdalite palatine aiguë.\", \"sch\": \"Germe (strepto A ++) → Amygdales palatines → Angine\"}, {\"id\": \"f59\", \"ch\": \"d3\", \"rub\": \"clin\", \"pg\": \"2:6,2:7\", \"f\": \"Signes cliniques et paracliniques de l'angine.\", \"b\": \"Frissons, douleur et irritation de gorge, odynophagie irradiant à l'oreille (otalgie réflexe), fièvre élevée, céphalées, arthralgies, asthénie ; amygdales hypertrophiées à enduit blanchâtre (érythémato-pultacée), adénopathies sensibles et mobiles ; NFS : hyperleucocytose à PNN ; prélèvement de gorge non indispensable.\", \"mn\": \"« Amygdales blanches + oreille qui tire. »\", \"kid\": \"On a très mal en avalant, ça tire jusqu'à l'oreille, et on voit des points blancs sur les amygdales.\", \"ref\": \"Angine érythémato-pultacée + hyperleucocytose.\", \"sch\": \"Amygdales inflammées → Odynophagie → Douleur projetée à l'oreille (otalgie réflexe)\"}, {\"id\": \"f60\", \"ch\": \"d3\", \"rub\": \"trt\", \"pg\": \"2:6,2:7\", \"f\": \"Traitement de l'angine et sa complication la plus courante.\", \"b\": \"Pénicilline 3 à 4 millions d'unités/jour pendant 8 jours, acide acétylsalicylique, antiseptiques locaux, repos au lit ; complication la plus courante sans traitement : phlegmon péri-amygdalien.\", \"mn\": \"« Péni 3-4 millions × 8 jours. »\", \"kid\": \"On donne de la pénicilline pendant 8 jours ; sinon une poche de pus peut se former à côté de l'amygdale.\", \"ref\": \"Pénicilline 8 j pour éviter le phlegmon.\", \"sch\": \"Angine non traitée → Phlegmon péri-amygdalien ; traitée → Péni 3-4 MUI/j × 8 j\"}, {\"id\": \"f61\", \"ch\": \"d4\", \"rub\": \"def\", \"pg\": \"1:22\", \"f\": \"Définissez la dyspnée laryngée.\", \"b\": \"Bradypnée inspiratoire avec tirage sus-sternal, cornage et trouble de la voix ; toute dyspnée obstructive de l'enfant est une urgence (décompensation rapide, pronostic vital).\", \"mn\": \"« BTC-V » : Bradypnée inspiratoire, Tirage, Cornage, Voix.\", \"kid\": \"L'air a du mal à entrer : l'enfant respire lentement, en creusant le cou, avec un bruit de corne.\", \"ref\": \"Dyspnée laryngée = obstacle haut, inspiration difficile.\", \"sch\": \"Obstacle laryngé → Inspiration lente et bruyante → Tirage + cornage + dysphonie\"}, {\"id\": \"f62\", \"ch\": \"d4\", \"rub\": \"cause\", \"pg\": \"1:22\", \"f\": \"Citez des causes de dyspnée laryngée chez le nourrisson, l'enfant et l'adulte.\", \"b\": \"Nourrisson : malformation, spasmes, CE, stridor. Enfant : laryngite aiguë sous-glottique, CE méconnus, papillomatose/tumeur, traumatisme. Adulte : CE, traumatisme, laryngites, lésions nerveuses (spasmes, paralysies), tumeurs.\", \"mn\": \"« Le CE est à tous les âges. »\", \"kid\": \"À tous les âges, un objet avalé de travers peut boucher la gorge ; chez l'enfant, c'est souvent une laryngite.\", \"ref\": \"Causes selon l'âge ; CE partout.\", \"sch\": \"Âge → Cause probable : Nourrisson (malformation/stridor) → Enfant (laryngite) → Adulte (tumeur/nerf)\"}, {\"id\": \"f63\", \"ch\": \"d4\", \"rub\": \"clin\", \"pg\": \"1:23\", \"f\": \"Décrivez les 4 stades de la laryngite aiguë sous-glottique.\", \"b\": \"Stade 1 : calme, tirage modéré sus-sternal, TA et pouls normaux. Stade 2 : agité, tirage net sus-sternal + xiphoïdien, pouls accéléré. Stade 3 : angoissé, tirage intense + intercostal, TA élevée, cyanose. Stade 4 : inconscient, tirage et cornage absents, TA effondrée, pouls filant, rythme irrégulier, cyanose.\", \"mn\": \"« Calme – Agité – Angoissé – Inconscient » ; le silence du stade 4 est le plus grave.\", \"kid\": \"Plus c'est grave, plus l'enfant s'agite… jusqu'au moment où il s'épuise et devient silencieux : c'est le pire.\", \"ref\": \"Gravité croissante ; stade 4 = épuisement.\", \"sch\": \"Stade 1 (calme) → 2 (agité) → 3 (angoissé, cyanose) → 4 (inconscient, signes absents)\"}, {\"id\": \"f64\", \"ch\": \"d4\", \"rub\": \"cat\", \"pg\": \"1:23\", \"f\": \"Conduite à tenir devant une dyspnée laryngée.\", \"b\": \"Ne jamais faire attendre. Stades I-II : évaluer, position assise tête en hyperextension, oxygène, corticoïde IVD, aérosol d'adrénaline 1 mg dans 5 ml de NaCl 0,9 % si allergie/œdème, appeler le médecin/évacuer. Stades III-IV : intubation nasotrachéale, trachéotomie si obstacle mécanique empêchant l'intubation. Traiter la cause.\", \"mn\": \"« Assis – O2 – Cortico – Adré » puis « Intuber ou Trachéo ».\", \"kid\": \"On assoit l'enfant, on lui donne de l'oxygène et un médicament qui dégonfle la gorge ; si c'est très grave, on met un tuyau pour respirer.\", \"ref\": \"Stades 1-2 : médical ; stades 3-4 : voie aérienne.\", \"sch\": \"Dyspnée laryngée → Position assise + O2 + corticoïde IVD (+ adrénaline aérosol) → Échec/stade 3-4 → Intubation / Trachéotomie\"}, {\"id\": \"f65\", \"ch\": \"d5\", \"rub\": \"cat\", \"pg\": \"2:8,2:9\", \"f\": \"CE des fosses nasales : exemples, motif de consultation et CAT.\", \"b\": \"Volontaires (mousse, craie, papier, gomme, perle, maïs, haricot, arachide) ou involontaires (balle, mèche oubliée) ; obstruction nasale + rhinorrhée mucopurulente UNILATÉRALE, odeur nauséabonde ; CAT : interrogatoire, rhinoscopie ; visible : mouchage en force narine libre fermée après rétraction des cornets, extraction au crochet/pince ; invisible : évacuer.\", \"mn\": \"« Un seul côté qui coule et qui sent = objet dans le nez. »\", \"kid\": \"Si un enfant a une seule narine qui coule et sent mauvais, il a peut-être mis une perle ou un haricot dedans.\", \"ref\": \"Rhinorrhée unilatérale fétide de l'enfant = CE.\", \"sch\": \"CE nasal → Rhinorrhée unilatérale fétide → Rhinoscopie → Mouchage forcé / crochet / évacuation\"}, {\"id\": \"f66\", \"ch\": \"d5\", \"rub\": \"cat\", \"pg\": \"2:9\", \"f\": \"CE du pharynx : motif de consultation et CAT.\", \"b\": \"Arête, os, épingle ; douleur à l'arrière-gorge, dysphagie, odynophagie, au cours d'un repas ; examen avec bon éclairage et abaisse-langue ; visible : extraction à la pince ; non visible : évacuer.\", \"mn\": \"« Arête au repas → Lampe + abaisse-langue → Pince ou évacuation. »\", \"kid\": \"Une arête de poisson coincée dans la gorge pendant le repas : on regarde avec une lampe et on la retire avec une pince.\", \"ref\": \"Visible = pince ; invisible = évacuer.\", \"sch\": \"Repas → Arête → Douleur arrière-gorge → Examen éclairé → Pince / Évacuation\"}, {\"id\": \"f67\", \"ch\": \"d5\", \"rub\": \"clin\", \"pg\": \"2:9,2:10\", \"f\": \"CE laryngé et trachéal : signes et traitement.\", \"b\": \"Laryngé volumineux plein : asphyxie aiguë rapidement mortelle ; moins volumineux/creux : dyspnée laryngée avec tirage, voix éteinte ; syndrome de pénétration dans la journée, sans fièvre. Trachéal : souvent mobile, quintes de toux, spasmes, dyspnée expiratoire aux changements de position. Traitement : bronchoscopie au tube rigide sous AG.\", \"mn\": \"« Pénétration + pas de fièvre = CE, pas laryngite. »\", \"kid\": \"Si l'enfant s'étouffe d'un coup en jouant, sans fièvre, il a sûrement avalé un objet de travers.\", \"ref\": \"Syndrome de pénétration → bronchoscopie rigide.\", \"sch\": \"Inhalation → Syndrome de pénétration → Dyspnée/toux selon le siège → Bronchoscopie rigide sous AG\"}, {\"id\": \"f68\", \"ch\": \"d5\", \"rub\": \"clin\", \"pg\": \"2:10\", \"f\": \"CE de l'œsophage : signes, diagnostic et traitement.\", \"b\": \"Pièce de monnaie, arête, os, prothèse dentaire, bol alimentaire ; adulte : douleur rétrosternale, odynophagie, gêne respiratoire, dysphagie brutale (repas ou nuit : prothèse) ; enfant : troubles moindres, dysphagie sans contexte infectieux ; radio si radio-opaque ; extraction dans les 2-3 jours + ATB, antispasmodique, réhydratation parentérale.\", \"mn\": \"« Dysphagie brutale la nuit = dentier avalé. »\", \"kid\": \"Un adulte qui a avalé son dentier en dormant a mal derrière le sternum et ne peut plus avaler.\", \"ref\": \"Dysphagie brutale → radio → extraction rapide.\", \"sch\": \"CE œsophagien → Dysphagie brutale + douleur rétrosternale → Radio (si opaque) → Extraction en 2-3 jours\"}, {\"id\": \"f69\", \"ch\": \"e1\", \"rub\": \"cat\", \"pg\": \"2:11\", \"f\": \"Lavage d'oreille : définition, indications et matériel.\", \"b\": \"Mise en état de vacuité du CAE dans un but thérapeutique ; indications : bouchon de cérumen, bouchon épidermique, CE accessible ; matériel : seringue stérile 50 ml (poire à défaut), cupule stérile, compresses, coton, serviette/champ, alèze et tablier imperméables, gants stériles, réniforme.\", \"mn\": \"Indications « BBC » : Bouchon cérumen, Bouchon épidermique, Corps étranger.\", \"kid\": \"On rince le conduit de l'oreille avec une grosse seringue d'eau tiède pour faire sortir la cire ou un petit objet.\", \"ref\": \"Lavage = vider le CAE ; 3 indications.\", \"sch\": \"Bouchon / CE accessible → Lavage d'oreille (seringue 50 ml) → CAE vide\"}, {\"id\": \"f70\", \"ch\": \"e1\", \"rub\": \"cat\", \"pg\": \"2:11,2:12\", \"f\": \"Décrivez la technique du lavage d'oreille.\", \"b\": \"Prévenir ; vérifier la température de l'eau sur le revers de la main ; installer et protéger cou/épaules ; préparer la solution ; le patient tient le haricot sous l'oreille ; injecter doucement puis pression modérée ; pencher la tête ; nettoyer et sécher ; contrôle otoscopique ; réinstaller ; noter (bouchon/CE, liquide, réaction).\", \"mn\": \"« Tester – Tirer le pavillon – Doucement – Vérifier à l'otoscope. »\", \"kid\": \"On vérifie que l'eau n'est ni trop froide ni trop chaude sur le dos de la main, puis on rince tout doucement.\", \"ref\": \"Eau tiède, pression douce, contrôle otoscopique.\", \"sch\": \"T° eau (revers de main) → Installation → Injection douce → Écoulement → Séchage → Otoscopie → Transmission\"}, {\"id\": \"f71\", \"ch\": \"e1\", \"rub\": \"comp\", \"pg\": \"2:12,2:13\", \"f\": \"Surveillance, incidents et contre-indications du lavage d'oreille.\", \"b\": \"Surveiller : efficacité, aspect du liquide, douleur, vertiges, perforation. Incidents : vertiges/nausées (eau trop froide ou trop chaude), douleur (arrêter), traumatisme (introduction trop profonde). Ne jamais laver une otorrhée de l'oreille moyenne (surinfection de la caisse) ; jamais d'eau froide, glacée ou chaude. Qualité : pavillon étiré, CAE rectiligne.\", \"mn\": \"« Vertige = mauvaise température ; Douleur = STOP ; Otorrhée = JAMAIS. »\", \"kid\": \"Si l'eau est trop froide ou trop chaude, la tête tourne ; si ça fait mal, on arrête tout de suite.\", \"ref\": \"Température, douleur, otorrhée : les 3 pièges.\", \"sch\": \"Eau non tiède → Stimulation de l'oreille interne → Vertiges + nausées\"}, {\"id\": \"f72\", \"ch\": \"e2\", \"rub\": \"prev\", \"pg\": \"2:13,2:14\", \"f\": \"Lavage de nez : principe, indications et intérêts.\", \"b\": \"Faire passer un liquide légèrement salé dans les FN pour les nettoyer ; indications : rhinite atrophique (rhinorrhées purulentes, croûtes), encombrement nasal, après chirurgie endonasale ; intérêts : prévient/soulage les infections rhinopharyngées, bien-être respiratoire, limite les allergènes, restaure filtration-drainage-immunité, évite la descente des mucosités vers bronches, assainit le rhinopharynx, aide drainage et ventilation.\", \"mn\": \"Indications « RAE » : Rhinite Atrophique, Encombrement, après Endonasale.\", \"kid\": \"On rince le nez avec de l'eau salée, comme on rince une bouteille, pour enlever la saleté et les microbes.\", \"ref\": \"Eau salée → nez propre → moins d'infections.\", \"sch\": \"Liquide salé → Narine haute → Cavum → Narine basse → Mucosités évacuées\"}, {\"id\": \"f73\", \"ch\": \"e2\", \"rub\": \"cat\", \"pg\": \"2:14,2:15,2:16\", \"f\": \"Technique de lavage de nez chez le nourrisson de moins de 6 mois.\", \"b\": \"Mains lavées ; dosettes de SP à usage unique (pas d'eau du robinet ni minérale) ; 1) allongé sur le dos ou le côté, tête maintenue sur le côté (fausse route) ; 2) embout dans la narine du haut ; 3) presser toute la dosette en fermant la bouche ; 4) attendre la déglutition ; 5) essuyer ; recommencer de l'autre côté avec une autre dosette. Préférable au mouche-bébé. Vasoconstricteurs proscrits avant 15 ans.\", \"mn\": \"« Tête sur le CÔTÉ, narine du HAUT, bouche FERMÉE. »\", \"kid\": \"On couche bébé la tête sur le côté, on met le sérum dans la narine du haut et il ressort par celle du bas.\", \"ref\": \"Tête latérale = pas de fausse route.\", \"sch\": \"Bébé tête sur le côté → Dosette narine haute → Bouche fermée → Sortie narine basse → Déglutition → Autre côté\"}, {\"id\": \"f74\", \"ch\": \"e2\", \"rub\": \"cat\", \"pg\": \"2:16,2:17\", \"f\": \"Lavage de nez chez l'enfant qui se mouche et l'adulte ; préparation de l'eau salée.\", \"b\": \"Enfant : assis, tête inclinée, embout dans la narine la plus haute, pression, se moucher fort, puis l'autre côté (sans vasoconstricteur). Adulte : position verticale, tête inclinée, narine supérieure, pression franche, laisser agir, changer de côté, moucher. Préparation : 1 L d'eau + 2 cuillères à café de gros sel (pas de sel fin de table), option bicarbonate, reposer 1 min. Fréquence : cures d'1 semaine par mois, saisonnière ou en alerte. Froid/tiède : défenses ; tiède/chaud : dilatation.\", \"mn\": \"« 1 litre = 2 cuillères à café de GROS sel. »\", \"kid\": \"Les grands se penchent sur le côté, versent l'eau dans la narine du haut et se mouchent bien fort.\", \"ref\": \"Narine supérieure toujours ; gros sel 2 c. à café/L.\", \"sch\": \"1 L d'eau + 2 c. à café gros sel (+ bicarbonate) → Repos 1 min → Lavage narine supérieure → Mouchage\"}, {\"id\": \"f75\", \"ch\": \"e3\", \"rub\": \"def\", \"pg\": \"2:18\", \"f\": \"Méchage antérieur : définition et indications.\", \"b\": \"Combler en accordéon les FN avec une mèche, des choanes au vestibule, pour faire l'hémostase ; indications : épistaxis, contention d'une réduction des OPN, cavoscopie, après chirurgie (cautérisation des cornets, turbinectomie, plastie).\", \"mn\": \"« Accordéon des choanes au vestibule. »\", \"kid\": \"On remplit le nez avec une longue bande pliée comme un accordéon pour appuyer sur ce qui saigne.\", \"ref\": \"Méchage = compression intranasale.\", \"sch\": \"Épistaxis → Mèche en accordéon → Compression → Hémostase\"}, {\"id\": \"f76\", \"ch\": \"e3\", \"rub\": \"cat\", \"pg\": \"2:18,2:19\", \"f\": \"Matériel et technique du méchage antérieur.\", \"b\": \"Spéculum de Palmer, pince coudée de Lubet-Barbon/Politzer, ciseaux, miroir de Clar, mèche de gaze 2-3 cm, xylocaïne 5 % naphazoline, pommade HEC… ; patient assis/demi-assis, champ, haricot sous le menton ; moucher ; xylocaïne puis attendre 5-10 min (rétracte les cornets, anesthésie) ; mèche imbibée d'hémostatique ; spéculum ; mèche introduite au fond, tassée en accordéon haut/bas ; fixation compresses + sparadrap ; ATB, antalgique, hémostatique ; déméchage à 48 h.\", \"mn\": \"« Assis – Mouche – Xylo 5-10 min – Accordéon – 48 h. »\", \"kid\": \"On endort l'intérieur du nez avec un spray, on attend un peu, puis on glisse la bande avec une pince en faisant des plis.\", \"ref\": \"Anesthésier, combler, fixer, retirer à 48 h.\", \"sch\": \"Mouchage → Xylocaïne (5-10 min) → Spéculum → Mèche au fond → Accordéon → Fixation → Déméchage 48 h\"}, {\"id\": \"f77\", \"ch\": \"e3\", \"rub\": \"cat\", \"pg\": \"2:18,2:19\", \"f\": \"Préparation psychologique et conseils de sortie après méchage.\", \"b\": \"Rassurer, acte non douloureux sous anesthésie locale, déméchage dans 48 h ; respirer par la bouche 48 h, manger et boire lentement à petites gorgées, prendre le traitement (sinon surinfection des FN), revenir en cas de nouveau saignement.\", \"mn\": \"« Bouche 48 h – petites gorgées – traitement – revenir si ça saigne. »\", \"kid\": \"Pendant deux jours, on respire par la bouche et on boit doucement ; si ça resaigne, on revient vite.\", \"ref\": \"Informer pour 48 h de nez bouché.\", \"sch\": \"Sortie → Respiration buccale 48 h → Traitement pris → Déméchage ; Resaignement → Retour\"}, {\"id\": \"f78\", \"ch\": \"e4\", \"rub\": \"cat\", \"pg\": \"2:20\", \"f\": \"Trachéotomie : définition et soins post-opératoires.\", \"b\": \"Ouverture de la trachée cervicale pour y introduire une canule qui court-circuite les VAS lors d'un obstacle ; soins : aspiration des sécrétions, humidification de l'air, prévention de l'infection de la plaie et broncho-pulmonaire, canule changée tous les 3 jours si possible, sonde d'aspiration dans un bocal d'eau + antiseptique (Bétadine jaune).\", \"mn\": \"« AHI-3 » : Aspirer, Humidifier, prévenir l'Infection, canule tous les 3 jours.\", \"kid\": \"On fait un petit trou dans le cou pour que l'air passe en dessous de l'obstacle ; il faut garder le tuyau propre et humide.\", \"ref\": \"Trachéotomie = dérivation de l'air sous l'obstacle.\", \"sch\": \"Obstacle des VAS → Ouverture trachéale + canule → Aspiration + humidification + asepsie → Canule changée tous les 3 j\"}], \"qs\": [{\"id\": \"q001\", \"t\": \"qcm\", \"f\": \"f1\", \"ch\": \"a1\", \"q\": \"Quelles parties de l'oreille forment l'appareil de transmission ?\", \"x\": \"Le cours divise l'appareil auriculaire en appareil de transmission (oreille externe + moyenne) et appareil de perception (oreille interne).\", \"o\": [\"L'oreille externe et l'oreille moyenne\", \"L'oreille moyenne et l'oreille interne\", \"L'oreille interne seule\", \"Le pavillon et la cochlée\"], \"c\": 0, \"d\": 1}, {\"id\": \"q002\", \"t\": \"qcm\", \"f\": \"f4\", \"ch\": \"a1\", \"q\": \"Dans quelle portion du conduit auditif externe se trouvent les glandes cérumineuses ?\", \"x\": \"Sur le 1/3 externe, la peau possède des glandes cérumineuses ; sur les 2/3 internes, la peau adhère directement à l'os.\", \"o\": [\"Les deux tiers internes\", \"Le tiers externe\", \"Le tiers moyen uniquement\", \"Le fond du conduit au contact du tympan\"], \"c\": 1, \"d\": 2}, {\"id\": \"q003\", \"t\": \"qcm\", \"f\": \"f3\", \"ch\": \"a1\", \"q\": \"Quelle fonction de l'oreille moyenne est assurée par le réflexe stapédien ?\", \"x\": \"L'oreille moyenne assure transmission, adaptation d'impédance et protection de l'oreille interne grâce au réflexe stapédien.\", \"o\": [\"L'adaptation d'impédance\", \"La localisation des sons\", \"La protection de l'oreille interne\", \"La transformation du signal mécanique en signal électrique\"], \"c\": 2, \"d\": 3}, {\"id\": \"q004\", \"t\": \"qcm\", \"f\": \"f5\", \"ch\": \"a1\", \"q\": \"Quelle est l'unité fonctionnelle de la cochlée ?\", \"x\": \"Cochlée → organe de Corti ; vestibule → macule ; canaux semi-circulaires → crêtes ampullaires.\", \"o\": [\"La macule\", \"Les crêtes ampullaires\", \"L'antre mastoïdien\", \"L'organe de Corti\"], \"c\": 3, \"d\": 2}, {\"id\": \"q005\", \"t\": \"qcm\", \"f\": \"f1\", \"ch\": \"a1\", \"q\": \"Quelle est la structure du conduit auditif externe ?\", \"x\": \"Le CAE, en entonnoir, est fibro-cartilagineux dans son tiers externe et osseux dans ses deux tiers internes.\", \"o\": [\"Fibro-cartilagineuse au 1/3 externe, osseuse aux 2/3 internes\", \"Osseuse au 1/3 externe, cartilagineuse aux 2/3 internes\", \"Entièrement cartilagineuse\", \"Entièrement osseuse\"], \"c\": 0, \"d\": 1}, {\"id\": \"q006\", \"t\": \"vf\", \"f\": \"f2\", \"ch\": \"a1\", \"q\": \"La trompe d'Eustache fait communiquer la caisse du tympan avec le pharynx.\", \"x\": \"Vrai : conduit ostéo-cartilagineux entre caisse du tympan et pharynx, qui aère l'oreille moyenne et équilibre la pression.\", \"v\": true, \"d\": 1}, {\"id\": \"q007\", \"t\": \"vf\", \"f\": \"f5\", \"ch\": \"a1\", \"q\": \"Le vestibule et les canaux semi-circulaires assurent l'audition.\", \"x\": \"Faux : selon le cours, « l'oreille interne joue un rôle dans l'audition grâce à la cochlée » et « dans l'équilibre grâce au vestibule et aux canaux semi-circulaires ».\", \"v\": false, \"d\": 1}, {\"id\": \"q008\", \"t\": \"open\", \"f\": \"f3\", \"ch\": \"a1\", \"q\": \"Comment s'appellent les trois osselets de la caisse du tympan (dans l'ordre) ?\", \"x\": \"La caisse du tympan contient le marteau, l'enclume et l'étrier, qui forment avec le tympan la chaîne tympano-ossiculaire.\", \"a\": \"marteau enclume étrier\", \"alt\": [\"marteau, enclume, étrier\", \"marteau enclume etrier\"], \"k\": [\"marteau\", \"enclume\", \"etrier\"], \"d\": 3}, {\"id\": \"q009\", \"t\": \"cas\", \"f\": \"f2\", \"ch\": \"a1\", \"q\": \"Quelle structure permet d'équilibrer la pression de part et d'autre du tympan ?\", \"x\": \"La trompe d'Eustache participe à l'aération de l'oreille moyenne et sert d'équilibre de pression de part et d'autre du tympan.\", \"o\": [\"La mastoïde\", \"La trompe d'Eustache\", \"Le conduit auditif externe\", \"Le labyrinthe\"], \"c\": 1, \"s\": \"Une patiente revient d'un voyage en avion et se plaint d'oreilles « bouchées » qui se débouchent quand elle avale.\", \"d\": 3}, {\"id\": \"q010\", \"t\": \"qcm\", \"f\": \"f7\", \"ch\": \"a2\", \"q\": \"Le cours affirme que le nez est :\", \"x\": \"Fonction respiratoire : « le nez est la seule voie physiologique de la respiration ».\", \"o\": [\"Une voie respiratoire accessoire\", \"Uniquement l'organe de l'odorat\", \"La seule voie physiologique de la respiration\", \"Sans rôle dans la phonation\"], \"c\": 2, \"d\": 2}, {\"id\": \"q011\", \"t\": \"qcm\", \"f\": \"f6\", \"ch\": \"a2\", \"q\": \"La paroi externe de la fosse nasale comporte :\", \"x\": \"Paroi externe = méats et cornets ; paroi interne = cloison ; paroi supérieure = toit ; inférieure = plancher.\", \"o\": [\"La cloison nasale\", \"Le toit des fosses nasales\", \"Le vestibule nasal\", \"Les cornets et les méats\"], \"c\": 3, \"d\": 3}, {\"id\": \"q012\", \"t\": \"qcm\", \"f\": \"f8\", \"ch\": \"a2\", \"q\": \"Où se situe la muqueuse olfactive ?\", \"x\": \"La muqueuse olfactive occupe la partie supérieure de la fosse nasale ; la respiratoire occupe presque toute la fosse nasale.\", \"o\": [\"À la partie supérieure de la fosse nasale\", \"Sur le plancher des fosses nasales\", \"Dans le vestibule nasal\", \"Dans toute la fosse nasale\"], \"c\": 0, \"d\": 2}, {\"id\": \"q013\", \"t\": \"qcm\", \"f\": \"f7\", \"ch\": \"a2\", \"q\": \"Le conditionnement de l'air inspiré par le nez comprend :\", \"x\": \"Le nez permet outre la ventilation le conditionnement de l'air : réchauffement, humidification, purification.\", \"o\": [\"Refroidissement, assèchement, purification\", \"Réchauffement, humidification, purification\", \"Humidification seulement\", \"Filtration des sons\"], \"c\": 1, \"d\": 1}, {\"id\": \"q014\", \"t\": \"vf\", \"f\": \"f8\", \"ch\": \"a2\", \"q\": \"Le squelette de la cloison nasale est osseux en arrière et cartilagineux en avant.\", \"x\": \"Vrai : en arrière de l'os, en avant du cartilage, essentiellement le cartilage septal.\", \"v\": true, \"d\": 1}, {\"id\": \"q015\", \"t\": \"vf\", \"f\": \"f6\", \"ch\": \"a2\", \"q\": \"Le vestibule nasal est situé en arrière de la cavité nasale proprement dite.\", \"x\": \"Faux : selon le cours, « en avant de cette cavité le vestibule nasal », tapissé d'un épiderme garni de poils.\", \"v\": false, \"d\": 1}, {\"id\": \"q016\", \"t\": \"open\", \"f\": \"f6\", \"ch\": \"a2\", \"q\": \"Comment appelle-t-on la structure qui sépare les deux fosses nasales ?\", \"x\": \"Les deux fosses nasales sont séparées par une cloison nasale ou septum nasal.\", \"a\": \"cloison nasale\", \"alt\": [\"septum nasal\", \"septum\", \"cloison\"], \"k\": [], \"d\": 3}, {\"id\": \"q017\", \"t\": \"cas\", \"f\": \"f7\", \"ch\": \"a2\", \"q\": \"Quelle fonction du nez explique ce changement ?\", \"x\": \"Fonction phonatoire : le nez influence le timbre de la voix.\", \"o\": [\"La fonction olfactive\", \"La fonction de protection\", \"La fonction phonatoire\", \"La fonction d'équilibre\"], \"c\": 2, \"s\": \"Un patient enrhumé vous dit que sa voix « sonne bizarre » depuis que son nez est bouché.\", \"d\": 3}, {\"id\": \"q018\", \"t\": \"qcm\", \"f\": \"f9\", \"ch\": \"a3\", \"q\": \"Où se drainent les sinus antérieurs ?\", \"x\": \"Les sinus antérieurs entourent l'orbite et se drainent tous dans le méat moyen (fosse nasale).\", \"o\": [\"Dans le méat inférieur\", \"Dans le rhinopharynx\", \"Dans l'orbite\", \"Dans le méat moyen\"], \"c\": 3, \"d\": 2}, {\"id\": \"q019\", \"t\": \"qcm\", \"f\": \"f9\", \"ch\": \"a3\", \"q\": \"Lequel est un sinus postérieur ?\", \"x\": \"Sinus postérieurs : ethmoïdal postérieur et sphénoïdal.\", \"o\": [\"Le sinus sphénoïdal\", \"Le sinus frontal\", \"Le sinus maxillaire\", \"Les cellules ethmoïdales antérieures\"], \"c\": 0, \"d\": 3}, {\"id\": \"q020\", \"t\": \"qcm\", \"f\": \"f9\", \"ch\": \"a3\", \"q\": \"Le cours attribue aux sinus un rôle dans :\", \"x\": \"Ils jouent un rôle dans le conditionnement de l'air intra-sinusien, la ventilation et le drainage des sécrétions.\", \"o\": [\"L'audition et l'équilibre\", \"Le conditionnement de l'air, la ventilation et le drainage des sécrétions\", \"La production de cérumen\", \"La déglutition\"], \"c\": 1, \"d\": 2}, {\"id\": \"q021\", \"t\": \"vf\", \"f\": \"f9\", \"ch\": \"a3\", \"q\": \"Les sinus antérieurs entourent la cavité de l'orbite.\", \"x\": \"Vrai : point commun des sinus antérieurs (maxillaire, frontal, ethmoïdal antérieur).\", \"v\": true, \"d\": 1}, {\"id\": \"q022\", \"t\": \"vf\", \"f\": \"f9\", \"ch\": \"a3\", \"q\": \"Le sinus frontal appartient au groupe des sinus postérieurs.\", \"x\": \"Faux : selon le cours, « les sinus antérieurs : le sinus maxillaire, frontal et les cellules ethmoïdales antérieures ».\", \"v\": false, \"d\": 1}, {\"id\": \"q023\", \"t\": \"open\", \"f\": \"f9\", \"ch\": \"a3\", \"q\": \"Combien de groupes de sinus de la face le cours distingue-t-il ?\", \"x\": \"Le cours distingue deux groupes : sinus antérieurs et sinus postérieurs.\", \"a\": \"2\", \"alt\": [\"deux\", \"2 groupes\"], \"k\": [], \"d\": 3}, {\"id\": \"q024\", \"t\": \"cas\", \"f\": \"f9\", \"ch\": \"a3\", \"q\": \"Quel point doit-il désigner ?\", \"x\": \"Ces sinus antérieurs se drainent tous dans le méat moyen.\", \"o\": [\"Le méat supérieur\", \"Les choanes\", \"Le méat moyen\", \"Le canal lacrymal\"], \"c\": 2, \"s\": \"Un étudiant doit montrer sur un schéma le point de drainage commun du sinus maxillaire, du sinus frontal et de l'ethmoïde antérieur.\", \"d\": 3}, {\"id\": \"q025\", \"t\": \"qcm\", \"f\": \"f10\", \"ch\": \"a4\", \"q\": \"Le pharynx s'étend de la base du crâne jusqu'au bord inférieur de :\", \"x\": \"Conduit musculo-membraneux de la base du crâne au bord inférieur de C6 (ou bord supérieur de C7).\", \"o\": [\"La 4e vertèbre cervicale (C4)\", \"La 1re vertèbre thoracique (T1)\", \"La 2e vertèbre cervicale (C2)\", \"La 6e vertèbre cervicale (C6)\"], \"c\": 3, \"d\": 1}, {\"id\": \"q026\", \"t\": \"qcm\", \"f\": \"f11\", \"ch\": \"a4\", \"q\": \"Par quoi le nasopharynx communique-t-il avec les fosses nasales ?\", \"x\": \"Le nasopharynx (cavum) communique avec les fosses nasales par les choanes.\", \"o\": [\"Les choanes\", \"Les vallécules\", \"Les piliers du voile\", \"La trompe d'Eustache\"], \"c\": 0, \"d\": 2}, {\"id\": \"q027\", \"t\": \"qcm\", \"f\": \"f11\", \"ch\": \"a4\", \"q\": \"Quel étage constitue avec le larynx le carrefour aérodigestif ?\", \"x\": \"L'hypopharynx constitue avec le larynx le carrefour aérodigestif et se termine à la bouche œsophagienne.\", \"o\": [\"L'oropharynx\", \"L'hypopharynx\", \"Le nasopharynx\", \"Le cavum\"], \"c\": 1, \"d\": 3}, {\"id\": \"q028\", \"t\": \"vf\", \"f\": \"f11\", \"ch\": \"a4\", \"q\": \"Les amygdales palatines font partie de l'oropharynx.\", \"x\": \"Vrai : l'oropharynx comprend la région amygdalienne (amygdales palatines, piliers antérieur et postérieur).\", \"v\": true, \"d\": 1}, {\"id\": \"q029\", \"t\": \"vf\", \"f\": \"f12\", \"ch\": \"a4\", \"q\": \"Selon le cours, le pharynx n'a aucun rôle dans l'audition.\", \"x\": \"Faux : parmi les fonctions du pharynx, le cours cite « l'audition » (et aussi ventilation, déglutition, phonation, défenses, digestion, goût).\", \"v\": false, \"d\": 1}, {\"id\": \"q030\", \"t\": \"open\", \"f\": \"f10\", \"ch\": \"a4\", \"q\": \"Quelle est la longueur approximative du pharynx (en cm) ?\", \"x\": \"Le pharynx mesure 13 cm de longueur environ.\", \"a\": \"13 cm\", \"alt\": [\"13\", \"treize centimetres\"], \"k\": [], \"d\": 3}, {\"id\": \"q031\", \"t\": \"cas\", \"f\": \"f12\", \"ch\": \"a4\", \"q\": \"Quelle fonction du pharynx illustre-t-il ?\", \"x\": \"Le pharynx intervient dans l'élaboration des défenses immunitaires par ses nombreuses formations lymphoïdes.\", \"o\": [\"La digestion\", \"Le goût\", \"L'élaboration des défenses immunitaires\", \"La ventilation\"], \"c\": 2, \"s\": \"Lors d'un exposé, un étudiant explique que les formations lymphoïdes du pharynx (amygdales) protègent l'organisme.\", \"d\": 3}, {\"id\": \"q032\", \"t\": \"qcm\", \"f\": \"f11\", \"ch\": \"a4\", \"q\": \"Lequel de ces éléments n'appartient PAS à l'oropharynx ?\", \"x\": \"Les choanes font communiquer nasopharynx et fosses nasales ; les autres éléments appartiennent à l'oropharynx.\", \"o\": [\"La base de langue et les vallécules\", \"Le voile du palais mou\", \"Les piliers antérieur et postérieur\", \"Les choanes\"], \"c\": 3, \"d\": 2}, {\"id\": \"q033\", \"t\": \"qcm\", \"f\": \"f13\", \"ch\": \"a5\", \"q\": \"Quel cartilage forme la « pomme d'Adam » ?\", \"x\": \"Le cartilage thyroïde en forme de livre ouvert présente un relief antérieur plus prononcé chez l'homme (pomme d'Adam).\", \"o\": [\"Le cartilage thyroïde\", \"Le cartilage cricoïde\", \"Le cartilage aryténoïde\", \"L'épiglotte\"], \"c\": 0, \"d\": 1}, {\"id\": \"q034\", \"t\": \"qcm\", \"f\": \"f13\", \"ch\": \"a5\", \"q\": \"Sur quels cartilages s'insèrent les cordes vocales ?\", \"x\": \"Les aryténoïdes, articulés avec le cricoïde, portent les deux cordes vocales ; leurs mouvements règlent position et tension.\", \"o\": [\"Le thyroïde seul\", \"Les aryténoïdes\", \"L'épiglotte\", \"Les anneaux trachéaux\"], \"c\": 1, \"d\": 2}, {\"id\": \"q035\", \"t\": \"qcm\", \"f\": \"f13\", \"ch\": \"a5\", \"q\": \"Quel muscle du larynx n'est PAS innervé par le nerf récurrent ?\", \"x\": \"Tous les muscles sont commandés par les nerfs récurrents sauf le crico-thyroïdien, tenseur des cordes vocales, innervé par le nerf laryngé supérieur.\", \"o\": [\"Le crico-aryténoïdien latéral\", \"Les muscles dilatateurs de la glotte\", \"Le crico-thyroïdien\", \"Tous les muscles sont innervés par le récurrent\"], \"c\": 2, \"d\": 3}, {\"id\": \"q036\", \"t\": \"qcm\", \"f\": \"f15\", \"ch\": \"a5\", \"q\": \"Quel est le calibre de la trachée chez l'enfant de 1 à 4 ans ?\", \"x\": \"Calibre : 6 mm (1-4 ans), 8 mm (4-8 ans), 10 mm (8-12 ans), 12 mm (adulte).\", \"o\": [\"8 mm\", \"10 mm\", \"12 mm\", \"6 mm\"], \"c\": 3, \"d\": 2}, {\"id\": \"q037\", \"t\": \"qcm\", \"f\": \"f14\", \"ch\": \"a5\", \"q\": \"Pendant la phonation, la glotte est :\", \"x\": \"Rôle phonatoire : émission et modulation des sons, glotte fermée et cordes plus ou moins tendues.\", \"o\": [\"Fermée avec des cordes plus ou moins tendues\", \"Largement ouverte\", \"Fermée par l'épiglotte uniquement\", \"Sans mouvement des cordes\"], \"c\": 0, \"d\": 1}, {\"id\": \"q038\", \"t\": \"vf\", \"f\": \"f15\", \"ch\": \"a5\", \"q\": \"La longueur de la trachée cervicale est de 5 à 6 cm chez l'adulte et de 4 cm chez l'enfant.\", \"x\": \"Vrai : chiffres exacts du cours.\", \"v\": true, \"d\": 1}, {\"id\": \"q039\", \"t\": \"vf\", \"f\": \"f16\", \"ch\": \"a5\", \"q\": \"La fonction ciliaire de la trachée permet au larynx de monter et de descendre lors de la déglutition.\", \"x\": \"Faux : selon le cours, c'est « la fonction tonique » qui « permet au larynx de monter et descendre » ; la fonction ciliaire « assure le drainage des sécrétions ».\", \"v\": false, \"d\": 1}, {\"id\": \"q040\", \"t\": \"vf\", \"f\": \"f13\", \"ch\": \"a5\", \"q\": \"Le cartilage cricoïde est le cartilage qui ferme le larynx lors de la déglutition.\", \"x\": \"Faux : selon le cours, « le cartilage cricoïde assure la base du larynx » ; c'est l'épiglotte qui ferme le larynx.\", \"v\": false, \"d\": 1}, {\"id\": \"q041\", \"t\": \"open\", \"f\": \"f15\", \"ch\": \"a5\", \"q\": \"Quel est le calibre de la trachée chez l'adulte (en mm) ?\", \"x\": \"Calibre de la trachée : 12 mm chez l'adulte.\", \"a\": \"12 mm\", \"alt\": [\"12\", \"douze millimetres\"], \"k\": [], \"d\": 3}, {\"id\": \"q042\", \"t\": \"cas\", \"f\": \"f14\", \"ch\": \"a5\", \"q\": \"Quel mécanisme laryngé empêche les aliments de passer dans la trachée ?\", \"x\": \"Rôle dans la déglutition : l'épiglotte ferme le larynx et les cordes vocales se rapprochent.\", \"o\": [\"La glotte s'ouvre largement\", \"L'épiglotte ferme le larynx et les cordes vocales se rapprochent\", \"La trachée se contracte\", \"Le cricoïde s'abaisse\"], \"c\": 1, \"s\": \"Pendant un repas, un patient avale sans faire de fausse route.\", \"d\": 3}, {\"id\": \"q043\", \"t\": \"qcm\", \"f\": \"f17\", \"ch\": \"b1\", \"q\": \"Comment appelle-t-on une otalgie liée à une lésion de l'oreille elle-même ?\", \"x\": \"L'otalgie primitive ou vraie, liée à une lésion de l'oreille, est appelée otodynie.\", \"o\": [\"Otalgie réflexe\", \"Otalgie secondaire\", \"Otodynie (otalgie vraie)\", \"Otalgie fausse\"], \"c\": 2, \"d\": 3}, {\"id\": \"q044\", \"t\": \"qcm\", \"f\": \"f19\", \"ch\": \"b1\", \"q\": \"Une otalgie homolatérale accompagne très souvent :\", \"x\": \"Origine dentaire : les caries et accidents de la dent de sagesse s'accompagnent très souvent d'otalgie homolatérale.\", \"o\": [\"Les rhinites allergiques\", \"L'otomycose\", \"Le bouchon de cérumen\", \"Les caries et accidents de la dent de sagesse\"], \"c\": 3, \"d\": 2}, {\"id\": \"q045\", \"t\": \"qcm\", \"f\": \"f18\", \"ch\": \"b1\", \"q\": \"Laquelle est une cause d'otalgie PRIMITIVE ?\", \"x\": \"Le furoncle du conduit est une infection de l'oreille externe (otalgie vraie) ; les autres sont des otalgies réflexes.\", \"o\": [\"Le furoncle du conduit\", \"L'angine\", \"La sinusite aiguë\", \"Le reflux gastro-œsophagien\"], \"c\": 0, \"d\": 1}, {\"id\": \"q046\", \"t\": \"qcm\", \"f\": \"f20\", \"ch\": \"b1\", \"q\": \"Quel est le premier examen à réaliser devant une otalgie ?\", \"x\": \"L'examen comprend en premier lieu un examen de l'oreille par otoscopie (pavillon, CAE, tympan).\", \"o\": [\"La radiographie de Blondeau\", \"L'otoscopie\", \"La NFS\", \"L'oropharyngoscopie seule\"], \"c\": 1, \"d\": 2}, {\"id\": \"q047\", \"t\": \"qcm\", \"f\": \"f19\", \"ch\": \"b1\", \"q\": \"Laquelle est une cause œsophagienne d'otalgie réflexe ?\", \"x\": \"Causes œsophagiennes : corps étranger, œsophagite, cancer de l'œsophage, hernie hiatale et RGO.\", \"o\": [\"Le zona auriculaire\", \"La myringite virale\", \"La hernie hiatale avec reflux gastro-œsophagien\", \"L'othématome\"], \"c\": 2, \"d\": 3}, {\"id\": \"q048\", \"t\": \"vf\", \"f\": \"f17\", \"ch\": \"b1\", \"q\": \"Le traitement de l'otalgie est le traitement de sa cause.\", \"x\": \"Vrai : phrase du cours.\", \"v\": true, \"d\": 1}, {\"id\": \"q049\", \"t\": \"vf\", \"f\": \"f18\", \"ch\": \"b1\", \"q\": \"Les tumeurs malignes du conduit donnent une otalgie tardive et peu intense.\", \"x\": \"Faux : selon le cours, tumeurs malignes du conduit : « otalgie précoce et intense ».\", \"v\": false, \"d\": 1}, {\"id\": \"q050\", \"t\": \"open\", \"f\": \"f17\", \"ch\": \"b1\", \"q\": \"Quel autre nom donne-t-on à l'otalgie secondaire ou fausse ?\", \"x\": \"L'otalgie secondaire ou fausse, liée à une lésion extra-auriculaire de voisinage, est appelée otalgie réflexe.\", \"a\": \"otalgie réflexe\", \"alt\": [\"reflexe\", \"otalgie reflexe\"], \"k\": [], \"d\": 3}, {\"id\": \"q051\", \"t\": \"cas\", \"f\": \"f19\", \"ch\": \"b1\", \"q\": \"Comment qualifier cette otalgie ?\", \"x\": \"Tympan et conduit normaux + lésion dentaire homolatérale : otalgie secondaire (réflexe), traitée en soignant la dent.\", \"o\": [\"Otodynie par otite externe\", \"Otalgie primitive par bouchon\", \"Otalgie d'origine œsophagienne\", \"Otalgie réflexe d'origine dentaire\"], \"c\": 3, \"s\": \"Un adulte consulte pour une douleur de l'oreille droite. L'otoscopie est normale ; il a une carie profonde d'une molaire inférieure droite.\", \"d\": 3}, {\"id\": \"q052\", \"t\": \"qcm\", \"f\": \"f22\", \"ch\": \"b2\", \"q\": \"Une surdité de perception correspond à une atteinte de :\", \"x\": \"Surdités de perception : altération de l'oreille interne ; c'est une surdité à tympan normal.\", \"o\": [\"L'oreille interne\", \"L'oreille externe\", \"L'oreille moyenne\", \"Du pavillon\"], \"c\": 0, \"d\": 2}, {\"id\": \"q053\", \"t\": \"qcm\", \"f\": \"f24\", \"ch\": \"b2\", \"q\": \"Quelle famille d'antibiotiques domine les surdités toxiques ?\", \"x\": \"Surdités toxiques dominées par les aminosides, à redouter en cas d'insuffisance rénale.\", \"o\": [\"Les pénicillines\", \"Les aminosides\", \"Les macrolides\", \"Les céphalosporines\"], \"c\": 1, \"d\": 1}, {\"id\": \"q054\", \"t\": \"qcm\", \"f\": \"f21\", \"ch\": \"b2\", \"q\": \"La disparition totale de l'ouïe s'appelle :\", \"x\": \"Surdité : de l'hypoacousie (baisse de l'acuité) à la cophose (disparition totale de l'ouïe).\", \"o\": [\"L'hypoacousie\", \"La presbyacousie\", \"La cophose\", \"L'acouphène\"], \"c\": 2, \"d\": 2}, {\"id\": \"q055\", \"t\": \"qcm\", \"f\": \"f24\", \"ch\": \"b2\", \"q\": \"Quel signe doit alerter sur une surdité chez un nourrisson de 0 à 3 mois ?\", \"x\": \"Signes à surveiller de 0 à 3 mois : absence de sursaut aux bruits forts, sommeil imperturbable, cri modifié.\", \"o\": [\"Une fièvre élevée\", \"Une rhinorrhée unilatérale\", \"Un tympan bombé\", \"L'absence de sursaut aux bruits forts\"], \"c\": 3, \"d\": 3}, {\"id\": \"q056\", \"t\": \"vf\", \"f\": \"f23\", \"ch\": \"b2\", \"q\": \"Les nettoyages au coton-tige favorisent l'accumulation de cérumen qui devient noirâtre et dur.\", \"x\": \"Vrai : cause de bouchon de cérumen citée dans les surdités de transmission.\", \"v\": true, \"d\": 1}, {\"id\": \"q057\", \"t\": \"vf\", \"f\": \"f24\", \"ch\": \"b2\", \"q\": \"La presbyacousie est une surdité de transmission de l'enfant.\", \"x\": \"Faux : selon le cours, « la presbyacousie ou surdité de la sénescence se voit à l'âge de 50 à 60 ans » ; c'est une surdité de perception.\", \"v\": false, \"d\": 1}, {\"id\": \"q058\", \"t\": \"open\", \"f\": \"f22\", \"ch\": \"b2\", \"q\": \"Comment appelle-t-on une surdité qui atteint à la fois l'appareil de transmission et l'appareil de perception ?\", \"x\": \"Surdités mixtes : l'atteinte est au niveau des deux appareils.\", \"a\": \"surdité mixte\", \"alt\": [\"mixte\", \"surdite mixte\"], \"k\": [], \"d\": 3}, {\"id\": \"q059\", \"t\": \"cas\", \"f\": \"f24\", \"ch\": \"b2\", \"q\": \"Quel type de surdité faut-il suspecter ?\", \"x\": \"Tympan normal + aminoside + insuffisance rénale : surdité de perception toxique.\", \"o\": [\"Surdité de perception toxique\", \"Surdité de transmission par bouchon\", \"Surdité mixte congénitale\", \"Otite moyenne aiguë\"], \"c\": 0, \"s\": \"M. K., 58 ans, sous aminoside pour une infection sévère, a une insuffisance rénale. Il se plaint d'entendre de moins en moins bien ; le tympan est normal.\", \"d\": 3}, {\"id\": \"q060\", \"t\": \"qcm\", \"f\": \"f25\", \"ch\": \"b3\", \"q\": \"Un acouphène est :\", \"x\": \"Les acouphènes sont des bruits entendus dans l'oreille ou la tête sans source extérieure, perçus seulement par le sujet malade.\", \"o\": [\"Un bruit extérieur amplifié\", \"Un bruit perçu sans source extérieure, entendu seulement par le malade\", \"Une douleur de l'oreille\", \"Une perte totale de l'audition\"], \"c\": 1, \"d\": 2}, {\"id\": \"q061\", \"t\": \"qcm\", \"f\": \"f25\", \"ch\": \"b3\", \"q\": \"Lequel n'est PAS une forme sonore d'acouphène citée dans le cours ?\", \"x\": \"Formes : tintement, chuintement, bourdonnement et sifflement ; le cornage est un signe de dyspnée laryngée.\", \"o\": [\"Le tintement\", \"Le chuintement\", \"Le cornage\", \"Le sifflement\"], \"c\": 2, \"d\": 1}, {\"id\": \"q062\", \"t\": \"qcm\", \"f\": \"f26\", \"ch\": \"b3\", \"q\": \"Le traitement d'urgence des acouphènes associe notamment :\", \"x\": \"Traitement d'urgence : vasodilatateurs, corticoïdes, oxygénothérapie, musique, traitement étiologique.\", \"o\": [\"Antibiotiques et antifongiques\", \"Lavage d'oreille et méchage\", \"Paracentèse et adénoïdectomie\", \"Vasodilatateurs, corticoïdes et oxygénothérapie\"], \"c\": 3, \"d\": 2}, {\"id\": \"q063\", \"t\": \"qcm\", \"f\": \"f26\", \"ch\": \"b3\", \"q\": \"Laquelle est une cause générale d'acouphènes citée par le cours ?\", \"x\": \"Étiologies : surdité brusque, traumatismes, HTA, anémie sévère et insuffisance rénale, stress ou dépression.\", \"o\": [\"L'anémie sévère\", \"Le furoncle du conduit\", \"La rhinite allergique\", \"La pharyngite mycosique\"], \"c\": 0, \"d\": 3}, {\"id\": \"q064\", \"t\": \"vf\", \"f\": \"f25\", \"ch\": \"b3\", \"q\": \"Les acouphènes peuvent être unilatéraux ou bilatéraux.\", \"x\": \"Vrai : « ils peuvent être uni ou bilatéraux ».\", \"v\": true, \"d\": 1}, {\"id\": \"q065\", \"t\": \"vf\", \"f\": \"f26\", \"ch\": \"b3\", \"q\": \"Le cours déconseille d'écouter de la musique en cas d'acouphènes.\", \"x\": \"Faux : le cours propose d'« écouter la musique pour oublier ses acouphènes ».\", \"v\": false, \"d\": 1}, {\"id\": \"q066\", \"t\": \"open\", \"f\": \"f26\", \"ch\": \"b3\", \"q\": \"Citez un traumatisme auditif cité par le cours comme cause d'acouphènes.\", \"x\": \"Traumatisme auditif : concert, boîte de nuit, pétard.\", \"a\": \"concert\", \"alt\": [\"boite de nuit\", \"petard\", \"concert boite de nuit petard\"], \"k\": [], \"d\": 3}, {\"id\": \"q067\", \"t\": \"cas\", \"f\": \"f26\", \"ch\": \"b3\", \"q\": \"Quelle est la conduite d'urgence décrite dans le cours ?\", \"x\": \"Traumatisme auditif : traitement d'urgence associant vasodilatateurs, corticoïdes, oxygénothérapie (et traitement étiologique).\", \"o\": [\"Lavage d'oreille immédiat\", \"Vasodilatateurs, corticoïdes et oxygénothérapie, puis traitement étiologique\", \"Antibiotiques locaux\", \"Simple surveillance sans traitement\"], \"c\": 1, \"s\": \"Un jeune homme se plaint d'un sifflement permanent dans les deux oreilles depuis une soirée en boîte de nuit la veille.\", \"d\": 3}, {\"id\": \"q068\", \"t\": \"qcm\", \"f\": \"f27\", \"ch\": \"b4\", \"q\": \"L'othématome est :\", \"x\": \"Othématome : dû à une collection de sang entre le périchondre et le cartilage du pavillon.\", \"o\": [\"Une infection fongique du conduit\", \"Un bouchon épidermique\", \"Une collection de sang entre le périchondre et le cartilage du pavillon\", \"Une perforation du tympan\"], \"c\": 2, \"d\": 2}, {\"id\": \"q069\", \"t\": \"qcm\", \"f\": \"f29\", \"ch\": \"b4\", \"q\": \"Quel germe est responsable du furoncle du conduit auditif externe ?\", \"x\": \"Inflammation des follicules sébacés du CAE due au staphylocoque, siégeant dans le 1/3 externe.\", \"o\": [\"Le pyocyanique\", \"Le streptocoque A\", \"Un champignon\", \"Le staphylocoque\"], \"c\": 3, \"d\": 1}, {\"id\": \"q070\", \"t\": \"qcm\", \"f\": \"f30\", \"ch\": \"b4\", \"q\": \"Quelles circonstances déclenchent classiquement l'otite externe diffuse ?\", \"x\": \"Elle peut être déclenchée par une baignade en piscine, un traumatisme local ou compliquer un eczéma.\", \"o\": [\"Baignade en piscine, traumatisme local, eczéma\", \"Rhinopharyngite du nourrisson\", \"Prise d'aminosides\", \"Chirurgie endonasale\"], \"c\": 0, \"d\": 2}, {\"id\": \"q071\", \"t\": \"qcm\", \"f\": \"f30\", \"ch\": \"b4\", \"q\": \"En cas de perforation tympanique, quels antibiotiques peuvent être instillés dans l'oreille ?\", \"x\": \"Seuls la rifamycine (Otofa) et la lincomycine (Lincocine) sont utilisables en instillation en cas de perforation.\", \"o\": [\"Polydexa et Panotile\", \"Rifamycine (Otofa) et lincomycine (Lincocine)\", \"Pevaryl et Kétoderm\", \"Aminosides en gouttes\"], \"c\": 1, \"d\": 3}, {\"id\": \"q072\", \"t\": \"qcm\", \"f\": \"f31\", \"ch\": \"b4\", \"q\": \"Quel germe retrouve-t-on le plus souvent dans le pus de la périchondrite aiguë ?\", \"x\": \"Le pavillon se fistulise avec un écoulement purulent contenant le plus souvent du pyocyanique.\", \"o\": [\"Le staphylocoque doré\", \"Moraxella catarrhalis\", \"Le pyocyanique\", \"Le pneumocoque\"], \"c\": 2, \"d\": 2}, {\"id\": \"q073\", \"t\": \"vf\", \"f\": \"f27\", \"ch\": \"b4\", \"q\": \"Pour extraire un corps étranger de l'oreille externe, la pince est l'instrument à privilégier.\", \"x\": \"Faux : selon le cours, « leur extraction s'effectue par lavage ou au crochet, la pince est à éviter ».\", \"v\": false, \"d\": 1}, {\"id\": \"q074\", \"t\": \"vf\", \"f\": \"f30\", \"ch\": \"b4\", \"q\": \"Dans l'otite externe diffuse, le tympan est généralement normal.\", \"x\": \"Vrai : « le tympan est généralement normal, parfois un peu rouge ».\", \"v\": true, \"d\": 1}, {\"id\": \"q075\", \"t\": \"vf\", \"f\": \"f31\", \"ch\": \"b4\", \"q\": \"L'otomycose se traite par antimycosiques locaux pendant 2 à 3 semaines.\", \"x\": \"Vrai : Pevaryl 1 % lait ou lotion, Kétoderm crème… pendant 2 à 3 semaines.\", \"v\": true, \"d\": 1}, {\"id\": \"q076\", \"t\": \"open\", \"f\": \"f29\", \"ch\": \"b4\", \"q\": \"Quel est le signe le plus important du furoncle du conduit ?\", \"x\": \"La douleur est le signe le plus important : précoce, intense, réveillée par la mobilisation du pavillon, la mastication et la pression du tragus.\", \"a\": \"la douleur\", \"alt\": [\"douleur\", \"otalgie\"], \"k\": [], \"d\": 3}, {\"id\": \"q077\", \"t\": \"open\", \"f\": \"f28\", \"ch\": \"b4\", \"q\": \"Avec quel produit ramollit-on un bouchon de cérumen avant le lavage ?\", \"x\": \"Extraction par lavage après instillation pendant quelques minutes d'un antiseptique moussant destiné à le ramollir.\", \"a\": \"antiseptique moussant\", \"alt\": [\"un antiseptique moussant\"], \"k\": [\"antiseptique\", \"moussant\"], \"d\": 3}, {\"id\": \"q078\", \"t\": \"cas\", \"f\": \"f30\", \"ch\": \"b4\", \"q\": \"Quel traitement local de base le cours propose-t-il ?\", \"x\": \"Otite externe diffuse : nettoyage du CAE au SP, gouttes ATB-corticoïde (Panotile, Polydexa, Colicort), méchage si rétréci, antalgique.\", \"o\": [\"Paracentèse en urgence\", \"Pénicilline 3 à 4 millions d'unités/j\", \"Lavage d'oreille sous pression\", \"Nettoyage au sérum physiologique et gouttes antibiotique-corticoïde\"], \"c\": 3, \"s\": \"Adolescent de 15 ans, nageur, se plaint d'une douleur de l'oreille gauche majorée quand on tire le pavillon, avec un écoulement fétide. Le CAE est œdématié sur toute sa longueur, le tympan est normal.\", \"d\": 3}, {\"id\": \"q079\", \"t\": \"qcm\", \"f\": \"f32\", \"ch\": \"b5\", \"q\": \"L'OMA du nourrisson survient le plus souvent au décours :\", \"x\": \"Elle survient la plupart du temps au décours d'une rhinopharyngite ; les autres causes sont rares.\", \"o\": [\"D'une rhinopharyngite\", \"D'une baignade en piscine\", \"D'un traumatisme sonore\", \"D'un bouchon de cérumen\"], \"c\": 0, \"d\": 3}, {\"id\": \"q080\", \"t\": \"qcm\", \"f\": \"f33\", \"ch\": \"b5\", \"q\": \"À l'otoscopie, un tympan opaque, terne et bombé évoque :\", \"x\": \"OMA suppurée collectée : tympan plus ou moins opaque, terne, bombé, manche du marteau peu visible.\", \"o\": [\"Une otite congestive\", \"Une OMA suppurée collectée\", \"Une OMA suppurée perforée\", \"Une otite externe diffuse\"], \"c\": 1, \"d\": 2}, {\"id\": \"q081\", \"t\": \"qcm\", \"f\": \"f34\", \"ch\": \"b5\", \"q\": \"Quelle dose d'amoxicilline-acide clavulanique le cours propose-t-il pour l'OMA du nourrisson ?\", \"x\": \"Antibiotique : amoxicilline + acide clavulanique 80 à 100 mg/kg/jour.\", \"o\": [\"20 à 30 mg/kg/jour\", \"3 à 4 millions d'unités/jour\", \"80 à 100 mg/kg/jour\", \"0,5 à 1 mg/kg/jour\"], \"c\": 2, \"d\": 1}, {\"id\": \"q082\", \"t\": \"qcm\", \"f\": \"f34\", \"ch\": \"b5\", \"q\": \"À quel stade la paracentèse est-elle indiquée ?\", \"x\": \"Paracentèse au stade suppuré collecté.\", \"o\": [\"Au stade congestif\", \"Après guérison\", \"Au stade de perforation\", \"Au stade suppuré collecté\"], \"c\": 3, \"d\": 2}, {\"id\": \"q083\", \"t\": \"qcm\", \"f\": \"f35\", \"ch\": \"b5\", \"q\": \"Laquelle est une complication de l'OMA du nourrisson ?\", \"x\": \"Complications : OMA récidivantes, mastoïdites aiguës, paralysies faciales otitiques, méningite.\", \"o\": [\"La mastoïdite aiguë\", \"L'othématome\", \"La presbyacousie\", \"L'otomycose\"], \"c\": 0, \"d\": 3}, {\"id\": \"q084\", \"t\": \"vf\", \"f\": \"f33\", \"ch\": \"b5\", \"q\": \"Chez le nourrisson, les otites sont bilatérales dans plus de la moitié des cas.\", \"x\": \"Vrai : phrase du cours.\", \"v\": true, \"d\": 1}, {\"id\": \"q085\", \"t\": \"vf\", \"f\": \"f34\", \"ch\": \"b5\", \"q\": \"La vaccination contre le pneumocoque et l'Haemophilus influenzae augmente la fréquence des otites résistantes.\", \"x\": \"Faux : selon le cours, elle « réduit la fréquence des otites chez les enfants et en particulier celles à germes résistants ».\", \"v\": false, \"d\": 1}, {\"id\": \"q086\", \"t\": \"open\", \"f\": \"f34\", \"ch\": \"b5\", \"q\": \"Quelle est la posologie de Célestine solution dans l'OMA du nourrisson (gouttes/kg/jour) ?\", \"x\": \"Célestine solution 10 gouttes/kg/jour.\", \"a\": \"10 gouttes/kg/jour\", \"alt\": [\"10\", \"10 gouttes\", \"dix gouttes\"], \"k\": [], \"d\": 3}, {\"id\": \"q087\", \"t\": \"open\", \"f\": \"f33\", \"ch\": \"b5\", \"q\": \"Sur quel examen repose le diagnostic d'OMA ?\", \"x\": \"Le diagnostic repose sur l'otoscopie, après nettoyage atraumatique du CAE.\", \"a\": \"otoscopie\", \"alt\": [\"l'otoscopie\", \"otoscope\"], \"k\": [], \"d\": 3}, {\"id\": \"q088\", \"t\": \"cas\", \"f\": \"f33\", \"ch\": \"b5\", \"q\": \"Quel est le diagnostic le plus probable ?\", \"x\": \"Tympan rouge et épaissi avec hypervascularisation du manche du marteau : otite congestive.\", \"o\": [\"OMA suppurée perforée\", \"Otite moyenne aiguë congestive\", \"Otite externe diffuse\", \"Bouchon de cérumen\"], \"c\": 1, \"s\": \"Nourrisson de 10 mois, fébrile depuis 2 jours après un rhume, pleure et porte la main à l'oreille. À l'otoscopie : tympan rouge, épaissi, manche du marteau hypervascularisé, non bombé.\", \"d\": 3}, {\"id\": \"q089\", \"t\": \"qcm\", \"f\": \"f36\", \"ch\": \"c1\", \"q\": \"Dans 90 % des cas, l'épistaxis provient :\", \"x\": \"Dans 90 % des cas, la tache vasculaire (Kisselbach) sur la cloison, à environ 1 cm de l'entrée narinaire.\", \"o\": [\"Du sinus maxillaire\", \"Des cornets inférieurs\", \"De la tache vasculaire de Kisselbach sur la cloison\", \"Du rhinopharynx\"], \"c\": 2, \"d\": 1}, {\"id\": \"q090\", \"t\": \"qcm\", \"f\": \"f38\", \"ch\": \"c1\", \"q\": \"Combien de temps dure la compression bidigitale d'une épistaxis bénigne ?\", \"x\": \"Compression bidigitale des ailes du nez pendant 10 minutes, tête penchée en avant.\", \"o\": [\"2 minutes\", \"30 minutes\", \"48 heures\", \"10 minutes\"], \"c\": 3, \"d\": 2}, {\"id\": \"q091\", \"t\": \"qcm\", \"f\": \"f38\", \"ch\": \"c1\", \"q\": \"Dans quel délai maximal la mèche d'un tamponnement antérieur doit-elle être retirée ?\", \"x\": \"Mèche enlevée au plus tard 48 h après, pour prévenir tout risque de nécrose septale.\", \"o\": [\"48 heures\", \"24 heures\", \"5 jours\", \"7 jours\"], \"c\": 0, \"d\": 3}, {\"id\": \"q092\", \"t\": \"qcm\", \"f\": \"f37\", \"ch\": \"c1\", \"q\": \"L'angiofibrome juvénile est une tumeur :\", \"x\": \"Tumeur de l'adolescent de sexe masculin, très hémorragique (fibrome nasopharyngien).\", \"o\": [\"Maligne de la femme âgée\", \"Bénigne, très hémorragique, de l'adolescent de sexe masculin\", \"Bénigne de la petite fille\", \"Maligne du sinus maxillaire\"], \"c\": 1, \"d\": 2}, {\"id\": \"q093\", \"t\": \"qcm\", \"f\": \"f39\", \"ch\": \"c1\", \"q\": \"Lequel ne fait PAS partie de la CAT devant une épistaxis grave ?\", \"x\": \"Épistaxis grave : hospitalisation, TA, voie veineuse, groupage, tamponnement antérieur voire postérieur, ATB et hémostatique parentéral.\", \"o\": [\"Voie veineuse\", \"Groupage sanguin\", \"Compression simple puis retour à domicile\", \"Tamponnement antérieur voire postérieur\"], \"c\": 2, \"d\": 1}, {\"id\": \"q094\", \"t\": \"vf\", \"f\": \"f37\", \"ch\": \"c1\", \"q\": \"Il est important de prendre la TA chez tout malade adulte ayant une épistaxis.\", \"x\": \"Vrai : l'HTA est la première cause citée.\", \"v\": true, \"d\": 1}, {\"id\": \"q095\", \"t\": \"vf\", \"f\": \"f38\", \"ch\": \"c1\", \"q\": \"Pendant la compression d'une épistaxis, la tête doit être penchée en arrière.\", \"x\": \"Faux : selon le cours, compression des ailes du nez « pendant 10 minutes tête penchée en avant ».\", \"v\": false, \"d\": 1}, {\"id\": \"q096\", \"t\": \"vf\", \"f\": \"f37\", \"ch\": \"c1\", \"q\": \"La grossesse fait partie des causes d'épistaxis citées par le cours.\", \"x\": \"Vrai : rubrique « autres causes » : CE chez l'enfant, perforation septale avec croûte, grossesse.\", \"v\": true, \"d\": 1}, {\"id\": \"q097\", \"t\": \"open\", \"f\": \"f37\", \"ch\": \"c1\", \"q\": \"Quelle maladie hémorragique est aussi appelée angiomatose hémorragique familiale ?\", \"x\": \"Maladie de Rendu-Osler (angiomatose hémorragique familiale).\", \"a\": \"maladie de Rendu-Osler\", \"alt\": [\"rendu osler\", \"rendu-osler\", \"osler\"], \"k\": [\"rendu\", \"osler\"], \"d\": 3}, {\"id\": \"q098\", \"t\": \"cas\", \"f\": \"f38\", \"ch\": \"c1\", \"q\": \"Quelle est la prochaine étape ?\", \"x\": \"Épistaxis bénigne : compression bidigitale 10 min tête en avant (coton imbibé d'eau oxygénée ou de thrombase) ; méchage seulement si échec.\", \"o\": [\"Tamponnement postérieur d'emblée\", \"Transfusion\", \"Trachéotomie\", \"Compression bidigitale 10 min tête penchée en avant\"], \"c\": 3, \"s\": \"Femme de 45 ans, saignement modéré par la narine droite depuis 15 min, constantes normales. Après mouchage et pulvérisation de lidocaïne-naphazoline, l'origine est sur la cloison antérieure.\", \"d\": 3}, {\"id\": \"q099\", \"t\": \"cas\", \"f\": \"f39\", \"ch\": \"c1\", \"q\": \"Quelle conduite est prioritaire ?\", \"x\": \"Épistaxis grave (retentissement hémodynamique) : hospitalisation, TA, voie veineuse (choc), groupage (transfusion), tamponnement, ATB + hémostatique parentéral.\", \"o\": [\"Hospitalisation, voie veineuse, groupage, tamponnement antérieur voire postérieur\", \"Compression 10 min et sortie\", \"Lavage de nez au sérum froid\", \"Antihistaminique oral\"], \"c\": 0, \"s\": \"Homme de 68 ans hypertendu, épistaxis abondante récidivante, pâle, pouls rapide, TA basse.\", \"d\": 3}, {\"id\": \"q100\", \"t\": \"qcm\", \"f\": \"f41\", \"ch\": \"c2\", \"q\": \"La triade de la rhinite allergique comprend :\", \"x\": \"Triade symptomatique brutale : obstruction nasale, éternuements en salve et rhinorrhée aqueuse.\", \"o\": [\"Fièvre, otalgie, rhinorrhée purulente\", \"Obstruction nasale, éternuements en salve, rhinorrhée aqueuse\", \"Épistaxis, anosmie, céphalée\", \"Douleur sous-orbitaire, cacosmie, fièvre\"], \"c\": 1, \"d\": 2}, {\"id\": \"q101\", \"t\": \"qcm\", \"f\": \"f41\", \"ch\": \"c2\", \"q\": \"Une rhinite allergique est dite persistante si les symptômes durent :\", \"x\": \"Persistante : > 4 jours/semaine et > 4 semaines/an ; intermittente : < 4 jours/semaine ou < 4 semaines/an.\", \"o\": [\"Moins de 4 jours par semaine\", \"Moins de 12 semaines\", \"Plus de 4 jours par semaine et plus de 4 semaines dans l'année\", \"Plus de 3 semaines\"], \"c\": 2, \"d\": 1}, {\"id\": \"q102\", \"t\": \"qcm\", \"f\": \"f41\", \"ch\": \"c2\", \"q\": \"Une rhinite allergique est dite sévère si le patient présente :\", \"x\": \"Formes sévères : au moins un des symptômes cités ; formes modérées : aucun.\", \"o\": [\"Aucun de ces symptômes\", \"Une fièvre supérieure à 39 °C\", \"Une épistaxis\", \"Au moins un symptôme parmi troubles du sommeil, gêne des activités, gêne professionnelle/scolaire, symptômes invalidants\"], \"c\": 3, \"d\": 2}, {\"id\": \"q103\", \"t\": \"qcm\", \"f\": \"f42\", \"ch\": \"c2\", \"q\": \"Quel élément définit la NARES ?\", \"x\": \"NARES : rhinite non allergique à éosinophiles (> 20 %), enquête allergique négative.\", \"o\": [\"Éosinophiles > 20 % dans les sécrétions avec enquête allergique négative\", \"Enquête allergique positive\", \"Neutrophiles > 50 %\", \"Rhinite au 3e trimestre de grossesse\"], \"c\": 0, \"d\": 3}, {\"id\": \"q104\", \"t\": \"qcm\", \"f\": \"f42\", \"ch\": \"c2\", \"q\": \"Lequel est cité comme médicament pouvant provoquer une rhinite ?\", \"x\": \"Rhinites médicamenteuses : aspirine, réserpine, guanéthidine, IEC ; vasoconstricteurs au long cours.\", \"o\": [\"Le paracétamol\", \"Les inhibiteurs de l'enzyme de conversion\", \"L'amoxicilline\", \"La nystatine\"], \"c\": 1, \"d\": 2}, {\"id\": \"q105\", \"t\": \"vf\", \"f\": \"f40\", \"ch\": \"c2\", \"q\": \"Les rhinites infectieuses sont dites chroniques au-delà de 12 semaines.\", \"x\": \"Vrai : aiguës si les symptômes disparaissent en moins de 12 semaines, chroniques au-delà.\", \"v\": true, \"d\": 1}, {\"id\": \"q106\", \"t\": \"vf\", \"f\": \"f43\", \"ch\": \"c2\", \"q\": \"Le traitement des rhinites repose sur un vasoconstricteur de longue durée.\", \"x\": \"Faux : selon le cours, « désobstruer les fosses nasales par un vasoconstricteur de courte durée ».\", \"v\": false, \"d\": 1}, {\"id\": \"q107\", \"t\": \"open\", \"f\": \"f43\", \"ch\": \"c2\", \"q\": \"Quelle classe de médicament le cours utilise-t-il pour lutter contre l'allergie dans les rhinites ?\", \"x\": \"Traitement : « lutter contre l'allergie en donnant un antihistaminique », avec éviction de l'allergène.\", \"a\": \"antihistaminique\", \"alt\": [\"antihistaminiques\", \"un antihistaminique\", \"anti histaminique\"], \"k\": [], \"d\": 3}, {\"id\": \"q108\", \"t\": \"cas\", \"f\": \"f41\", \"ch\": \"c2\", \"q\": \"Comment classer cette rhinite allergique ?\", \"x\": \"< 4 jours/semaine → intermittente ; aucun critère de gravité → modérée.\", \"o\": [\"Persistante sévère\", \"Intermittente sévère\", \"Intermittente modérée\", \"Persistante modérée\"], \"c\": 2, \"s\": \"Étudiante de 20 ans : éternuements en salve, nez qui coule « comme de l'eau » et nez bouché, 2 jours par semaine pendant la saison des pollens, sans retentissement sur le sommeil ni les cours.\", \"d\": 3}, {\"id\": \"q109\", \"t\": \"qcm\", \"f\": \"f45\", \"ch\": \"c3\", \"q\": \"Quel est le sinus le plus fréquemment atteint dans les sinusites aiguës ?\", \"x\": \"La sinusite maxillaire aiguë est la plus fréquente.\", \"o\": [\"Le sinus frontal\", \"Le sinus sphénoïdal\", \"L'ethmoïde postérieur\", \"Le sinus maxillaire\"], \"c\": 3, \"d\": 1}, {\"id\": \"q110\", \"t\": \"qcm\", \"f\": \"f45\", \"ch\": \"c3\", \"q\": \"La douleur de la sinusite maxillaire aiguë est :\", \"x\": \"Douleur faciale unilatérale, sous-orbitaire, pulsatile, augmentée par la position penchée en avant et la toux.\", \"o\": [\"Unilatérale, sous-orbitaire, pulsatile, augmentée tête penchée en avant\", \"Bilatérale et frontale\", \"Rétro-sternale\", \"Calmée par la toux\"], \"c\": 0, \"d\": 2}, {\"id\": \"q111\", \"t\": \"qcm\", \"f\": \"f45\", \"ch\": \"c3\", \"q\": \"Quelle incidence radiographique montre l'opacité du sinus maxillaire ?\", \"x\": \"La radiographie en incidence de Blondeau montre une opacité constante du sinus maxillaire.\", \"o\": [\"Le cliché de profil du cavum\", \"L'incidence de Blondeau\", \"La radio du thorax\", \"L'incidence de Schüller\"], \"c\": 1, \"d\": 3}, {\"id\": \"q112\", \"t\": \"qcm\", \"f\": \"f46\", \"ch\": \"c3\", \"q\": \"Durée de l'antibiothérapie dans la sinusite maxillaire aiguë :\", \"x\": \"Antibiothérapie générale pendant 10 jours ; corticothérapie en cure courte de 5 jours.\", \"o\": [\"5 jours\", \"3 jours\", \"10 jours\", \"21 jours\"], \"c\": 2, \"d\": 2}, {\"id\": \"q113\", \"t\": \"qcm\", \"f\": \"f46\", \"ch\": \"c3\", \"q\": \"Quand donner l'antihistaminique dans la sinusite maxillaire aiguë ?\", \"x\": \"« Lutter contre l'allergie par un antihistaminique après le traitement antibiotique ».\", \"o\": [\"Avant l'antibiotique\", \"À la place de l'antibiotique\", \"Jamais\", \"Après le traitement antibiotique\"], \"c\": 3, \"d\": 1}, {\"id\": \"q114\", \"t\": \"vf\", \"f\": \"f44\", \"ch\": \"c3\", \"q\": \"La sinusite aiguë évolue depuis moins de trois semaines.\", \"x\": \"Vrai : définition du cours.\", \"v\": true, \"d\": 1}, {\"id\": \"q115\", \"t\": \"vf\", \"f\": \"f45\", \"ch\": \"c3\", \"q\": \"La sinusite maxillaire aiguë est habituellement bilatérale.\", \"x\": \"Faux : selon le cours, « elle est habituellement unilatérale » ; si tous les sinus homolatéraux sont atteints : pansinusite.\", \"v\": false, \"d\": 1}, {\"id\": \"q116\", \"t\": \"open\", \"f\": \"f45\", \"ch\": \"c3\", \"q\": \"Comment appelle-t-on l'atteinte de tous les sinus d'un même côté ?\", \"x\": \"Si tous les sinus homolatéraux sont atteints, on parle de pansinusite aiguë.\", \"a\": \"pansinusite\", \"alt\": [\"pansinusite aigue\", \"pan sinusite\"], \"k\": [], \"d\": 3}, {\"id\": \"q117\", \"t\": \"cas\", \"f\": \"f45\", \"ch\": \"c3\", \"q\": \"Quelle corticothérapie le cours associe-t-il au traitement ?\", \"x\": \"Sinusite maxillaire aiguë : ATB 10 jours + corticothérapie 5 jours à 0,5-1 mg/kg/j (Cortancyl) + soins locaux.\", \"o\": [\"Cure courte de 5 jours à 0,5-1 mg/kg/j (Cortancyl)\", \"Célestine 10 gouttes/kg/j\", \"Corticoïde IVD en urgence\", \"Aucune corticothérapie\"], \"c\": 0, \"s\": \"Homme de 30 ans, 5 jours après un rhume : douleur pulsatile sous l'œil gauche, pire quand il se penche, rhinorrhée purulente gauche, cacosmie. Pus au méat moyen gauche.\", \"d\": 3}, {\"id\": \"q118\", \"t\": \"qcm\", \"f\": \"f47\", \"ch\": \"c4\", \"q\": \"Les végétations adénoïdes correspondent à l'hypertrophie de :\", \"x\": \"Hypertrophie du tissu lymphoïde de la paroi postéro-supérieure du rhinopharynx : amygdale pharyngée de Luschka.\", \"o\": [\"L'amygdale palatine\", \"L'amygdale pharyngée de Luschka\", \"L'amygdale linguale\", \"Des cornets inférieurs\"], \"c\": 1, \"d\": 2}, {\"id\": \"q119\", \"t\": \"qcm\", \"f\": \"f48\", \"ch\": \"c4\", \"q\": \"Quel signe traduit la surinfection adénoïdienne ?\", \"x\": \"La rhinorrhée muco-purulente traduit la surinfection adénoïdienne.\", \"o\": [\"Un ronflement nocturne\", \"Une respiration buccale\", \"Une rhinorrhée muco-purulente\", \"Une otalgie réflexe\"], \"c\": 2, \"d\": 3}, {\"id\": \"q120\", \"t\": \"qcm\", \"f\": \"f48\", \"ch\": \"c4\", \"q\": \"Dans quelles conditions réalise-t-on le cliché de profil du cavum ?\", \"x\": \"Végétations visibles sur un cliché de profil du cavum en inspiration et bouche fermée.\", \"o\": [\"En expiration bouche ouverte\", \"En position couchée tête en arrière\", \"Après un repas\", \"En inspiration et bouche fermée\"], \"c\": 3, \"d\": 2}, {\"id\": \"q121\", \"t\": \"qcm\", \"f\": \"f49\", \"ch\": \"c4\", \"q\": \"L'adénoïdectomie est indiquée en cas de :\", \"x\": \"Traitement : adénoïdectomie si rhonchopathie invalidante avec apnée du sommeil.\", \"o\": [\"Rhonchopathie invalidante avec apnée du sommeil\", \"Rhume simple\", \"Épistaxis bénigne\", \"Rhinite allergique intermittente\"], \"c\": 0, \"d\": 1}, {\"id\": \"q122\", \"t\": \"vf\", \"f\": \"f49\", \"ch\": \"c4\", \"q\": \"Les otites moyennes aiguës récidivantes sont une complication tubotympanique des végétations.\", \"x\": \"Vrai : complications tubotympaniques : OMA récidivantes et otites séro-muqueuses.\", \"v\": true, \"d\": 1}, {\"id\": \"q123\", \"t\": \"vf\", \"f\": \"f48\", \"ch\": \"c4\", \"q\": \"Les végétations adénoïdes donnent une obstruction nasale unilatérale.\", \"x\": \"Faux : selon le cours, « obstruction nasale bilatérale entraînant une respiration buccale, un ronflement nocturne, des troubles du sommeil ».\", \"v\": false, \"d\": 1}, {\"id\": \"q124\", \"t\": \"open\", \"f\": \"f49\", \"ch\": \"c4\", \"q\": \"Quel est le traitement chirurgical des végétations adénoïdes ?\", \"x\": \"Adénoïdectomie si rhonchopathie invalidante avec apnée du sommeil.\", \"a\": \"adénoïdectomie\", \"alt\": [\"adenoidectomie\", \"ablation des vegetations\"], \"k\": [], \"d\": 3}, {\"id\": \"q125\", \"t\": \"cas\", \"f\": \"f48\", \"ch\": \"c4\", \"q\": \"Quel diagnostic évoquer ?\", \"x\": \"Obstruction nasale bilatérale + respiration buccale + ronflement + OMA récidivantes : végétations adénoïdes.\", \"o\": [\"Rhinite allergique\", \"Végétations adénoïdes obstructives\", \"Corps étranger nasal unilatéral\", \"Sinusite maxillaire aiguë\"], \"c\": 1, \"s\": \"Enfant de 4 ans : respire bouche ouverte, ronfle la nuit, dort mal, otites à répétition. Quand on ferme sa bouche, il ne peut pas respirer par le nez.\", \"d\": 3}, {\"id\": \"q126\", \"t\": \"qcm\", \"f\": \"f50\", \"ch\": \"d1\", \"q\": \"La rhinopharyngite est le plus souvent d'origine :\", \"x\": \"Inflammation aiguë de la muqueuse des FN et du rhinopharynx le plus souvent d'origine virale.\", \"o\": [\"Bactérienne\", \"Fongique\", \"Virale\", \"Allergique\"], \"c\": 2, \"d\": 2}, {\"id\": \"q127\", \"t\": \"qcm\", \"f\": \"f53\", \"ch\": \"d1\", \"q\": \"Quelle est la complication la plus fréquente de la rhinopharyngite ?\", \"x\": \"Complications : otite moyenne aiguë la plus fréquente, puis laryngite, trachéobronchite, phlegmon, sinusite, ethmoïdite.\", \"o\": [\"La sinusite maxillaire\", \"Le phlegmon rétro-pharyngé\", \"L'ethmoïdite aiguë\", \"L'otite moyenne aiguë\"], \"c\": 3, \"d\": 3}, {\"id\": \"q128\", \"t\": \"qcm\", \"f\": \"f50\", \"ch\": \"d1\", \"q\": \"La fièvre de début de la rhinopharyngite est typiquement :\", \"x\": \"Fièvre d'apparition brutale et souvent élevée (39 à 40 °C).\", \"o\": [\"Brutale et souvent élevée (39 à 40 °C)\", \"Progressive et modérée à 38 °C\", \"Absente\", \"Intermittente sur 3 semaines\"], \"c\": 0, \"d\": 2}, {\"id\": \"q129\", \"t\": \"qcm\", \"f\": \"f53\", \"ch\": \"d1\", \"q\": \"En cas de complication, l'antibiotique est donné pendant :\", \"x\": \"Traitement des complications : anti-inflammatoire et antibiotique (amoxicilline ± acide clavulanique) pendant 8 jours ; contrôle une semaine après.\", \"o\": [\"3 jours\", \"8 jours\", \"10 jours\", \"21 jours\"], \"c\": 1, \"d\": 1}, {\"id\": \"q130\", \"t\": \"vf\", \"f\": \"f52\", \"ch\": \"d1\", \"q\": \"Dans une rhinopharyngite non compliquée, l'antibiothérapie est inutile.\", \"x\": \"Vrai : phrase du cours.\", \"v\": true, \"d\": 1}, {\"id\": \"q131\", \"t\": \"vf\", \"f\": \"f52\", \"ch\": \"d1\", \"q\": \"La guérison complète d'une rhinopharyngite survient habituellement en 15 jours.\", \"x\": \"Faux : selon le cours, « la guérison complète survient habituellement en 5 jours ».\", \"v\": false, \"d\": 1}, {\"id\": \"q132\", \"t\": \"open\", \"f\": \"f51\", \"ch\": \"d1\", \"q\": \"Quel examen de l'oreille montre une congestion de la membrane tympanique dans la rhinopharyngite ?\", \"x\": \"L'otoscopie montre une congestion de la membrane tympanique.\", \"a\": \"otoscopie\", \"alt\": [\"l'otoscopie\"], \"k\": [], \"d\": 3}, {\"id\": \"q133\", \"t\": \"cas\", \"f\": \"f52\", \"ch\": \"d1\", \"q\": \"Quel soin local de base faut-il expliquer à la mère ?\", \"x\": \"Rhinopharyngite non compliquée : désinfection au SP plusieurs fois par jour, aspiration (mouche-bébé) ; antibiotique inutile.\", \"o\": [\"Antibiotique pendant 8 jours d'emblée\", \"Méchage antérieur\", \"Désinfection rhinopharyngée pluriquotidienne au sérum physiologique\", \"Vasoconstricteur nasal au long cours\"], \"c\": 2, \"s\": \"Enfant de 2 ans : fièvre à 39,5 °C depuis hier, nez bouché, rhinorrhée séreuse, yeux rouges. Tympans simplement congestifs, état général conservé.\", \"d\": 3}, {\"id\": \"q134\", \"t\": \"qcm\", \"f\": \"f54\", \"ch\": \"d2\", \"q\": \"L'odynophagie désigne :\", \"x\": \"Douleurs plus importantes lors de la déglutition : odynophagie ; enrouement : dysphonie.\", \"o\": [\"Un enrouement de la voix\", \"Une perte du goût\", \"Une difficulté respiratoire\", \"Une douleur lors de la déglutition\"], \"c\": 3, \"d\": 2}, {\"id\": \"q135\", \"t\": \"qcm\", \"f\": \"f55\", \"ch\": \"d2\", \"q\": \"La pharyngite chronique dure :\", \"x\": \"La pharyngite chronique s'installe progressivement et dure plus de trois semaines.\", \"o\": [\"Plus de trois semaines\", \"Quelques jours à une semaine\", \"Moins de 48 heures\", \"Exactement 10 jours\"], \"c\": 0, \"d\": 3}, {\"id\": \"q136\", \"t\": \"qcm\", \"f\": \"f56\", \"ch\": \"d2\", \"q\": \"Quelle complication générale peut suivre une pharyngite à streptocoque ?\", \"x\": \"Complications : abcès péri-pharyngé, otites, sinusites, laryngites, trachéobronchites, pneumonies, GNA post-streptococcique, RAA.\", \"o\": [\"La presbyacousie\", \"La glomérulonéphrite aiguë post-streptococcique\", \"L'otomycose\", \"La rhinite allergique\"], \"c\": 1, \"d\": 2}, {\"id\": \"q137\", \"t\": \"qcm\", \"f\": \"f57\", \"ch\": \"d2\", \"q\": \"Comment se présente l'examen d'une pharyngite mycosique ?\", \"x\": \"À l'examen : plaques de couleur blanc crème.\", \"o\": [\"Des amygdales rouges sans dépôt\", \"Un tympan bombé\", \"Des plaques de couleur blanc crème\", \"Un pus au méat moyen\"], \"c\": 2, \"d\": 1}, {\"id\": \"q138\", \"t\": \"vf\", \"f\": \"f56\", \"ch\": \"d2\", \"q\": \"Selon le cours, la pharyngite est bactérienne dans 30 % des cas (streptocoque β-hémolytique du groupe A).\", \"x\": \"Vrai (p. 38) ; à rapprocher de la mention « 90 % virales » pour les rhinopharyngites (p. 37).\", \"v\": true, \"d\": 1}, {\"id\": \"q139\", \"t\": \"vf\", \"f\": \"f55\", \"ch\": \"d2\", \"q\": \"La pharyngite chronique est plus fréquente chez l'enfant que chez l'adulte.\", \"x\": \"Faux : selon le cours, « la pharyngite chronique est plus fréquente chez l'adulte que chez l'enfant ».\", \"v\": false, \"d\": 1}, {\"id\": \"q140\", \"t\": \"vf\", \"f\": \"f54\", \"ch\": \"d2\", \"q\": \"Dans la pharyngite aiguë, la fièvre est typiquement supérieure à 40 °C.\", \"x\": \"Faux : selon le cours, pharyngite aiguë : « fièvre modérée à 38 °C ».\", \"v\": false, \"d\": 1}, {\"id\": \"q141\", \"t\": \"open\", \"f\": \"f57\", \"ch\": \"d2\", \"q\": \"Citez un antifongique utilisé dans la pharyngite mycosique.\", \"x\": \"Nystatine (Mycostatine) à sucer, amphotéricine (Fungizone) ou miconazole (Daktarin) en gel.\", \"a\": \"nystatine\", \"alt\": [\"mycostatine\", \"amphotericine\", \"fungizone\", \"miconazole\", \"daktarin\"], \"k\": [], \"d\": 3}, {\"id\": \"q142\", \"t\": \"cas\", \"f\": \"f55\", \"ch\": \"d2\", \"q\": \"Quel diagnostic évoquer ?\", \"x\": \"> 3 semaines, symptômes localisés, sans fièvre, terrain (tabac, métier d'enseignant) : pharyngite chronique.\", \"o\": [\"Angine érythémato-pultacée\", \"Pharyngite aiguë virale\", \"Corps étranger du pharynx\", \"Pharyngite chronique\"], \"c\": 3, \"s\": \"Enseignante de 45 ans, fumeuse, se plaint depuis 2 mois de gorge sèche, besoin constant de se racler la gorge, douleur à la déglutition, sans fièvre.\", \"d\": 3}, {\"id\": \"q143\", \"t\": \"qcm\", \"f\": \"f58\", \"ch\": \"d3\", \"q\": \"L'angine aiguë est l'inflammation de :\", \"x\": \"On appelle angine aiguë l'inflammation de l'oropharynx et des amygdales palatines.\", \"o\": [\"L'oropharynx et des amygdales palatines\", \"Du rhinopharynx seul\", \"Du larynx\", \"Des sinus maxillaires\"], \"c\": 0, \"d\": 3}, {\"id\": \"q144\", \"t\": \"qcm\", \"f\": \"f59\", \"ch\": \"d3\", \"q\": \"Des amygdales hypertrophiées recouvertes d'un enduit blanchâtre définissent :\", \"x\": \"Tableau typique de l'angine érythémato-pultacée.\", \"o\": [\"La pharyngite mycosique\", \"L'angine érythémato-pultacée\", \"Le phlegmon péri-amygdalien\", \"La rhinopharyngite\"], \"c\": 1, \"d\": 2}, {\"id\": \"q145\", \"t\": \"qcm\", \"f\": \"f60\", \"ch\": \"d3\", \"q\": \"Quelle est la complication la plus courante de l'angine non traitée ?\", \"x\": \"L'évolution sans traitement peut se faire vers un phlegmon péri-amygdalien, complication la plus courante.\", \"o\": [\"L'otomycose\", \"L'ethmoïdite\", \"Le phlegmon péri-amygdalien\", \"La surdité de perception\"], \"c\": 2, \"d\": 1}, {\"id\": \"q146\", \"t\": \"qcm\", \"f\": \"f59\", \"ch\": \"d3\", \"q\": \"Que montre la NFS dans l'angine ?\", \"x\": \"Signes biologiques : hyperleucocytose à polynucléaires.\", \"o\": [\"Une éosinophilie > 20 %\", \"Une thrombopénie\", \"Une NFS normale\", \"Une hyperleucocytose à polynucléaires\"], \"c\": 3, \"d\": 2}, {\"id\": \"q147\", \"t\": \"vf\", \"f\": \"f58\", \"ch\": \"d3\", \"q\": \"Les angines atteignent surtout les adolescents et les adultes jeunes.\", \"x\": \"Vrai : phrase du cours.\", \"v\": true, \"d\": 1}, {\"id\": \"q148\", \"t\": \"vf\", \"f\": \"f59\", \"ch\": \"d3\", \"q\": \"Le prélèvement de gorge est indispensable pour traiter une angine.\", \"x\": \"Faux : selon le cours, on peut réaliser un prélèvement « mais pas indispensable ».\", \"v\": false, \"d\": 1}, {\"id\": \"q149\", \"t\": \"open\", \"f\": \"f60\", \"ch\": \"d3\", \"q\": \"Pendant combien de jours dure la pénicillinothérapie de l'angine ?\", \"x\": \"Pénicillinothérapie : 3 à 4 millions d'unités par jour pendant 8 jours.\", \"a\": \"8 jours\", \"alt\": [\"8\", \"huit jours\"], \"k\": [], \"d\": 3}, {\"id\": \"q150\", \"t\": \"cas\", \"f\": \"f59\", \"ch\": \"d3\", \"q\": \"Quel traitement le cours propose-t-il ?\", \"x\": \"Angine érythémato-pultacée : pénicillinothérapie 3-4 MUI/j pendant 8 jours, acide acétylsalicylique, antiseptiques locaux, repos au lit.\", \"o\": [\"Pénicilline 3 à 4 millions d'unités/j pendant 8 jours, aspirine, antiseptiques locaux, repos\", \"Nystatine en comprimé à sucer\", \"Adénoïdectomie\", \"Lavage de nez seul\"], \"c\": 0, \"s\": \"Étudiant de 19 ans : frissons, fièvre élevée, douleur de gorge irradiant à l'oreille, amygdales augmentées de volume avec enduit blanchâtre, ganglions cervicaux sensibles et mobiles.\", \"d\": 3}, {\"id\": \"q151\", \"t\": \"qcm\", \"f\": \"f61\", \"ch\": \"d4\", \"q\": \"La dyspnée laryngée est une :\", \"x\": \"Définition : bradypnée inspiratoire avec tirage sus-sternal, cornage et trouble de la voix.\", \"o\": [\"Tachypnée expiratoire avec sibilants\", \"Bradypnée inspiratoire avec tirage, cornage et trouble de la voix\", \"Polypnée superficielle sans tirage\", \"Bradypnée expiratoire\"], \"c\": 1, \"d\": 3}, {\"id\": \"q152\", \"t\": \"qcm\", \"f\": \"f63\", \"ch\": \"d4\", \"q\": \"Au stade 4 de la laryngite sous-glottique, l'enfant est :\", \"x\": \"Stade 4 : inconscient, tirage absent, cornage absent, TA effondrée, pouls filant, cyanose, rythme irrégulier.\", \"o\": [\"Calme avec tirage modéré\", \"Agité avec pouls accéléré\", \"Inconscient, tirage et cornage absents, TA effondrée, pouls filant\", \"Angoissé avec TA élevée\"], \"c\": 2, \"d\": 2}, {\"id\": \"q153\", \"t\": \"qcm\", \"f\": \"f64\", \"ch\": \"d4\", \"q\": \"Quelle position adopter aux stades I et II ?\", \"x\": \"Maintien en position assise, tête en hyperextension.\", \"o\": [\"Décubitus dorsal strict\", \"Position latérale de sécurité\", \"Trendelenburg\", \"Position assise, tête en hyperextension\"], \"c\": 3, \"d\": 1}, {\"id\": \"q154\", \"t\": \"qcm\", \"f\": \"f64\", \"ch\": \"d4\", \"q\": \"Quand réaliser une trachéotomie dans la dyspnée laryngée ?\", \"x\": \"Stades III et IV : intubation nasotrachéale ; trachéotomie lorsqu'il s'agit d'un obstacle mécanique interdisant l'intubation.\", \"o\": [\"Obstacle mécanique interdisant l'intubation (stades III-IV)\", \"Dès le stade I\", \"En cas de stridor du nouveau-né\", \"Jamais\"], \"c\": 0, \"d\": 2}, {\"id\": \"q155\", \"t\": \"qcm\", \"f\": \"f62\", \"ch\": \"d4\", \"q\": \"Quelle cause est typique de l'enfant (et non du nourrisson) ?\", \"x\": \"Chez l'enfant : laryngites aiguës sous-glottiques, CE méconnus, papillomatose, traumatisme.\", \"o\": [\"Le stridor\", \"La laryngite aiguë sous-glottique\", \"La malformation laryngée\", \"Les tumeurs malignes\"], \"c\": 1, \"d\": 3}, {\"id\": \"q156\", \"t\": \"vf\", \"f\": \"f62\", \"ch\": \"d4\", \"q\": \"Le stridor du nouveau-né s'accompagne habituellement de cyanose.\", \"x\": \"Faux : selon le cours, le stridor est une inspiration bruyante aiguë qui « ne s'accompagne ni de gêne respiratoire ni de cyanose ».\", \"v\": false, \"d\": 1}, {\"id\": \"q157\", \"t\": \"vf\", \"f\": \"f61\", \"ch\": \"d4\", \"q\": \"Toute dyspnée obstructive de l'enfant est une urgence.\", \"x\": \"Vrai : elle peut se décompenser rapidement et mettre en jeu le pronostic vital.\", \"v\": true, \"d\": 1}, {\"id\": \"q158\", \"t\": \"open\", \"f\": \"f64\", \"ch\": \"d4\", \"q\": \"Quelle dose d'adrénaline le cours fait-il diluer dans 5 ml de NaCl 0,9 % pour l'aérosol (en mg) ?\", \"x\": \"Casser une ampoule de 1 mg d'adrénaline dans 5 ml de NaCl 0,9 % et l'administrer en aérosol.\", \"a\": \"1 mg\", \"alt\": [\"1\", \"un milligramme\", \"1mg\"], \"k\": [], \"d\": 3}, {\"id\": \"q159\", \"t\": \"open\", \"f\": \"f63\", \"ch\": \"d4\", \"q\": \"Combien de stades de gravité compte la classification des laryngites sous-glottiques ?\", \"x\": \"Classification en 4 stades de gravité croissante.\", \"a\": \"4\", \"alt\": [\"quatre\", \"4 stades\"], \"k\": [], \"d\": 3}, {\"id\": \"q160\", \"t\": \"cas\", \"f\": \"f63\", \"ch\": \"d4\", \"q\": \"À quel stade correspond ce tableau et quelle CAT ?\", \"x\": \"Agité + tirage sus-sternal et xiphoïdien + pouls accéléré + TA normale = stade 2 ; CAT des stades I-II.\", \"o\": [\"Stade 4 : intubation immédiate\", \"Stade 1 : simple surveillance à domicile\", \"Stade 2 : position assise, O2, corticoïde IVD, appel du médecin\", \"Stade 3 : trachéotomie d'emblée\"], \"c\": 2, \"s\": \"Enfant de 3 ans, laryngite : agité, tirage net sus-sternal et xiphoïdien, cornage net, pouls accéléré, TA normale, extrémités roses.\", \"d\": 3}, {\"id\": \"q161\", \"t\": \"qcm\", \"f\": \"f65\", \"ch\": \"d5\", \"q\": \"Quel motif de consultation évoque un corps étranger des fosses nasales ?\", \"x\": \"Motif : obstruction nasale avec rhinorrhée muco-purulente unilatérale, odeur nauséabonde.\", \"o\": [\"Rhinorrhée aqueuse bilatérale\", \"Éternuements en salve\", \"Fièvre à 40 °C isolée\", \"Obstruction nasale avec rhinorrhée muco-purulente unilatérale\"], \"c\": 3, \"d\": 1}, {\"id\": \"q162\", \"t\": \"qcm\", \"f\": \"f67\", \"ch\": \"d5\", \"q\": \"Un corps étranger laryngé volumineux et plein entraîne :\", \"x\": \"S'il est volumineux et plein, il crée un état d'asphyxie aiguë rapidement mortel.\", \"o\": [\"Une asphyxie aiguë rapidement mortelle\", \"Une toux intermittente\", \"Une dysphagie isolée\", \"Une rhinorrhée unilatérale\"], \"c\": 0, \"d\": 2}, {\"id\": \"q163\", \"t\": \"qcm\", \"f\": \"f67\", \"ch\": \"d5\", \"q\": \"Traitement de choix d'un corps étranger trachéal :\", \"x\": \"Le traitement de choix est l'extraction par bronchoscopie au tube rigide à l'aide d'optiques sous anesthésie générale.\", \"o\": [\"Lavage au sérum physiologique\", \"Extraction par bronchoscopie au tube rigide sous anesthésie générale\", \"Antibiothérapie seule\", \"Mouchage en force\"], \"c\": 1, \"d\": 3}, {\"id\": \"q164\", \"t\": \"qcm\", \"f\": \"f68\", \"ch\": \"d5\", \"q\": \"Chez l'adulte, une dysphagie brutale survenue au cours de la nuit évoque :\", \"x\": \"Dysphagie brutale au cours d'un repas (CE alimentaire) ou de la nuit (prothèse dentaire).\", \"o\": [\"Une arête de poisson\", \"Une pièce de monnaie\", \"Une prothèse dentaire dans l'œsophage\", \"Une laryngite\"], \"c\": 2, \"d\": 2}, {\"id\": \"q165\", \"t\": \"qcm\", \"f\": \"f66\", \"ch\": \"d5\", \"q\": \"Devant un CE du pharynx non visible, il faut :\", \"x\": \"S'il est visible : l'extraire avec une pince ; s'il n'est pas visible : évacuer le malade.\", \"o\": [\"Faire un lavage de nez\", \"Faire moucher en force\", \"Donner un antispasmodique et attendre\", \"Évacuer le malade\"], \"c\": 3, \"d\": 1}, {\"id\": \"q166\", \"t\": \"vf\", \"f\": \"f67\", \"ch\": \"d5\", \"q\": \"Le corps étranger trachéal est souvent mobile.\", \"x\": \"Vrai : symptomatologie de troubles respiratoires intermittents (quintes, spasmes, dyspnée expiratoire aux changements de position).\", \"v\": true, \"d\": 1}, {\"id\": \"q167\", \"t\": \"vf\", \"f\": \"f68\", \"ch\": \"d5\", \"q\": \"La radiologie montre toujours le corps étranger de l'œsophage.\", \"x\": \"Faux : selon le cours, « la radiologie montre la présence et la localisation du corps étranger s'il est radio-opaque ».\", \"v\": false, \"d\": 1}, {\"id\": \"q168\", \"t\": \"open\", \"f\": \"f68\", \"ch\": \"d5\", \"q\": \"Dans quel délai le cours recommande-t-il l'extraction d'un CE de l'œsophage (en jours) ?\", \"x\": \"Le seul traitement est l'extraction dans les 2-3 jours.\", \"a\": \"2-3 jours\", \"alt\": [\"2 a 3 jours\", \"2 3 jours\", \"dans les 2-3 jours\"], \"k\": [], \"d\": 3}, {\"id\": \"q169\", \"t\": \"cas\", \"f\": \"f67\", \"ch\": \"d5\", \"q\": \"Quelle est la conduite adaptée ?\", \"x\": \"Syndrome de pénétration dans la journée, sans fièvre + troubles intermittents posturaux : CE trachéal mobile → bronchoscopie rigide.\", \"o\": [\"Évoquer un CE trachéal et orienter pour bronchoscopie au tube rigide sous AG\", \"Traiter une laryngite par antibiotiques\", \"Faire un lavage de nez\", \"Prescrire un antihistaminique\"], \"c\": 0, \"s\": \"Enfant de 2 ans jouant avec des cacahuètes : brusque accès de suffocation et toux dans l'après-midi, sans fièvre. Depuis, quintes de toux intermittentes aux changements de position.\", \"d\": 3}, {\"id\": \"q170\", \"t\": \"qcm\", \"f\": \"f69\", \"ch\": \"e1\", \"q\": \"Laquelle est une indication du lavage d'oreille ?\", \"x\": \"Indications : bouchon de cérumen, bouchon épidermique, corps étranger accessible.\", \"o\": [\"Otorrhée de l'oreille moyenne\", \"Bouchon de cérumen\", \"Perforation tympanique\", \"Otite externe diffuse aiguë\"], \"c\": 1, \"d\": 2}, {\"id\": \"q171\", \"t\": \"qcm\", \"f\": \"f69\", \"ch\": \"e1\", \"q\": \"Quelle seringue est prévue pour le lavage d'oreille ?\", \"x\": \"Matériel : seringue stérile (50 ml), poire à lavage à défaut.\", \"o\": [\"Seringue de 5 ml\", \"Seringue à insuline\", \"Seringue stérile de 50 ml\", \"Seringue de 200 ml\"], \"c\": 2, \"d\": 3}, {\"id\": \"q172\", \"t\": \"qcm\", \"f\": \"f70\", \"ch\": \"e1\", \"q\": \"Comment vérifie-t-on la température de l'eau de lavage ?\", \"x\": \"Vérifier la température de l'eau en la versant sur le revers de la main.\", \"o\": [\"Avec un thermomètre rectal\", \"En demandant au patient de la goûter\", \"Ce n'est pas nécessaire\", \"En versant l'eau sur le revers de la main\"], \"c\": 3, \"d\": 2}, {\"id\": \"q173\", \"t\": \"qcm\", \"f\": \"f71\", \"ch\": \"e1\", \"q\": \"Des vertiges et nausées pendant le lavage sont dus à :\", \"x\": \"Incidents : vertiges et nausées → eau trop froide ou trop chaude ; douleur → arrêter ; traumatisme → introduction trop profonde.\", \"o\": [\"Une eau trop froide ou trop chaude\", \"Une pression trop faible\", \"Un bouchon trop mou\", \"Un patient assis\"], \"c\": 0, \"d\": 1}, {\"id\": \"q174\", \"t\": \"vf\", \"f\": \"f71\", \"ch\": \"e1\", \"q\": \"On ne doit jamais faire de lavage d'oreille dans une otorrhée de l'oreille moyenne.\", \"x\": \"Vrai : risque de surinfecter la caisse du tympan avec l'eau et les débris souillés du CAE.\", \"v\": true, \"d\": 1}, {\"id\": \"q175\", \"t\": \"vf\", \"f\": \"f70\", \"ch\": \"e1\", \"q\": \"La pression d'injection du lavage d'oreille doit être forte d'emblée.\", \"x\": \"Faux : selon le cours, « injecter doucement la solution pour ne pas surprendre le patient puis augmenter la pression qui doit rester modérée ».\", \"v\": false, \"d\": 1}, {\"id\": \"q176\", \"t\": \"open\", \"f\": \"f70\", \"ch\": \"e1\", \"q\": \"Quel examen permet de contrôler la vacuité du CAE après le lavage ?\", \"x\": \"Contrôler la vacuité du conduit auditif externe par une otoscopie.\", \"a\": \"otoscopie\", \"alt\": [\"une otoscopie\", \"l'otoscopie\"], \"k\": [], \"d\": 3}, {\"id\": \"q177\", \"t\": \"cas\", \"f\": \"f71\", \"ch\": \"e1\", \"q\": \"Que doit faire l'infirmier ?\", \"x\": \"Incidents et accidents : douleur → arrêter le lavage.\", \"o\": [\"Augmenter la pression pour finir vite\", \"Arrêter le lavage\", \"Introduire la seringue plus profondément\", \"Changer l'eau pour de l'eau glacée\"], \"c\": 1, \"s\": \"Pendant un lavage d'oreille pour bouchon de cérumen, le patient signale brusquement une douleur vive.\", \"d\": 3}, {\"id\": \"q178\", \"t\": \"qcm\", \"f\": \"f73\", \"ch\": \"e2\", \"q\": \"Pourquoi maintient-on la tête du nourrisson sur le côté pendant le lavage de nez ?\", \"x\": \"Tête impérativement sur le côté pour éviter les risques de « fausse route » (passage involontaire de sérum dans les voies respiratoires).\", \"o\": [\"Pour faciliter les pleurs\", \"Pour réchauffer le sérum\", \"Pour éviter une fausse route\", \"Pour éviter une otite externe\"], \"c\": 2, \"d\": 2}, {\"id\": \"q179\", \"t\": \"qcm\", \"f\": \"f73\", \"ch\": \"e2\", \"q\": \"Avant quel âge les vasoconstricteurs nasaux sont-ils proscrits selon le chapitre lavage de nez ?\", \"x\": \"L'emploi de sprays contenant des vasoconstricteurs est proscrit avant l'âge de 15 ans.\", \"o\": [\"6 mois\", \"2 ans\", \"5 ans\", \"15 ans\"], \"c\": 3, \"d\": 3}, {\"id\": \"q180\", \"t\": \"qcm\", \"f\": \"f74\", \"ch\": \"e2\", \"q\": \"Chez l'adulte, dans quelle narine introduit-on l'embout ?\", \"x\": \"Incliner la tête sur le côté et introduire l'embout dans la narine supérieure ; pulvériser toujours dans la narine supérieure.\", \"o\": [\"La narine supérieure\", \"La narine inférieure\", \"Les deux narines en même temps\", \"Peu importe\"], \"c\": 0, \"d\": 2}, {\"id\": \"q181\", \"t\": \"qcm\", \"f\": \"f72\", \"ch\": \"e2\", \"q\": \"Laquelle est une indication du lavage de nez ?\", \"x\": \"Indications : rhinite atrophique, encombrement nasal, après une intervention par voie endonasale.\", \"o\": [\"Épistaxis grave\", \"Rhinite atrophique avec rhinorrhées purulentes et croûtes\", \"Corps étranger trachéal\", \"Fracture du rocher\"], \"c\": 1, \"d\": 1}, {\"id\": \"q182\", \"t\": \"vf\", \"f\": \"f73\", \"ch\": \"e2\", \"q\": \"Le lavage de nez est préférable à l'utilisation d'un mouche-bébé.\", \"x\": \"Vrai : le mouche-bébé est reconnu comme moins efficace, il débouche moins bien.\", \"v\": true, \"d\": 1}, {\"id\": \"q183\", \"t\": \"vf\", \"f\": \"f74\", \"ch\": \"e2\", \"q\": \"Pour préparer l'eau salée, on utilise du sel fin de table.\", \"x\": \"Faux : selon le cours, « du gros sel (et non du sel fin de table qui contient des additifs indésirables) ».\", \"v\": false, \"d\": 1}, {\"id\": \"q184\", \"t\": \"open\", \"f\": \"f74\", \"ch\": \"e2\", \"q\": \"Combien de cuillères à café de gros sel pour 1 litre d'eau ?\", \"x\": \"Pour 1 litre d'eau, 2 cuillères à café de gros sel.\", \"a\": \"2\", \"alt\": [\"deux\", \"2 cuilleres\", \"2 cuilleres a cafe\"], \"k\": [], \"d\": 3}, {\"id\": \"q185\", \"t\": \"cas\", \"f\": \"f73\", \"ch\": \"e2\", \"q\": \"Quel conseil lui donner ?\", \"x\": \"Chez le nourrisson : dosettes de SP à usage unique ; eau du robinet ou minérale déconseillée (pas assez salée, germes) ; tête sur le côté.\", \"o\": [\"Utiliser l'eau du robinet froide\", \"Utiliser un spray vasoconstricteur\", \"Utiliser des dosettes de sérum physiologique à usage unique, tête de bébé sur le côté\", \"Aspirer uniquement avec la bouche\"], \"c\": 2, \"s\": \"Une mère veut nettoyer le nez de son bébé de 3 mois encombré et propose d'utiliser l'eau du robinet.\", \"d\": 3}, {\"id\": \"q186\", \"t\": \"qcm\", \"f\": \"f75\", \"ch\": \"e3\", \"q\": \"Le méchage antérieur consiste à combler les fosses nasales :\", \"x\": \"Combler en accordéon les fosses nasales à l'aide d'une mèche depuis les choanes jusqu'au vestibule, pour l'hémostase.\", \"o\": [\"En spirale, du vestibule au sinus maxillaire\", \"Avec un ballonnet gonflé\", \"Avec du coton sec en boule\", \"En accordéon, des choanes jusqu'au vestibule\"], \"c\": 3, \"d\": 2}, {\"id\": \"q187\", \"t\": \"qcm\", \"f\": \"f76\", \"ch\": \"e3\", \"q\": \"Quel instrument sert à écarter la narine pendant le méchage ?\", \"x\": \"Matériel : spéculum de Palmer, pince coudée de Lubet-Barbon, miroir de Clar…\", \"o\": [\"Le spéculum de Palmer\", \"L'otoscope\", \"Le miroir de Clar uniquement\", \"L'abaisse-langue\"], \"c\": 0, \"d\": 3}, {\"id\": \"q188\", \"t\": \"qcm\", \"f\": \"f76\", \"ch\": \"e3\", \"q\": \"Combien de temps attendre après la pulvérisation de xylocaïne ?\", \"x\": \"Faire une pulvérisation ou un premier méchage à la xylocaïne et attendre 5 à 10 min (rétracte les cornets, anesthésie les FN).\", \"o\": [\"30 secondes\", \"5 à 10 minutes\", \"1 heure\", \"24 heures\"], \"c\": 1, \"d\": 2}, {\"id\": \"q189\", \"t\": \"qcm\", \"f\": \"f77\", \"ch\": \"e3\", \"q\": \"Quel conseil de sortie donner après un méchage antérieur ?\", \"x\": \"Conseils : respirer par la bouche 48 h, manger et boire lentement par petites gorgées, prendre le traitement, revenir s'il saigne.\", \"o\": [\"Se moucher fort toutes les heures\", \"Retirer soi-même la mèche le lendemain\", \"Respirer par la bouche pendant 48 h\", \"Boire de grandes quantités d'un trait\"], \"c\": 2, \"d\": 1}, {\"id\": \"q190\", \"t\": \"vf\", \"f\": \"f75\", \"ch\": \"e3\", \"q\": \"La contention d'une réduction des os propres du nez est une indication du méchage antérieur.\", \"x\": \"Vrai : indications : épistaxis, contention d'une réduction des OPN, cavoscopie, après chirurgie.\", \"v\": true, \"d\": 1}, {\"id\": \"q191\", \"t\": \"vf\", \"f\": \"f77\", \"ch\": \"e3\", \"q\": \"Le méchage antérieur se fait sous anesthésie générale.\", \"x\": \"Faux : selon le cours, « il est fait sous anesthésie locale » et l'acte n'est pas douloureux.\", \"v\": false, \"d\": 1}, {\"id\": \"q192\", \"t\": \"open\", \"f\": \"f76\", \"ch\": \"e3\", \"q\": \"Au bout de combien d'heures se fait le déméchage ?\", \"x\": \"Le déméchage se fait au bout de 48 h.\", \"a\": \"48 h\", \"alt\": [\"48\", \"48 heures\", \"quarante huit heures\"], \"k\": [], \"d\": 3}, {\"id\": \"q193\", \"t\": \"cas\", \"f\": \"f76\", \"ch\": \"e3\", \"q\": \"Dans quelle position installer le patient ?\", \"x\": \"Technique : installer le patient en position assise ou demi-assise, le protéger d'un champ, placer le haricot sous son menton.\", \"o\": [\"Décubitus dorsal tête en arrière\", \"Décubitus ventral\", \"Position de Trendelenburg\", \"Assise ou demi-assise, protégée d'un champ, haricot sous le menton\"], \"c\": 3, \"s\": \"Vous préparez un méchage antérieur pour une épistaxis rebelle chez un patient anxieux.\", \"d\": 3}, {\"id\": \"q194\", \"t\": \"qcm\", \"f\": \"f78\", \"ch\": \"e4\", \"q\": \"La trachéotomie est :\", \"x\": \"Ouverture de la trachée cervicale afin d'introduire une canule qui court-circuite les voies aériennes supérieures lors d'un obstacle.\", \"o\": [\"L'ouverture de la trachée cervicale pour y introduire une canule\", \"L'ablation du larynx\", \"L'intubation par la bouche\", \"La ligature de la trachée\"], \"c\": 0, \"d\": 2}, {\"id\": \"q195\", \"t\": \"qcm\", \"f\": \"f78\", \"ch\": \"e4\", \"q\": \"Selon le cours, la canule de trachéotomie est changée si possible :\", \"x\": \"Soins de la canule à changer tous les 3 jours si possible.\", \"o\": [\"Toutes les heures\", \"Tous les 3 jours\", \"Une fois par mois\", \"Jamais\"], \"c\": 1, \"d\": 3}, {\"id\": \"q196\", \"t\": \"qcm\", \"f\": \"f78\", \"ch\": \"e4\", \"q\": \"Dans quoi conserve-t-on la sonde d'aspiration ?\", \"x\": \"La sonde d'aspiration est placée dans un bocal contenant une eau additionnée d'antiseptique, exemple Bétadine jaune.\", \"o\": [\"Un bocal sec\", \"Du sérum glucosé\", \"Un bocal d'eau additionnée d'antiseptique (ex. Bétadine jaune)\", \"De l'alcool pur\"], \"c\": 2, \"d\": 2}, {\"id\": \"q197\", \"t\": \"vf\", \"f\": \"f78\", \"ch\": \"e4\", \"q\": \"L'humidification de l'air inspiré fait partie des soins post-opératoires de la trachéotomie.\", \"x\": \"Vrai : aspiration des sécrétions, humidification, prévention de l'infection, soins de canule.\", \"v\": true, \"d\": 1}, {\"id\": \"q198\", \"t\": \"vf\", \"f\": \"f78\", \"ch\": \"e4\", \"q\": \"La trachéotomie sert à court-circuiter les voies aériennes inférieures.\", \"x\": \"Faux : selon le cours, elle sert « à court-circuiter les voies aériennes supérieures lors d'un obstacle ».\", \"v\": false, \"d\": 1}, {\"id\": \"q199\", \"t\": \"open\", \"f\": \"f78\", \"ch\": \"e4\", \"q\": \"Quel antiseptique est donné en exemple pour le bocal de la sonde d'aspiration ?\", \"x\": \"Exemple du cours : Bétadine jaune.\", \"a\": \"Bétadine jaune\", \"alt\": [\"betadine\", \"betadine jaune\", \"povidone iodee\"], \"k\": [\"betadine\"], \"d\": 3}, {\"id\": \"q200\", \"t\": \"cas\", \"f\": \"f78\", \"ch\": \"e4\", \"q\": \"Quels soins prioritaires réaliser ?\", \"x\": \"Soins post-opératoires : aspiration des sécrétions, humidification de l'air inspiré, prévention de l'infection.\", \"o\": [\"Retrait définitif de la canule\", \"Lavage de nez à la seringue\", \"Méchage antérieur\", \"Aspiration des sécrétions et humidification de l'air inspiré\"], \"c\": 3, \"s\": \"Patient trachéotomisé depuis 24 h : encombrement bronchique, sécrétions épaisses, air de la chambre très sec.\", \"d\": 3}], \"gl\": [{\"t\": \"Acouphène\", \"d\": \"Bruit perçu dans l'oreille ou la tête sans source extérieure, entendu seulement par le malade.\", \"p\": \"1:18\"}, {\"t\": \"Adénopathie\", \"d\": \"Augmentation de volume d'un ganglion lymphatique.\", \"p\": \"2:1,2:6\"}, {\"t\": \"Adénophlegmon\", \"d\": \"Suppuration d'un ganglion du cou, complication possible d'une rhinopharyngite.\", \"p\": \"2:2\"}, {\"t\": \"Adénoïdectomie\", \"d\": \"Ablation chirurgicale des végétations adénoïdes.\", \"p\": \"1:28,1:35\"}, {\"t\": \"Agueusie\", \"d\": \"Perte du goût.\", \"p\": \"2:5\"}, {\"t\": \"Aminosides\", \"d\": \"Famille d'antibiotiques dominant les surdités toxiques, surtout en cas d'insuffisance rénale.\", \"p\": \"1:17\"}, {\"t\": \"Amygdale de Luschka\", \"d\": \"Amygdale pharyngée du rhinopharynx ; son hypertrophie forme les végétations adénoïdes.\", \"p\": \"1:34\"}, {\"t\": \"Amygdales palatines\", \"d\": \"Formations lymphoïdes de la région amygdalienne de l'oropharynx.\", \"p\": \"1:10,2:6\"}, {\"t\": \"Angine\", \"d\": \"Inflammation aiguë de l'oropharynx et des amygdales palatines.\", \"p\": \"2:6\"}, {\"t\": \"Angine érythémato-pultacée\", \"d\": \"Angine avec amygdales hypertrophiées recouvertes d'un enduit blanchâtre.\", \"p\": \"2:6\"}, {\"t\": \"Angiofibrome juvénile\", \"d\": \"Tumeur bénigne très hémorragique du nasopharynx de l'adolescent masculin.\", \"p\": \"1:20\"}, {\"t\": \"Anosmie\", \"d\": \"Perte de l'odorat.\", \"p\": \"1:32\"}, {\"t\": \"Antre mastoïdien\", \"d\": \"Plus importante cellule aérienne de la mastoïde.\", \"p\": \"1:5\"}, {\"t\": \"Aryténoïdes\", \"d\": \"Cartilages articulés au cricoïde sur lesquels s'insèrent les cordes vocales.\", \"p\": \"1:11\"}, {\"t\": \"Atrésie du conduit\", \"d\": \"Absence congénitale ou étroitesse du CAE ; cause de surdité de transmission.\", \"p\": \"1:16\"}, {\"t\": \"Barotraumatisme\", \"d\": \"Lésion de l'oreille moyenne due à une variation brutale de pression.\", \"p\": \"1:15\"}, {\"t\": \"Bouchon de cérumen\", \"d\": \"Accumulation de cérumen durci obstruant le CAE.\", \"p\": \"1:16,1:24\"}, {\"t\": \"Bouchon épidermique\", \"d\": \"Amas de lamelles de desquamation de la peau du CAE.\", \"p\": \"1:16\"}, {\"t\": \"Bradypnée inspiratoire\", \"d\": \"Ralentissement de la respiration avec inspiration allongée, typique de la dyspnée laryngée.\", \"p\": \"1:22\"}, {\"t\": \"Bronchoscopie au tube rigide\", \"d\": \"Endoscopie trachéo-bronchique sous anesthésie générale pour extraire un CE.\", \"p\": \"2:10\"}, {\"t\": \"Cacosmie\", \"d\": \"Perception d'une mauvaise odeur ; subjective dans la sinusite maxillaire.\", \"p\": \"1:32\"}, {\"t\": \"CAE\", \"d\": \"Conduit auditif externe (méat acoustique externe).\", \"p\": \"1:3\"}, {\"t\": \"Caisse du tympan\", \"d\": \"Cavité de l'oreille moyenne contenant la chaîne des osselets.\", \"p\": \"1:4\"}, {\"t\": \"Canaux semi-circulaires\", \"d\": \"Partie du labyrinthe impliquée dans l'équilibre (crêtes ampullaires).\", \"p\": \"1:5\"}, {\"t\": \"Canule de trachéotomie\", \"d\": \"Tube placé dans la trachée ouverte ; changé tous les 3 jours si possible.\", \"p\": \"2:20\"}, {\"t\": \"Carrefour aérodigestif\", \"d\": \"Zone formée par l'hypopharynx et le larynx où se séparent air et aliments.\", \"p\": \"1:10\"}, {\"t\": \"Cartilage cricoïde\", \"d\": \"Cartilage formant la base du larynx.\", \"p\": \"1:11\"}, {\"t\": \"Cartilage thyroïde\", \"d\": \"Cartilage en livre ouvert formant la pomme d'Adam.\", \"p\": \"1:11\"}, {\"t\": \"Cavoscopie\", \"d\": \"Examen du cavum ; indication possible d'un méchage.\", \"p\": \"2:18\"}, {\"t\": \"Cavum\", \"d\": \"Autre nom du nasopharynx ou rhinopharynx.\", \"p\": \"1:9\"}, {\"t\": \"Choanes\", \"d\": \"Orifices postérieurs des fosses nasales vers le nasopharynx.\", \"p\": \"1:9,2:18\"}, {\"t\": \"Cholestéatome\", \"d\": \"Forme d'otite moyenne chronique (cholestéatomateuse) citée parmi les otalgies.\", \"p\": \"1:15\"}, {\"t\": \"Cloison nasale\", \"d\": \"Septum séparant les deux fosses nasales (os en arrière, cartilage en avant).\", \"p\": \"1:6,1:7\"}, {\"t\": \"Cochlée\", \"d\": \"Partie de l'oreille interne qui transforme le signal mécanique en signal électrique.\", \"p\": \"1:5\"}, {\"t\": \"Cophose\", \"d\": \"Disparition totale de l'ouïe.\", \"p\": \"1:16\"}, {\"t\": \"Cornage\", \"d\": \"Bruit inspiratoire rauque de la dyspnée laryngée.\", \"p\": \"1:22,1:23\"}, {\"t\": \"Cornets\", \"d\": \"Reliefs osseux de la paroi externe des fosses nasales.\", \"p\": \"1:7\"}, {\"t\": \"Corps étranger\", \"d\": \"Objet ou être vivant présent dans un endroit inhabituel.\", \"p\": \"2:8\"}, {\"t\": \"Corticothérapie\", \"d\": \"Traitement par corticoïdes (ex. cure de 5 jours dans la sinusite).\", \"p\": \"1:33,1:23\"}, {\"t\": \"Coryza\", \"d\": \"Rhume ; peut précéder une sinusite maxillaire.\", \"p\": \"1:32\"}, {\"t\": \"Crico-thyroïdien\", \"d\": \"Muscle tenseur des cordes vocales innervé par le nerf laryngé supérieur.\", \"p\": \"1:11,1:12\"}, {\"t\": \"Crêtes ampullaires\", \"d\": \"Unités fonctionnelles des canaux semi-circulaires.\", \"p\": \"1:5\"}, {\"t\": \"Cyanose\", \"d\": \"Coloration bleutée des extrémités ; stades 3 et 4 de la laryngite.\", \"p\": \"1:23\"}, {\"t\": \"Célestine\", \"d\": \"Corticoïde en solution (10 gouttes/kg/j) dans l'OMA du nourrisson.\", \"p\": \"1:28\"}, {\"t\": \"Cérumen\", \"d\": \"Sécrétion jaune-brune des glandes cérumineuses du 1/3 externe du CAE.\", \"p\": \"1:4\"}, {\"t\": \"Dysphagie\", \"d\": \"Difficulté à avaler.\", \"p\": \"2:9,2:10\"}, {\"t\": \"Dysphonie\", \"d\": \"Enrouement, trouble de la voix.\", \"p\": \"2:3\"}, {\"t\": \"Dyspnée laryngée\", \"d\": \"Bradypnée inspiratoire avec tirage, cornage et trouble de la voix.\", \"p\": \"1:22\"}, {\"t\": \"Déméchage\", \"d\": \"Retrait de la mèche, au bout de 48 h.\", \"p\": \"2:19\"}, {\"t\": \"Eczéma de l'oreille\", \"d\": \"Dermatose prurigineuse du conduit évoluant par poussées.\", \"p\": \"1:24,1:25\"}, {\"t\": \"Ethmoïdite\", \"d\": \"Infection des cellules ethmoïdales ; complication des végétations et rhinopharyngites.\", \"p\": \"1:35,2:2\"}, {\"t\": \"Fausse route\", \"d\": \"Passage involontaire de liquide ou d'aliment dans les voies respiratoires.\", \"p\": \"2:14,2:15\"}, {\"t\": \"Fosses nasales\", \"d\": \"Deux cavités séparées par la cloison, entre vestibule et choanes.\", \"p\": \"1:6\"}, {\"t\": \"Furoncle du conduit\", \"d\": \"Infection staphylococcique des follicules du 1/3 externe du CAE.\", \"p\": \"1:25\"}, {\"t\": \"Glande cérumineuse\", \"d\": \"Glande cutanée du 1/3 externe du CAE produisant le cérumen.\", \"p\": \"1:4\"}, {\"t\": \"Glomérulonéphrite post-streptococcique\", \"d\": \"Atteinte rénale aiguë après infection à streptocoque A.\", \"p\": \"2:5\"}, {\"t\": \"Glotte\", \"d\": \"Espace entre les cordes vocales ; ouverte pour respirer, fermée pour parler.\", \"p\": \"1:12\"}, {\"t\": \"Hypoacousie\", \"d\": \"Baisse de l'acuité auditive.\", \"p\": \"1:16\"}, {\"t\": \"Hypopharynx\", \"d\": \"Étage inférieur du pharynx, jusqu'à la bouche œsophagienne.\", \"p\": \"1:10\"}, {\"t\": \"Incidence de Blondeau\", \"d\": \"Radiographie montrant l'opacité du sinus maxillaire.\", \"p\": \"1:33\"}, {\"t\": \"Kisselbach (tache vasculaire)\", \"d\": \"Zone sur-vascularisée de la cloison antérieure, source de 90 % des épistaxis.\", \"p\": \"1:19\"}, {\"t\": \"Labyrinthe\", \"d\": \"Oreille interne (cochlée, vestibule, canaux semi-circulaires).\", \"p\": \"1:5\"}, {\"t\": \"Laryngite sous-glottique\", \"d\": \"Inflammation laryngée de l'enfant classée en 4 stades de gravité.\", \"p\": \"1:22,1:23\"}, {\"t\": \"Lavage d'oreille\", \"d\": \"Mise en état de vacuité du CAE dans un but thérapeutique.\", \"p\": \"2:11\"}, {\"t\": \"Lavage de nez\", \"d\": \"Passage d'un liquide légèrement salé dans les fosses nasales pour les nettoyer.\", \"p\": \"2:13\"}, {\"t\": \"Lubet-Barbon (pince de)\", \"d\": \"Pince coudée utilisée pour le méchage antérieur.\", \"p\": \"2:18\"}, {\"t\": \"Macule\", \"d\": \"Unité fonctionnelle du vestibule.\", \"p\": \"1:5\"}, {\"t\": \"Mastoïde\", \"d\": \"Ensemble de cellules aériennes de l'os temporal en communication avec la caisse.\", \"p\": \"1:4,1:5\"}, {\"t\": \"Mastoïdite\", \"d\": \"Infection de la mastoïde, complication de l'OMA.\", \"p\": \"1:28\"}, {\"t\": \"Miroir de Clar\", \"d\": \"Miroir frontal d'éclairage utilisé en ORL.\", \"p\": \"2:18\"}, {\"t\": \"Mouche-bébé\", \"d\": \"Appareil d'aspiration des mucosités, moins efficace que le lavage de nez.\", \"p\": \"2:2,2:15\"}, {\"t\": \"Mucopus\", \"d\": \"Mucus jaunâtre contenant polynucléaires et macrophages.\", \"p\": \"2:1\"}, {\"t\": \"Myringite\", \"d\": \"Inflammation du tympan, souvent virale.\", \"p\": \"1:15\"}, {\"t\": \"Méat moyen\", \"d\": \"Espace sous le cornet moyen où se drainent les sinus antérieurs.\", \"p\": \"1:8,1:32\"}, {\"t\": \"Méchage antérieur\", \"d\": \"Comblement en accordéon des fosses nasales par une mèche pour l'hémostase.\", \"p\": \"2:18\"}, {\"t\": \"Naphazoline\", \"d\": \"Vasoconstricteur associé à la lidocaïne/xylocaïne 5 % en pulvérisation nasale.\", \"p\": \"1:20,2:18\"}, {\"t\": \"NARES\", \"d\": \"Rhinite non allergique à éosinophiles (> 20 %), enquête allergique négative.\", \"p\": \"1:30\"}, {\"t\": \"Nasopharynx\", \"d\": \"Étage supérieur du pharynx (cavum, rhinopharynx).\", \"p\": \"1:9\"}, {\"t\": \"Nerf laryngé supérieur\", \"d\": \"Nerf innervant le crico-thyroïdien.\", \"p\": \"1:12\"}, {\"t\": \"Nerfs récurrents\", \"d\": \"Branches du pneumogastrique innervant les muscles du larynx.\", \"p\": \"1:11\"}, {\"t\": \"Nystatine\", \"d\": \"Antifongique (Mycostatine) à sucer dans la pharyngite mycosique.\", \"p\": \"2:5\"}, {\"t\": \"Nécrose septale\", \"d\": \"Mort du tissu de la cloison, risque d'un méchage laissé plus de 48 h.\", \"p\": \"1:20\"}, {\"t\": \"Odynodysphagie\", \"d\": \"Difficulté douloureuse à avaler salive, nourriture ou liquide.\", \"p\": \"2:4\"}, {\"t\": \"Odynophagie\", \"d\": \"Douleur à la déglutition.\", \"p\": \"2:3,2:6\"}, {\"t\": \"OMA\", \"d\": \"Otite moyenne aiguë : inflammation de la muqueuse de l'oreille moyenne < 3 semaines.\", \"p\": \"1:27\"}, {\"t\": \"OPN\", \"d\": \"Os propres du nez.\", \"p\": \"1:19,2:18\"}, {\"t\": \"Organe de Corti\", \"d\": \"Unité fonctionnelle de la cochlée (audition).\", \"p\": \"1:5\"}, {\"t\": \"Oropharyngoscopie\", \"d\": \"Examen de l'oropharynx à l'abaisse-langue.\", \"p\": \"1:14,2:2\"}, {\"t\": \"Oropharynx\", \"d\": \"Étage moyen du pharynx, en arrière de la cavité buccale.\", \"p\": \"1:9,1:10\"}, {\"t\": \"Osselets\", \"d\": \"Marteau, enclume, étrier de la caisse du tympan.\", \"p\": \"1:4\"}, {\"t\": \"Ostium\", \"d\": \"Orifice de drainage d'un sinus.\", \"p\": \"1:33\"}, {\"t\": \"Otalgie\", \"d\": \"Douleur de l'oreille.\", \"p\": \"1:14\"}, {\"t\": \"Otalgie réflexe\", \"d\": \"Otalgie fausse due à une lésion extra-auriculaire de voisinage.\", \"p\": \"1:14,1:15\"}, {\"t\": \"Othématome\", \"d\": \"Collection de sang entre le périchondre et le cartilage du pavillon.\", \"p\": \"1:24\"}, {\"t\": \"Otite externe diffuse\", \"d\": \"Infection du revêtement cutané de tout le CAE.\", \"p\": \"1:25,1:26\"}, {\"t\": \"Otite séromuqueuse\", \"d\": \"Épanchement non purulent de l'oreille moyenne ; complication des végétations.\", \"p\": \"1:28,1:34\"}, {\"t\": \"Otodynie\", \"d\": \"Otalgie vraie liée à une lésion de l'oreille.\", \"p\": \"1:14\"}, {\"t\": \"Otomycose\", \"d\": \"Otite externe fongique (dépôt blanchâtre + prurit).\", \"p\": \"1:26\"}, {\"t\": \"Otorrhée\", \"d\": \"Écoulement par l'oreille ; contre-indique le lavage si elle vient de l'oreille moyenne.\", \"p\": \"1:26,2:13\"}, {\"t\": \"Otoscopie\", \"d\": \"Examen du CAE et du tympan à l'otoscope.\", \"p\": \"1:14,1:27\"}, {\"t\": \"Pansinusite\", \"d\": \"Atteinte de tous les sinus d'un même côté.\", \"p\": \"1:32\"}, {\"t\": \"Papillomatose\", \"d\": \"Tumeur bénigne laryngée, cause de dyspnée chez l'enfant.\", \"p\": \"1:22\"}, {\"t\": \"Paracentèse\", \"d\": \"Incision du tympan pour évacuer le pus au stade suppuré collecté.\", \"p\": \"1:28\"}, {\"t\": \"Pavillon\", \"d\": \"Partie visible de l'oreille externe.\", \"p\": \"1:3\"}, {\"t\": \"Pharyngite\", \"d\": \"Inflammation de la gorge ou du pharynx.\", \"p\": \"2:3\"}, {\"t\": \"Phlegmon péri-amygdalien\", \"d\": \"Suppuration autour de l'amygdale, complication la plus courante de l'angine.\", \"p\": \"2:6\"}, {\"t\": \"Presbyacousie\", \"d\": \"Surdité de perception liée à l'âge (50-60 ans).\", \"p\": \"1:17\"}, {\"t\": \"Pyocyanique\", \"d\": \"Bactérie souvent retrouvée dans la périchondrite du pavillon.\", \"p\": \"1:26\"}, {\"t\": \"Périchondrite\", \"d\": \"Inflammation du pavillon, souvent à pyocyanique.\", \"p\": \"1:26\"}, {\"t\": \"RAA\", \"d\": \"Rhumatisme articulaire aigu, complication du streptocoque A.\", \"p\": \"2:5\"}, {\"t\": \"Rendu-Osler (maladie de)\", \"d\": \"Angiomatose hémorragique familiale, cause d'épistaxis.\", \"p\": \"1:19\"}, {\"t\": \"Rhinite\", \"d\": \"Inflammation des fosses nasales.\", \"p\": \"1:29\"}, {\"t\": \"Rhinopharyngite\", \"d\": \"Inflammation aiguë de la muqueuse des fosses nasales et du rhinopharynx.\", \"p\": \"2:1\"}, {\"t\": \"Rhinorrhée\", \"d\": \"Écoulement nasal (aqueux, séreux, muco-purulent).\", \"p\": \"1:29,2:1\"}, {\"t\": \"Rhinoscopie\", \"d\": \"Examen des fosses nasales (antérieure ou postérieure).\", \"p\": \"1:14,2:9\"}, {\"t\": \"Rhonchopathie\", \"d\": \"Ronflement ; invalidant avec apnée → adénoïdectomie.\", \"p\": \"1:35\"}, {\"t\": \"Réflexe stapédien\", \"d\": \"Réflexe protégeant l'oreille interne des sons intenses.\", \"p\": \"1:5\"}, {\"t\": \"Sinus\", \"d\": \"Cavités aériennes creusées dans le massif facial.\", \"p\": \"1:8\"}, {\"t\": \"Sinusite aiguë\", \"d\": \"Infection de la muqueuse des sinus < 3 semaines.\", \"p\": \"1:32\"}, {\"t\": \"Spéculum de Palmer\", \"d\": \"Instrument écartant la narine pour le méchage.\", \"p\": \"2:18,2:19\"}, {\"t\": \"Streptocoque β-hémolytique A\", \"d\": \"Germe principal des angines et pharyngites bactériennes.\", \"p\": \"2:4,2:6\"}, {\"t\": \"Stridor\", \"d\": \"Inspiration bruyante bénigne du nouveau-né, sans gêne ni cyanose.\", \"p\": \"1:22\"}, {\"t\": \"Surdité de perception\", \"d\": \"Surdité par atteinte de l'oreille interne, tympan normal.\", \"p\": \"1:17\"}, {\"t\": \"Surdité de transmission\", \"d\": \"Surdité par atteinte de l'oreille externe ou moyenne.\", \"p\": \"1:16\"}, {\"t\": \"Surdité mixte\", \"d\": \"Atteinte des appareils de transmission et de perception.\", \"p\": \"1:17\"}, {\"t\": \"Syndrome de pénétration\", \"d\": \"Accès brutal de suffocation et toux évoquant l'inhalation d'un CE.\", \"p\": \"2:9\"}, {\"t\": \"Sérum physiologique\", \"d\": \"Solution saline isotonique pour lavages et désinfection rhinopharyngée.\", \"p\": \"2:2,2:14\"}, {\"t\": \"Tamponnement postérieur\", \"d\": \"Tamponnement des choanes dans les épistaxis graves.\", \"p\": \"1:21\"}, {\"t\": \"Tirage\", \"d\": \"Dépression des parties molles (sus-sternal, xiphoïdien, intercostal) à l'inspiration.\", \"p\": \"1:22,1:23\"}, {\"t\": \"Trachéotomie\", \"d\": \"Ouverture de la trachée cervicale pour introduire une canule.\", \"p\": \"2:20,1:23\"}, {\"t\": \"Tragus\", \"d\": \"Saillie devant le CAE ; sa pression réveille la douleur du furoncle et de l'otite externe.\", \"p\": \"1:25,1:26\"}, {\"t\": \"TROD\", \"d\": \"Test rapide d'orientation diagnostique pour déterminer le germe d'une pharyngite.\", \"p\": \"2:3\"}, {\"t\": \"Trompe d'Eustache\", \"d\": \"Conduit ostéo-cartilagineux entre caisse du tympan et pharynx.\", \"p\": \"1:4\"}, {\"t\": \"Tympan\", \"d\": \"Membrane séparant le CAE de l'oreille moyenne.\", \"p\": \"1:3,1:27\"}, {\"t\": \"Vestibule (oreille)\", \"d\": \"Partie du labyrinthe impliquée dans l'équilibre (macule).\", \"p\": \"1:5\"}, {\"t\": \"Vestibule nasal\", \"d\": \"Partie antérieure de la fosse nasale garnie de poils.\", \"p\": \"1:7\"}, {\"t\": \"Végétations adénoïdes\", \"d\": \"Hypertrophie de l'amygdale pharyngée de Luschka.\", \"p\": \"1:34\"}, {\"t\": \"Xylocaïne\", \"d\": \"Anesthésique local (lidocaïne) utilisé avant méchage.\", \"p\": \"2:18,2:19\"}, {\"t\": \"Épiglotte\", \"d\": \"Cartilage qui ferme le larynx lors de la déglutition.\", \"p\": \"1:11,1:12\"}, {\"t\": \"Épistaxis\", \"d\": \"Saignement d'origine endonasale.\", \"p\": \"1:19\"}], \"tb\": [{\"t\": \"Otalgie vraie vs otalgie réflexe\", \"h\": [\"\", \"Otalgie vraie (otodynie)\", \"Otalgie réflexe\"], \"r\": [[\"Origine\", \"Lésion de l'oreille\", \"Lésion extra-auriculaire de voisinage\"], [\"Otoscopie\", \"Anormale (bouchon, otite, furoncle…)\", \"Souvent normale\"], [\"Exemples\", \"Furoncle, OMA, bouchon, CE, zona\", \"Carie dentaire, angine, sinusite, RGO, ATM\"], [\"Traitement\", \"Celui de la cause\", \"Celui de la cause\"]], \"p\": \"1:14,1:15\"}, {\"t\": \"Surdités : transmission, perception, mixte\", \"h\": [\"\", \"Transmission\", \"Perception\", \"Mixte\"], \"r\": [[\"Siège\", \"Oreille externe ou moyenne\", \"Oreille interne\", \"Les deux appareils\"], [\"Tympan\", \"Souvent anormal\", \"Normal\", \"Variable\"], [\"Causes\", \"Bouchon, CE, otites, tumeurs, atrésie\", \"Aminosides, presbyacousie, traumatisme sonore, congénitale\", \"Association\"]], \"p\": \"1:16,1:17\"}, {\"t\": \"Furoncle du conduit vs otite externe diffuse\", \"h\": [\"\", \"Furoncle\", \"Otite externe diffuse\"], \"r\": [[\"Étendue\", \"1/3 externe, localisé\", \"Totalité du CAE\"], [\"Germe / cause\", \"Staphylocoque, grattage\", \"Piscine, traumatisme, eczéma\"], [\"Signe majeur\", \"Douleur précoce intense (tragus, mastication)\", \"Otalgie au tragus et à la traction + otorrhée fétide\"], [\"Traitement\", \"Antalgique, AINS, ATB générale\", \"Nettoyage SP, gouttes ATB-corticoïde, méchage\"]], \"p\": \"1:25,1:26\"}, {\"t\": \"Les 3 aspects otoscopiques de l'OMA\", \"h\": [\"Forme\", \"Tympan\", \"Conduite\"], \"r\": [[\"Congestive\", \"Rouge, épaissi, manche du marteau hypervascularisé\", \"Traitement médical\"], [\"Suppurée collectée\", \"Opaque, terne, bombé\", \"Paracentèse\"], [\"Suppurée perforée\", \"Pus parfois pulsatile, perforation postérieure\", \"Traitement médical, nettoyage\"]], \"p\": \"1:27,1:28\"}, {\"t\": \"Épistaxis bénigne vs grave\", \"h\": [\"\", \"Bénigne\", \"Grave\"], \"r\": [[\"Abondance\", \"Minime ou moyenne\", \"Abondante ou répétée\"], [\"Hémodynamique\", \"Pas de retentissement\", \"Perturbée (choc possible)\"], [\"CAT\", \"Mouchage, spray, compression 10 min, méchage si échec\", \"Hospitalisation, TA, VVP, groupage, tamponnement ant./post.\"], [\"Médicaments\", \"ATB (suppuration)\", \"ATB + hémostatique parentéral\"]], \"p\": \"1:19,1:20,1:21\"}, {\"t\": \"Rhinite allergique : classification\", \"h\": [\"\", \"Modérée (aucun critère)\", \"Sévère (≥ 1 critère)\"], \"r\": [[\"Intermittente (< 4 j/sem ou < 4 sem/an)\", \"Intermittente modérée\", \"Intermittente sévère\"], [\"Persistante (> 4 j/sem et > 4 sem/an)\", \"Persistante modérée\", \"Persistante sévère\"], [\"Critères\", \"Sommeil, activités, travail/école, symptômes invalidants\", \"—\"]], \"p\": \"1:29,1:30\"}, {\"t\": \"Sinus antérieurs vs postérieurs\", \"h\": [\"\", \"Antérieurs\", \"Postérieurs\"], \"r\": [[\"Sinus\", \"Maxillaire, frontal, ethmoïde antérieur\", \"Ethmoïde postérieur, sphénoïdal\"], [\"Point commun\", \"Entourent l'orbite, drainent dans le méat moyen\", \"—\"], [\"Rôles (tous)\", \"Conditionnement de l'air, ventilation, drainage\", \"Idem\"]], \"p\": \"1:8\"}, {\"t\": \"Rhinopharyngite, pharyngite aiguë, angine\", \"h\": [\"\", \"Rhinopharyngite\", \"Pharyngite aiguë\", \"Angine\"], \"r\": [[\"Siège\", \"FN + rhinopharynx\", \"Pharynx\", \"Oropharynx + amygdales palatines\"], [\"Fièvre\", \"Brutale 39-40 °C\", \"Modérée 38 °C\", \"Élevée + frissons\"], [\"Germe\", \"Viral\", \"Surtout viral\", \"Strepto β-hémolytique A ++\"], [\"Antibiotique\", \"Inutile si non compliquée\", \"Si bactérienne\", \"Pénicilline 3-4 MUI/j × 8 j\"]], \"p\": \"2:1,2:2,2:3,2:6,2:7\"}, {\"t\": \"Pharyngite aiguë vs chronique\", \"h\": [\"\", \"Aiguë\", \"Chronique\"], \"r\": [[\"Durée\", \"Quelques jours à 1 semaine\", \"> 3 semaines\"], [\"Fièvre\", \"Modérée 38 °C\", \"Seulement si surinfection\"], [\"Terrain\", \"Tout âge, surtout viral\", \"Adulte : tabac, alcool, RGO, voix\"], [\"Signes\", \"Odynophagie, dysphonie, céphalées\", \"Sécheresse, raclage, odynodysphagie\"]], \"p\": \"2:3,2:4\"}, {\"t\": \"Stades de la laryngite aiguë sous-glottique\", \"h\": [\"\", \"Stade 1\", \"Stade 2\", \"Stade 3\", \"Stade 4\"], \"r\": [[\"État\", \"Calme\", \"Agité\", \"Angoissé\", \"Inconscient\"], [\"Tirage\", \"Modéré, sus-sternal\", \"Net, + xiphoïdien\", \"Intense, + intercostal\", \"Absent\"], [\"Cornage\", \"Modéré\", \"Net\", \"Intense\", \"Absent\"], [\"TA / pouls\", \"Normaux\", \"Normale / accéléré\", \"Élevée / accéléré\", \"Effondrée / filant\"], [\"Extrémités / rythme\", \"Normales / bradypnée insp.\", \"Normales / bradypnée insp.\", \"Cyanose / bradypnée\", \"Cyanose / irrégulier\"], [\"CAT\", \"Assis, O2, cortico IVD\", \"Idem ± adrénaline aérosol\", \"Intubation\", \"Intubation / trachéotomie\"]], \"p\": \"1:23\"}, {\"t\": \"Corps étrangers selon le siège\", \"h\": [\"Siège\", \"Motif / signes\", \"Conduite\"], \"r\": [[\"Fosses nasales\", \"Rhinorrhée muco-purulente unilatérale fétide\", \"Mouchage forcé, crochet/pince ; invisible : évacuer\"], [\"Pharynx\", \"Douleur arrière-gorge, dysphagie au repas\", \"Pince si visible ; sinon évacuer\"], [\"Larynx\", \"Asphyxie ou dyspnée laryngée, voix éteinte\", \"Urgence, extraction\"], [\"Trachée\", \"Toux et dyspnée intermittentes, posturales\", \"Bronchoscopie rigide sous AG\"], [\"Œsophage\", \"Dysphagie brutale, douleur rétrosternale\", \"Radio si opaque ; extraction en 2-3 j\"], [\"Oreille externe\", \"Fréquent chez l'enfant\", \"Lavage ou crochet, pince à éviter\"]], \"p\": \"2:8,2:9,2:10,1:24\"}, {\"t\": \"Lavage d'oreille vs lavage de nez vs méchage\", \"h\": [\"\", \"Lavage d'oreille\", \"Lavage de nez\", \"Méchage antérieur\"], \"r\": [[\"But\", \"Vider le CAE\", \"Nettoyer les FN\", \"Hémostase\"], [\"Indications\", \"Bouchon cérumen/épidermique, CE accessible\", \"Rhinite atrophique, encombrement, post-chirurgie\", \"Épistaxis, OPN, cavoscopie, post-chirurgie\"], [\"Matériel clé\", \"Seringue 50 ml, haricot\", \"Seringue 60 cc, SP, dosettes\", \"Spéculum de Palmer, pince de Lubet-Barbon, mèche 2-3 cm\"], [\"Piège\", \"Jamais sur otorrhée ; eau tiède\", \"Tête sur le côté (fausse route)\", \"Retrait à 48 h (nécrose)\"]], \"p\": \"2:11,2:13,2:18\"}], \"rs\": [{\"ch\": \"a1\", \"t\": \"Oreille\", \"h\": [\"Partie\", \"Composants\", \"Rôle\"], \"r\": [[\"Oreille externe\", \"Pavillon ; CAE (1/3 externe fibro-cartilagineux à glandes cérumineuses, 2/3 internes osseux)\", \"Capter, localiser, amplifier et diriger le son vers le tympan ; cérumen protecteur\"], [\"Oreille moyenne\", \"Caisse du tympan (marteau, enclume, étrier), mastoïde (antre), trompe d'Eustache\", \"Transmission, adaptation d'impédance, protection (réflexe stapédien) ; trompe : aération et équilibre de pression\"], [\"Oreille interne\", \"Cochlée (organe de Corti), vestibule (macule), canaux semi-circulaires (crêtes ampullaires)\", \"Audition (signal mécanique → électrique) et équilibre\"], [\"Appareils\", \"Externe + moyenne = transmission\", \"Interne = perception\"]], \"p\": \"1:3,1:4,1:5\"}, {\"ch\": \"a2\", \"t\": \"Nez\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Pyramide nasale\", \"Pyramide triangulaire ostéo-cartilagineuse, muqueuse dedans, muscles et peau dehors\"], [\"Fosses nasales\", \"2 fosses séparées par la cloison ; vestibule en avant ; parois : externe (cornets, méats), supérieure (toit), inférieure (plancher), interne (cloison)\"], [\"Muqueuses\", \"Respiratoire (presque toute la FN) ; olfactive (partie supérieure)\"], [\"Cloison\", \"Os en arrière, cartilage septal en avant\"], [\"Fonctions\", \"Olfactive, respiratoire (seule voie physiologique : réchauffe, humidifie, purifie), protection (muco-ciliaire), phonatoire (timbre)\"]], \"p\": \"1:6,1:7\"}, {\"ch\": \"a3\", \"t\": \"Sinus\", \"h\": [\"\", \"Sinus antérieurs\", \"Sinus postérieurs\"], \"r\": [[\"Composition\", \"Maxillaire, frontal, ethmoïde antérieur\", \"Ethmoïde postérieur, sphénoïdal\"], [\"Particularités\", \"Entourent l'orbite, drainent dans le méat moyen\", \"—\"], [\"Rôles\", \"Conditionnement de l'air, ventilation, drainage des sécrétions\", \"Idem\"]], \"p\": \"1:8\"}, {\"ch\": \"a4\", \"t\": \"Pharynx\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Définition\", \"Conduit musculo-membraneux, base du crâne → bord inférieur de C6, continué par l'œsophage\"], [\"Mesures\", \"13 cm de long ; 5 cm de large (nasal), 4 cm (oral), 4 cm (laryngé)\"], [\"Nasopharynx\", \"Cavum/rhinopharynx, derrière les FN, communique par les choanes\"], [\"Oropharynx\", \"Amygdales palatines et piliers, voile du palais, base de langue, vallécules, parois\"], [\"Hypopharynx\", \"Avec le larynx = carrefour aérodigestif ; jusqu'à la bouche œsophagienne\"], [\"Fonctions\", \"Ventilation, déglutition, phonation, immunité, digestion, goût, audition\"]], \"p\": \"1:9,1:10\"}, {\"ch\": \"a5\", \"t\": \"Larynx et trachée\", \"h\": [\"\", \"Larynx\", \"Trachée\"], \"r\": [[\"Définition\", \"Organe entre pharynx et trachée\", \"Conduit fibro-cartilagineux d'anneaux, aplati en arrière\"], [\"Structure\", \"Cartilages thyroïde, épiglottique, aryténoïdes, cricoïde\", \"Trachée cervicale 5-6 cm (adulte), 4 cm (enfant)\"], [\"Chiffres / innervation\", \"Nerfs récurrents (pneumogastrique) sauf crico-thyroïdien (laryngé supérieur)\", \"Calibre 6 / 8 / 10 / 12 mm selon l'âge\"], [\"Fonctions\", \"Déglutition, respiration (glotte ouverte), phonation (glotte fermée)\", \"Ciliaire, sécrétoire, tonique\"]], \"p\": \"1:11,1:12,1:13\"}, {\"ch\": \"b1\", \"t\": \"Otalgies\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Définition\", \"Douleur de l'oreille : vraie (otodynie) ou réflexe (fausse)\"], [\"Causes vraies\", \"Bouchon, CE, otite externe, furoncle, eczéma, périchondrite, othématome, zona, traumatisme, tumeur, myringite, OMA, OMC, cancer\"], [\"Causes réflexes\", \"Dents (homolatérale), glossite, angine, phlegmon, styloïde longue, cancers, ATM, sinusite, œsophage/RGO, thyroïdite, rachis cervical\"], [\"Examen\", \"Otoscopie puis examen ORL complet (oropharynx, rhinoscopie, bouche, ATM, sinus, nerfs, œsophage)\"], [\"Traitement\", \"Celui de la cause\"]], \"p\": \"1:14,1:15\"}, {\"ch\": \"b2\", \"t\": \"Surdités\", \"h\": [\"\", \"Transmission\", \"Perception\", \"Mixte\"], \"r\": [[\"Siège\", \"Oreille externe / moyenne\", \"Oreille interne (tympan normal)\", \"Les deux\"], [\"Causes\", \"Bouchon cérumen/épidermique, CE, otites, ostéomes, tumeurs, atrésie ; OMA, OMC, traumatismes\", \"Aminosides (+ insuffisance rénale), presbyacousie 50-60 ans, traumatismes sonores, congénitales\", \"Association\"], [\"Définition\", \"Trouble de l'audition : de l'hypoacousie à la cophose\", \"—\", \"—\"], [\"Alerte nourrisson (0-3 mois)\", \"Pas de sursaut aux bruits forts, sommeil imperturbable, cri modifié\", \"\", \"\"]], \"p\": \"1:16,1:17\"}, {\"ch\": \"b3\", \"t\": \"Acouphènes\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Définition\", \"Bruits perçus sans source extérieure, entendus seulement par le malade\"], [\"Clinique\", \"Permanents, intermittents ou temporaires ; tintement, chuintement, bourdonnement, sifflement ; uni/bilatéraux\"], [\"Causes\", \"Surdité brusque, traumatisme auditif ou crânien, HTA, anémie sévère, insuffisance rénale, stress/dépression\"], [\"Traitement d'urgence\", \"Vasodilatateurs, corticoïdes, oxygénothérapie, musique, traitement étiologique\"]], \"p\": \"1:18\"}, {\"ch\": \"b4\", \"t\": \"Pathologies de l'oreille externe\", \"h\": [\"Pathologie\", \"Cause / définition\", \"Signes\", \"Traitement\"], \"r\": [[\"Othématome\", \"Sang entre périchondre et cartilage du pavillon\", \"Tuméfaction du pavillon\", \"Spécialiste\"], [\"Corps étranger\", \"Fréquent chez l'enfant\", \"Gêne, hypoacousie\", \"Lavage ou crochet (pince à éviter)\"], [\"Bouchon de cérumen\", \"Cérumen durci (coton-tige)\", \"Hypoacousie, bourdonnement, vertiges, oreille bouchée\", \"Antiseptique moussant puis lavage\"], [\"Eczéma\", \"Dermatose par poussées\", \"Prurit intense\", \"Nettoyage, gouttes ATB-corticoïde, ATB si surinfection\"], [\"Furoncle du CAE\", \"Staphylocoque, 1/3 externe, grattage\", \"Douleur intense (tragus, mastication)\", \"Antalgique, AINS, ATB générale\"], [\"Otite externe diffuse\", \"Piscine, traumatisme, eczéma ; tout le CAE\", \"Otalgie (tragus, traction), otorrhée fétide, tympan normal\", \"Nettoyage SP, gouttes ATB-corticoïde, méchage ; Otofa si perforation\"], [\"Périchondrite\", \"Infection/traumatisme du pavillon\", \"Pavillon rouge, fistule, pyocyanique\", \"Antibiotique\"], [\"Otomycose\", \"Champignons\", \"Dépôt blanchâtre + prurit\", \"Antimycosique local 2-3 semaines\"]], \"p\": \"1:24,1:25,1:26\"}, {\"ch\": \"b5\", \"t\": \"OMA du nourrisson\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Définition\", \"Inflammation de la muqueuse de l'oreille moyenne < 3 semaines, après rhinopharyngite\"], [\"Germes\", \"H. influenzae, pneumocoque, Moraxella ; le plus souvent virale\"], [\"Signes\", \"Fièvre, diarrhée, vomissements, pleurs, rhinite, porte la main à l'oreille ; bilatérale > 1 fois sur 2\"], [\"Otoscopie\", \"Congestive (rouge) → suppurée collectée (bombée) → suppurée perforée (pus)\"], [\"CAT\", \"Vasoconstricteur < 5 j, SP, amox-clav 80-100 mg/kg/j, Célestine 10 gttes/kg/j, paracentèse si collectée\"], [\"Complications\", \"Récidives (adénoïdectomie), mastoïdite, paralysie faciale, méningite\"], [\"Prévention\", \"Hygiène nasale, traiter les allergies, vaccins pneumocoque et Haemophilus\"]], \"p\": \"1:27,1:28\"}, {\"ch\": \"c1\", \"t\": \"Épistaxis\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Définition\", \"Saignement endonasal antérieur, postérieur ou mixte ; urgence fréquente\"], [\"Origine\", \"90 % : tache vasculaire de Kisselbach, cloison à 1 cm de la narine\"], [\"Causes\", \"HTA, traumatismes, maladies hémorragiques (Rendu-Osler, hémophilie, anticoagulants), tumeurs (angiofibrome juvénile), infections, CE, grossesse\"], [\"CAT bénigne\", \"Mouchage, lidocaïne-naphazoline, compression 10 min tête en avant, méchage si échec (≤ 48 h), ATB\"], [\"CAT grave\", \"Hospitalisation, TA, voie veineuse, groupage, tamponnement antérieur/postérieur, ATB + hémostatique IV\"]], \"p\": \"1:19,1:20,1:21\"}, {\"ch\": \"c2\", \"t\": \"Rhinites\", \"h\": [\"Type\", \"Caractéristiques\", \"Traitement / notes\"], \"r\": [[\"Allergique\", \"Obstruction, éternuements en salve, rhinorrhée aqueuse ; intermittente/persistante (seuil 4 j/4 sem) ; modérée/sévère\", \"Antihistaminique, éviction de l'allergène\"], [\"Infectieuse\", \"Virale, bactérienne, mycosique, parasitaire ; aiguë < 12 sem, chronique au-delà\", \"Mouchage, lavage\"], [\"Médicamenteuse\", \"Aspirine, réserpine, guanéthidine, IEC, vasoconstricteurs prolongés\", \"Arrêt du produit\"], [\"Endocrinienne\", \"Hyperthyroïdie, acromégalie, 3e trimestre de grossesse\", \"—\"], [\"NARES\", \"Éosinophiles > 20 %, enquête allergique négative\", \"—\"], [\"Traitement général\", \"Mouchage, vasoconstricteur court, lavage, antihistaminique, éviction\", \"Lutter contre les symptômes invalidants\"]], \"p\": \"1:29,1:30,1:31\"}, {\"ch\": \"c3\", \"t\": \"Sinusite maxillaire aiguë\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Définition\", \"Infection de la muqueuse sinusienne < 3 semaines (après rhinite, grippe, piscine)\"], [\"Germes\", \"H. influenzae, pneumocoque, staphylocoque doré, anaérobies\"], [\"Clinique\", \"Douleur sous-orbitaire unilatérale pulsatile (penché en avant, toux), céphalée, obstruction, rhinorrhée purulente, cacosmie, anosmie\"], [\"Examens\", \"Pus au méat moyen, cornets tuméfiés ; Blondeau : opacité du sinus\"], [\"Traitement\", \"Lavage, antalgique, ATB 10 j (amox-clav, C3G, pristinamycine), cortico 5 j 0,5-1 mg/kg/j, aérosols, antihistaminique après ATB\"], [\"But\", \"Éviter le passage à la chronicité\"]], \"p\": \"1:32,1:33\"}, {\"ch\": \"c4\", \"t\": \"Végétations adénoïdes\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Définition\", \"Hypertrophie de l'amygdale pharyngée de Luschka (infections répétées)\"], [\"Signes\", \"Obstruction nasale bilatérale, respiration buccale, ronflement, troubles du sommeil ; rhinorrhée purulente = surinfection\"], [\"Examens\", \"Test bouche fermée ; mucopus pharyngé ; radio de profil du cavum (inspiration, bouche fermée)\"], [\"Complications\", \"OMA récidivantes, otites séromuqueuses, laryngites, trachéites, bronchopneumopathies, sinusites, ethmoïdite, adénites, détresse respiratoire\"], [\"Traitement\", \"Adénoïdectomie si rhonchopathie invalidante avec apnée du sommeil\"]], \"p\": \"1:34,1:35\"}, {\"ch\": \"d1\", \"t\": \"Rhinopharyngite\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Définition\", \"Inflammation aiguë des FN et du rhinopharynx, surtout virale, très fréquente chez l'enfant\"], [\"Signes\", \"Fièvre brutale 39-40 °C, obstruction bilatérale, rhinorrhée séreuse → mucopurulente, signes oculaires, toux rauque, adénopathies\"], [\"Examen\", \"Rhinoscopie (mucopus), oropharyngoscopie (rouge), otoscopie (congestion)\"], [\"Traitement\", \"SP pluriquotidien, mouche-bébé, mouchage ; pas d'ATB si non compliquée ; guérison en 5 jours\"], [\"Complications\", \"OMA (la plus fréquente), laryngite, trachéobronchite, phlegmons, sinusite, ethmoïdite → ATB 8 j\"]], \"p\": \"2:1,2:2\"}, {\"ch\": \"d2\", \"t\": \"Pharyngites\", \"h\": [\"\", \"Aiguë\", \"Chronique\", \"Mycosique\"], \"r\": [[\"Durée / cause\", \"Quelques jours à 1 semaine, surtout virale\", \"> 3 semaines ; tabac, alcool, RGO, voix\", \"Champignons\"], [\"Signes\", \"Odynophagie, dysphonie, fièvre 38 °C, céphalées, ganglions\", \"Sécheresse, raclage, odynodysphagie, sans fièvre\", \"Brûlures, coton, agueusie, plaques blanc crème\"], [\"Diagnostic\", \"Oropharyngoscopie, TROD\", \"Interrogatoire, palpation, prélèvement\", \"Examen\"], [\"Traitement\", \"Lavage nez, boissons chaudes, paracétamol, ATB si bactérienne\", \"Supprimer les irritants\", \"Nystatine, amphotéricine, miconazole\"], [\"Complications (strepto A, 30 %)\", \"Abcès, otites, sinusites, pneumonies, GNA, RAA\", \"\", \"\"]], \"p\": \"2:3,2:4,2:5\"}, {\"ch\": \"d3\", \"t\": \"Angine\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Définition\", \"Inflammation de l'oropharynx et des amygdales palatines ; adolescents, adultes jeunes\"], [\"Germes\", \"Streptocoque β-hémolytique A, staphylocoque, pneumocoque, H. influenzae\"], [\"Signes\", \"Frissons, fièvre élevée, odynophagie avec otalgie réflexe, arthralgies ; amygdales à enduit blanchâtre (érythémato-pultacée)\"], [\"Biologie\", \"Hyperleucocytose à PNN ; prélèvement de gorge non indispensable\"], [\"Traitement\", \"Pénicilline 3-4 MUI/j × 8 j, aspirine, antiseptiques locaux, repos\"], [\"Complication\", \"Phlegmon péri-amygdalien (la plus courante)\"]], \"p\": \"2:6,2:7\"}, {\"ch\": \"d4\", \"t\": \"Dyspnée laryngée\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Définition\", \"Bradypnée inspiratoire + tirage sus-sternal + cornage + trouble de la voix ; urgence chez l'enfant\"], [\"Causes nourrisson\", \"Malformation, spasmes, CE, stridor\"], [\"Causes enfant\", \"Laryngite sous-glottique, CE, papillomatose, traumatisme\"], [\"Causes adulte\", \"CE, traumatisme, laryngites, lésions nerveuses, tumeurs\"], [\"Stades\", \"1 calme → 2 agité → 3 angoissé, cyanose → 4 inconscient, signes absents, TA effondrée\"], [\"CAT\", \"Stades I-II : assis tête en hyperextension, O2, corticoïde IVD, adrénaline aérosol ; III-IV : intubation ou trachéotomie\"]], \"p\": \"1:22,1:23\"}, {\"ch\": \"d5\", \"t\": \"Corps étrangers\", \"h\": [\"Siège\", \"Exemples\", \"Signes\", \"Conduite\"], \"r\": [[\"Fosses nasales\", \"Perle, graine, papier, mèche\", \"Rhinorrhée purulente unilatérale fétide\", \"Mouchage forcé, crochet/pince ; invisible : évacuer\"], [\"Pharynx\", \"Arête, os, épingle\", \"Douleur, dysphagie au repas\", \"Pince si visible, sinon évacuer\"], [\"Larynx\", \"Objet volumineux ou creux\", \"Asphyxie ou dyspnée, voix éteinte\", \"Urgence\"], [\"Trachée\", \"CE mobile\", \"Toux, spasmes, dyspnée positionnelle\", \"Bronchoscopie rigide sous AG\"], [\"Œsophage\", \"Pièce, prothèse dentaire, bol\", \"Dysphagie brutale, douleur rétrosternale\", \"Radio ; extraction en 2-3 j\"]], \"p\": \"2:8,2:9,2:10\"}, {\"ch\": \"e1\", \"t\": \"Lavage d'oreille\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Définition\", \"Mise en état de vacuité du CAE dans un but thérapeutique\"], [\"Indications\", \"Bouchon de cérumen, bouchon épidermique, CE accessible\"], [\"Matériel\", \"Seringue 50 ml, cupule, compresses, coton, alèze, gants, tablier, réniforme\"], [\"Technique\", \"Eau testée sur le revers de la main, injection douce puis modérée, otoscopie de contrôle\"], [\"Incidents\", \"Vertiges (eau trop froide/chaude), douleur → arrêter, traumatisme (seringue trop profonde)\"], [\"Contre-indication\", \"Jamais sur une otorrhée de l'oreille moyenne\"]], \"p\": \"2:11,2:12,2:13\"}, {\"ch\": \"e2\", \"t\": \"Lavage de nez\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Principe\", \"Liquide légèrement salé dans les FN pour les nettoyer\"], [\"Indications\", \"Rhinite atrophique, encombrement, après chirurgie endonasale\"], [\"Nourrisson\", \"Dosettes SP, tête sur le côté, narine du haut, bouche fermée ; pas de vasoconstricteur avant 15 ans\"], [\"Enfant / adulte\", \"Narine supérieure, se moucher fort ; adulte vertical, pression franche\"], [\"Préparation\", \"1 L d'eau + 2 c. à café de gros sel (± bicarbonate)\"], [\"Fréquence\", \"Cures d'1 semaine par mois, saisonnière ou en alerte\"]], \"p\": \"2:13,2:14,2:15,2:16,2:17\"}, {\"ch\": \"e3\", \"t\": \"Méchage antérieur\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Définition\", \"Mèche en accordéon des choanes au vestibule pour l'hémostase\"], [\"Indications\", \"Épistaxis, réduction des OPN, cavoscopie, post-chirurgie\"], [\"Matériel\", \"Spéculum de Palmer, pince de Lubet-Barbon, mèche 2-3 cm, xylocaïne 5 % naphazoline\"], [\"Technique\", \"Assis, moucher, xylocaïne 5-10 min, mèche au fond en accordéon, fixation, ATB + antalgique\"], [\"Retrait\", \"Déméchage à 48 h\"], [\"Conseils\", \"Respirer par la bouche, boire lentement, prendre le traitement, revenir si saignement\"]], \"p\": \"2:18,2:19\"}, {\"ch\": \"e4\", \"t\": \"Trachéotomie\", \"h\": [\"Rubrique\", \"À retenir\"], \"r\": [[\"Définition\", \"Ouverture de la trachée cervicale avec canule, court-circuite les VAS\"], [\"Soins\", \"Aspiration, humidification, prévention infection plaie et broncho-pulmonaire\"], [\"Canule\", \"Changée tous les 3 jours si possible\"], [\"Sonde d'aspiration\", \"Bocal d'eau + antiseptique (Bétadine jaune)\"], [\"Non développé\", \"Indications et complications annoncées dans les objectifs\"]], \"p\": \"2:20\"}], \"imgs\": [{\"k\": \"oreille\", \"ch\": \"a1\", \"r\": \"1:3\", \"cap\": \"Schéma de l'oreille : externe, moyenne, interne\"}, {\"k\": \"tympan\", \"ch\": \"a1\", \"r\": \"1:4\", \"cap\": \"Vue otoscopique du tympan\"}, {\"k\": \"fosses\", \"ch\": \"a2\", \"r\": \"1:6\", \"cap\": \"Fosses nasales et coupe de la région nasale\"}, {\"k\": \"sinus\", \"ch\": \"a3\", \"r\": \"1:8\", \"cap\": \"Sinus de la face (frontaux, ethmoïdaux, sphénoïdaux, maxillaires)\"}, {\"k\": \"pharynx\", \"ch\": \"a4\", \"r\": \"1:9\", \"cap\": \"Coupe sagittale médiane tête et cou ; cavité buccale\"}, {\"k\": \"larynx\", \"ch\": \"a5\", \"r\": \"1:11\", \"cap\": \"Le larynx : vues antérieure et postérieure\"}, {\"k\": \"glotte\", \"ch\": \"a5\", \"r\": \"1:12\", \"cap\": \"Vue de la glotte et des cordes vocales\"}, {\"k\": \"trachee\", \"ch\": \"a5\", \"r\": \"1:12\", \"cap\": \"La trachée : faces antérieure et postérieure\"}, {\"k\": \"tableau\", \"ch\": \"d4\", \"r\": \"1:23\", \"cap\": \"Tableau : stades de la laryngite aiguë sous-glottique\"}, {\"k\": \"furoncle\", \"ch\": \"b4\", \"r\": \"1:25\", \"cap\": \"Furoncle du conduit auditif externe\"}, {\"k\": \"omacong\", \"ch\": \"b5\", \"r\": \"1:27\", \"cap\": \"Otite congestive : tympan rouge et épaissi\"}, {\"k\": \"omacoll\", \"ch\": \"b5\", \"r\": \"1:27\", \"cap\": \"OMA suppurée collectée : tympan bombé\"}, {\"k\": \"omaperf\", \"ch\": \"b5\", \"r\": \"1:27\", \"cap\": \"OMA suppurée perforée : écoulement de pus\"}, {\"k\": \"angine\", \"ch\": \"d3\", \"r\": \"2:7\", \"cap\": \"Aspect de l'angine (amygdales inflammatoires)\"}, {\"k\": \"mechage\", \"ch\": \"e3\", \"r\": \"2:19\", \"cap\": \"Mèche tassée en accordéon dans la fosse nasale\"}], \"fb\": {\"b1\": \"oreille\", \"b2\": \"oreille\", \"b3\": \"oreille\", \"c1\": \"mechage\", \"c2\": \"fosses\", \"c3\": \"sinus\", \"c4\": \"pharynx\", \"d1\": \"pharynx\", \"d2\": \"pharynx\", \"d5\": \"larynx\", \"e1\": \"tympan\", \"e2\": \"fosses\", \"e4\": \"trachee\"}};\nconst IM={\"oreille\": \"@@IMG132@@\", \"tympan\": \"@@IMG133@@\", \"fosses\": \"@@IMG134@@\", \"sinus\": \"@@IMG135@@\", \"pharynx\": \"@@IMG136@@\", \"larynx\": \"@@IMG137@@\", \"glotte\": \"@@IMG138@@\", \"trachee\": \"@@IMG139@@\", \"tableau\": \"@@IMG140@@\", \"furoncle\": \"@@IMG141@@\", \"omacong\": \"@@IMG142@@\", \"omacoll\": \"@@IMG143@@\", \"omaperf\": \"@@IMG144@@\", \"angine\": \"@@IMG145@@\", \"mechage\": \"@@IMG146@@\"};\n/* ===================== DONNÉES DÉRIVÉES ===================== */\nconst CH={};D.ch.forEach((c,i)=>{c.i=i;CH[c.id]=c});\nconst BL={};D.blocks.forEach(b=>BL[b.id]=b);\nconst FI={};D.fiches.forEach(f=>FI[f.id]=f);\nconst QI={};D.qs.forEach(q=>{QI[q.id]=q});\nconst PG={};D.pages.forEach(p=>{PG[p.d+':'+p.p]=p});\nconst RUB={anat:['Anatomie-physio','🫁','#2F6B5E'],def:['Définition','📘','#15335C'],cause:['Épidémio-causes','🦠','#E8684A'],clin:['Clinique','🩺','#1F4A7E'],exam:['Examens','🔬','#3B3F8F'],trt:['Traitement','💊','#2E6FA3'],cat:['CAT IDE','🧑🏾‍⚕️','#B07A12'],prev:['Prévention','🛡️','#2E8B57'],comp:['Complications','⚠️','#C0392B']};\nconst TYP={qcm:'QCM',vf:'Vrai/Faux',open:'Question ouverte',cas:'Cas clinique'};\nconst DIF=['','Facile','Moyen','Difficile'];\nconst AVS=['👩🏾‍⚕️','👨🏾‍⚕️','🧑🏾‍🎓','👂🏾','👃🏾','🩺','🦉','🦁','🌺','⭐','🔥','💡'];\nconst qRub=q=>FI[q.f].rub, qPg=q=>FI[q.f].pg;\nconst qByCh=id=>D.qs.filter(q=>q.ch===id);\nfunction chPages(c){const [d,r]=c.r.split(':');const [a,b]=r.split('-').map(Number);const o=[];for(let p=a;p<=(b||a);p++)o.push(d+':'+p);return o}\n/* ===================== ÉTAT / SAUVEGARDE ===================== */\nconst KEY='orl_infas_l3_v1';\nconst blank=()=>({name:'',av:'👩🏾‍⚕️',xp:0,streak:0,last:'',daily:{},time:0,ans:{},cards:{},fav:[],read:[],tips:{},notes:{},hl:{},cur:null});\nlet S=load();\nfunction load(){try{const s=JSON.parse(localStorage.getItem(KEY)||'null');return Object.assign(blank(),s||{})}catch(e){return blank()}}\nfunction save(){try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}}\nconst today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};\nfunction dayObj(){const t=today();return S.daily[t]||(S.daily[t]={q:0,ok:0,s:0})}\nfunction activity(){const t=today();if(S.last!==t){const y=new Date();y.setDate(y.getDate()-1);const ys=y.getFullYear()+'-'+String(y.getMonth()+1).padStart(2,'0')+'-'+String(y.getDate()).padStart(2,'0');S.streak=(S.last===ys)?S.streak+1:1;S.last=t}}\nconst lvl=x=>Math.floor(x/300)+1;\nfunction addXP(n){const a=lvl(S.xp);S.xp+=n;activity();save();const b=lvl(S.xp);if(b>a)toast('🎉 Niveau '+b+' atteint !')}\nsetInterval(()=>{if(!document.hidden){S.time+=10;dayObj().s+=10;save()}},10000);\n/* ===================== OUTILS ===================== */\nconst $=s=>document.querySelector(s);\nconst esc=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');\nconst sh=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};\nfunction toast(m){const t=$('#toast');t.textContent=m;t.style.display='block';clearTimeout(t._t);t._t=setTimeout(()=>t.style.display='none',2200)}\nconst refLab=r=>{const [d,p]=r.split(':');return 'ORL-'+d+' · p.'+p};\nconst pgBtn=r=>`<button class=\"pg\" onclick=\"openRef('${r}')\">${refLab(r)}</button>`;\nconst pgList=s=>String(s).split(',').map(x=>pgBtn(x.trim())).join('');\nfunction chOfRef(r){const p=PG[r];return p?p.ch:null}\nfunction openRef(r){const c=chOfRef(r);if(c)go('chapter',{id:c,at:r})}\nfunction mastery(id){const qs=qByCh(id);if(!qs.length)return 0;return Math.round(100*qs.filter(q=>S.ans[q.id]&&S.ans[q.id].ok).length/qs.length)}\nfunction seen(id){return qByCh(id).some(q=>S.ans[q.id])}\nconst mcol=m=>m>=80?'var(--ok)':m>=40?'var(--mid)':'var(--bad)';\nfunction ring(m,sz=54,dark){const r=sz/2-5,c=2*Math.PI*r;return `<svg class=\"ring\" width=\"${sz}\" height=\"${sz}\" viewBox=\"0 0 ${sz} ${sz}\"><circle cx=\"${sz/2}\" cy=\"${sz/2}\" r=\"${r}\" fill=\"none\" stroke=\"${dark?'rgba(255,255,255,.25)':'rgba(0,0,0,.1)'}\" stroke-width=\"6\"/><circle cx=\"${sz/2}\" cy=\"${sz/2}\" r=\"${r}\" fill=\"none\" stroke=\"${mcol(m)}\" stroke-width=\"6\" stroke-linecap=\"round\" stroke-dasharray=\"${c*m/100} ${c}\" transform=\"rotate(-90 ${sz/2} ${sz/2})\"/><text x=\"50%\" y=\"54%\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" dominant-baseline=\"middle\">${m}%</text></svg>`}\nconst acquired=()=>Object.values(S.ans).filter(a=>a.ok).length;\nconst mastered=()=>D.ch.filter(c=>mastery(c.id)>=80).length;\nfunction fmtT(s){const h=Math.floor(s/3600),m=Math.floor(s%3600/60);return h?h+' h '+m+' min':m+' min'}\n/* ===================== EN-TÊTE / PIED ===================== */\nfunction hdr(back){return `<header class=\"hdr\">${back?`<button class=\"hback\" aria-label=\"Retour\" onclick=\"goBack()\">←</button>`:''}<div class=\"brand\"><span class=\"logo\">ORL</span><span class=\"sub\">Oto-rhino-laryngologie · Infirmiers et sages-femmes L3</span></div><div class=\"sig\">Créé par <b>Daniel Noufe</b> · INFAS</div></header>`}\nconst foot=()=>`<div class=\"foot\">Créé par <b>Daniel Noufe</b> · INFAS</div>`;\n/* ===================== NAVIGATION ===================== */\nconst IC={home:'<path d=\"M3 11l9-8 9 8v9a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z\"/>',ch:'<path d=\"M4 4h7a3 3 0 0 1 3 3v13a2 2 0 0 0-2-2H4zM20 4h-3a3 3 0 0 0-3 3v13a2 2 0 0 1 2-2h4z\"/>',rev:'<rect x=\"3\" y=\"5\" width=\"14\" height=\"15\" rx=\"2\"/><path d=\"M7 3h12a2 2 0 0 1 2 2v12\"/>',st:'<path d=\"M4 20V10M10 20V4M16 20v-7M22 20H2\"/>',pr:'<circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 21c1.5-4 4.5-6 8-6s6.5 2 8 6\"/>'};\nconst TABS=[['home','Accueil','home'],['chapters','Chapitres','ch'],['revise','Réviser','rev'],['stats','Stats','st'],['profile','Profil','pr']];\nconst TABOF={home:'home',chapters:'chapters',sommaire:'chapters',chapter:'chapters',revise:'revise',quizhub:'revise',config:'revise',quiz:'revise',result:'revise',flash:'revise',errors:'revise',gallery:'revise',stats:'stats',profile:'profile',mine:'profile',glossary:'profile',tables:'profile',search:'home'};\nfunction nav(v){$('#nav').innerHTML=TABS.map(([id,l,ic])=>`<button class=\"${TABOF[v]===id?'on':''}\" onclick=\"go('${id}')\" aria-label=\"${l}\"><span class=\"pi\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">${IC[ic]}</svg></span>${l}</button>`).join('')}\nlet VIEW='home',PAR={},HIST=[];\nfunction go(v,p={},noHist){if(!noHist&&VIEW&&!(VIEW===v&&JSON.stringify(PAR)===JSON.stringify(p)))HIST.push([VIEW,PAR,window.scrollY]);if(HIST.length>40)HIST.shift();VIEW=v;PAR=p;render();if(!p.at&&!p.keep)window.scrollTo(0,0)}\nfunction goBack(){const h=HIST.pop();if(!h){go('home',{},true);return}VIEW=h[0];PAR=h[1];render();window.scrollTo(0,h[2]||0)}\nfunction render(){hideHL();nav(VIEW);const f=V[VIEW]||V.home;$('#app').innerHTML=f(PAR);if(VIEW==='chapter')afterChapter(PAR)}\nconst V={};\n/* ===================== ACCUEIL ===================== */\nconst EAR=`<svg width=\"78\" height=\"78\" viewBox=\"0 0 80 80\" aria-hidden=\"true\"><circle cx=\"40\" cy=\"40\" r=\"38\" fill=\"#0E2340\"/><path d=\"M47 60c-3 5-12 5-14-1-2-5 3-8 3-13 0-4-6-5-6-12 0-9 7-15 16-15s15 7 15 15c0 7-5 9-7 13-1 3-1 6-3 9z\" fill=\"none\" stroke=\"#9BEDE4\" stroke-width=\"4\" stroke-linecap=\"round\"/><path d=\"M38 34c0-4 3-7 7-7s7 3 7 7c0 3-3 4-4 6\" fill=\"none\" stroke=\"#9BEDE4\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M14 30c3-3 3-9 0-12M9 34c6-6 6-18 0-24\" fill=\"none\" stroke=\"#2EC4B6\" stroke-width=\"3\" stroke-linecap=\"round\" opacity=\".8\"/></svg>`;\nV.home=()=>{const x=S.xp%300,l=lvl(S.xp);const cur=S.cur&&S.cur.ids&&S.cur.i<S.cur.ids.length;\nreturn hdr()+`<button class=\"pcard\" onclick=\"go('profile')\"><div class=\"row\"><div class=\"av\">${S.av}</div><div class=\"grow\"><div style=\"font-size:19px;font-weight:800\">Bonjour ${esc(S.name||'')}${S.name?'':'à toi'} !</div><div class=\"stat3\"><span>NIV. ${l}</span><span>${S.xp} XP</span><span>🔥 ${S.streak} j</span></div></div></div><div class=\"xpbar\"><i style=\"width:${x/3}%\"></i></div><div class=\"row small\" style=\"justify-content:space-between\"><span>${x}/300 XP vers le niveau ${l+1}</span><span>${mastered()}/${D.ch.length} chapitres maîtrisés</span></div></button>\n<div style=\"margin-top:10px\"><button class=\"btn gold full\" onclick=\"continueQ()\">▶ ${cur?'Continuer le quiz ('+(S.cur.i+1)+'/'+S.cur.ids.length+')':'Continuer : 20 questions à revoir'}</button></div>\n<div class=\"search\"><span>🔎</span><input id=\"gs\" placeholder=\"Rechercher dans le cours, les questions, le glossaire\" onkeydown=\"if(event.key==='Enter')doSearch(this.value)\"><button class=\"btn dark\" style=\"min-height:40px\" onclick=\"doSearch($('#gs').value)\">OK</button></div>\n<button class=\"hero\" onclick=\"go('quizhub')\">${EAR}<span><b>Lancer le quiz</b>${D.qs.length} questions · QCM, Vrai/Faux, ouvertes, cas cliniques</span></button>\n<h2 class=\"tt\">Progression par bloc</h2><div class=\"card\">${D.blocks.map(b=>{const cs=D.ch.filter(c=>c.b===b.id);return `<div style=\"margin:8px 0\"><div class=\"row small\"><b style=\"color:${b.c}\">Bloc ${b.id}</b><span class=\"mut\">${b.t}</span></div><div class=\"seg\">${cs.map(c=>{const m=mastery(c.id),s=seen(c.id);return `<button title=\"${esc(c.t)} : ${m} %\" aria-label=\"${esc(c.t)} ${m} %\" style=\"background:${s?mcol(m):'var(--line)'}\" onclick=\"go('chapter',{id:'${c.id}'})\"></button>`}).join('')}</div></div>`}).join('')}\n<div class=\"legend\"><span><i style=\"background:var(--line)\"></i>Non commencé</span><span><i style=\"background:var(--bad)\"></i>&lt; 40 %</span><span><i style=\"background:var(--mid)\"></i>40-79 %</span><span><i style=\"background:var(--ok)\"></i>≥ 80 %</span></div></div>\n<div class=\"tiles\">${[['📖','Sommaire & cours',\"go('sommaire')\"],['❓','Quiz',\"go('quizhub')\"],['🩺','Cas cliniques',\"startMode('cas')\"],['📊','Tableaux résumés',\"go('tables')\"],['🔤','Glossaire',\"go('glossary')\"],['🖼️','Galerie',\"go('gallery')\"]].map(t=>`<button class=\"tile\" onclick=\"${t[2]}\"><span class=\"ic\">${t[0]}</span>${t[1]}</button>`).join('')}</div>`+foot()};\nfunction continueQ(){if(S.cur&&S.cur.ids&&S.cur.i<S.cur.ids.length){Z=S.cur;go('quiz');return}\nconst pri=D.qs.map(q=>{const a=S.ans[q.id];return [q.id,a?(a.ok?3:1):2,Math.random()]}).sort((a,b)=>a[1]-b[1]||a[2]-b[2]).slice(0,20).map(x=>x[0]);startQuiz(pri,'Questions à revoir')}\n/* ===================== RECHERCHE ===================== */\nconst norm=s=>String(s).toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'');\nfunction doSearch(t){t=(t||'').trim();if(t.length<2){toast('Tape au moins 2 lettres');return}go('search',{t})}\nV.search=({t})=>{const n=norm(t);const strip=s=>s.replace(/\\+\\+\\+/g,'');\nconst pages=D.pages.filter(p=>norm(p.t).includes(n)).map(p=>{const s=strip(p.t),i=norm(s).indexOf(n);return {p,sn:s.slice(Math.max(0,i-60),i+90)}});\nconst qs=D.qs.filter(q=>norm(q.q+' '+(q.s||'')+' '+(q.o||[]).join(' ')+' '+(q.a||'')+' '+CH[q.ch].t).includes(n));\nconst gl=D.gl.filter(g=>norm(g.t+' '+g.d).includes(n));\nconst hi=s=>esc(s).replace(new RegExp('('+t.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\\\$&')+')','gi'),'<mark class=\"key\">$1</mark>');\nreturn hdr(1)+`<div class=\"search\"><span>🔎</span><input id=\"gs\" value=\"${esc(t)}\" onkeydown=\"if(event.key==='Enter')doSearch(this.value)\"><button class=\"btn dark\" style=\"min-height:40px\" onclick=\"doSearch($('#gs').value)\">OK</button></div>\n<h2 class=\"tt\">Cours (${pages.length})</h2>${pages.slice(0,30).map(({p,sn})=>`<button class=\"card\" style=\"display:block;width:100%;text-align:left\" onclick=\"go('chapter',{id:'${p.ch}',at:'${p.d}:${p.p}'})\"><b>${esc(CH[p.ch].t)}</b> <span class=\"pg\">${refLab(p.d+':'+p.p)}</span><div class=\"small mut\">…${hi(sn)}…</div></button>`).join('')||'<p class=\"mut\">Aucun passage du cours.</p>'}\n<h2 class=\"tt\">Questions (${qs.length})</h2>${qs.slice(0,40).map(q=>`<div class=\"card\"><div class=\"small mut\">${esc(CH[q.ch].t)} · ${TYP[q.t]}</div><b>${hi(q.q)}</b><details><summary class=\"small\" style=\"cursor:pointer;color:var(--rasp);font-weight:700;padding:6px 0\">Voir la réponse</summary><div>${esc(answerText(q))}</div><div class=\"small mut\">${esc(q.x)}</div>${pgList(qPg(q))}</details></div>`).join('')||'<p class=\"mut\">Aucune question.</p>'}\n<h2 class=\"tt\">Glossaire (${gl.length})</h2>${gl.map(g=>`<div class=\"card\"><b>${hi(g.t)}</b><div class=\"small\">${hi(g.d)}</div>${pgList(g.p)}</div>`).join('')||'<p class=\"mut\">Aucun terme.</p>'}`+foot()};\nfunction answerText(q){if(q.t==='vf')return q.v?'Vrai':'Faux';if(q.t==='open')return q.a;return q.o[q.c]}\n/* ===================== CHAPITRES ===================== */\nV.chapters=({f='all'})=>{const list=D.ch.filter(c=>f==='all'||(f==='fav'?S.fav.includes(c.id):c.b===f));\nreturn hdr()+`<div class=\"pills\"><div class=\"pill\"><b>${D.ch.length}</b>chapitres</div><div class=\"pill\"><b>${S.read.length}</b>lus</div><div class=\"pill\"><b>${mastered()}</b>maîtrisés</div><div class=\"pill\"><b>${S.fav.length}</b>favoris</div></div>\n<div class=\"row wrap\">${[['all','Tous'],...D.blocks.map(b=>[b.id,'Bloc '+b.id]),['fav','★ Favoris']].map(([k,l])=>`<button class=\"chip ${f===k?'on':''}\" onclick=\"go('chapters',{f:'${k}',keep:1},true)\">${l}</button>`).join('')}</div>\n<button class=\"btn ghost full\" style=\"margin-top:12px\" onclick=\"go('sommaire')\">📖 Sommaire classique</button>\n${list.map((c,i)=>{const m=mastery(c.id),k=i%3,dk=k>0;return `<div class=\"cc k${k}\"><button class=\"grow row\" style=\"text-align:left;gap:12px\" onclick=\"go('chapter',{id:'${c.id}'})\">${ring(m,56,dk)}<span><span class=\"m\">Bloc ${c.b} · ${esc(BL[c.b].t)}</span><span class=\"t\" style=\"display:block\">${esc(c.t)}</span><span class=\"m\">${refLab(c.r.split('-')[0])}${c.r.includes('-')?'–'+c.r.split('-')[1]:''} · ${qByCh(c.id).length} questions${S.read.includes(c.id)?' · ✓ lu':''}</span></span></button><button class=\"star\" aria-label=\"Favori\" onclick=\"togFav('${c.id}')\">${S.fav.includes(c.id)?'★':'☆'}</button></div>`}).join('')||'<p class=\"mut\">Aucun chapitre favori pour l\\'instant : touche ☆ sur une carte.</p>'}`+foot()};\nfunction togFav(id){const i=S.fav.indexOf(id);i<0?S.fav.push(id):S.fav.splice(i,1);save();const y=scrollY;render();scrollTo(0,y)}\nV.sommaire=()=>hdr(1)+`<h2 class=\"tt\">Sommaire</h2><p class=\"small mut\">Pages = pages réelles des PDF (ORL-1 = partie 1, ORL-2 = partie 2). Touche une page pour l'ouvrir.</p>`+D.blocks.map(b=>`<div class=\"bband\" style=\"background:${b.c}\">Bloc ${b.id} · ${esc(b.t)}</div>`+D.ch.filter(c=>c.b===b.id).map(c=>`<div class=\"sline\"><button class=\"t\" style=\"color:${b.c};text-align:left;min-height:36px\" onclick=\"go('chapter',{id:'${c.id}'})\">${esc(c.t)}</button><div>${chPages(c).map(r=>pgBtn(r)).join('')}</div></div>`).join('')).join('')+foot();\n/* ===================== TEXTE D'UN CHAPITRE ===================== */\nfunction md(t){const L=t.split('\\n');let h='',ul=0;const inl=s=>esc(s).replace(/\\+\\+\\+(.+?)\\+\\+\\+/g,'<mark class=\"key\">$1</mark>');\nfor(const l of L){if(l.startsWith('- ')){if(!ul){h+='<ul>';ul=1}h+='<li>'+inl(l.slice(2))+'</li>';continue}if(ul){h+='</ul>';ul=0}\nif(l.startsWith('## '))h+='<h3>'+inl(l.slice(3))+'</h3>';else if(l.startsWith('# '))h+='<h2>'+inl(l.slice(2))+'</h2>';else if(l.startsWith('['))h+='<p class=\"fig\">'+inl(l)+'</p>';else if(l.trim())h+='<p>'+inl(l)+'</p>'}\nif(ul)h+='</ul>';return h}\nV.chapter=({id})=>{const c=CH[id];const pgs=chPages(c).map(r=>PG[r]).filter(Boolean);const m=mastery(id);\nreturn hdr(1)+`<div class=\"card\"><div><span class=\"badge\" style=\"background:${BL[c.b].c};color:#fff\">Bloc ${c.b}</span><span class=\"badge\">${qByCh(id).length} questions</span><span class=\"badge\" style=\"background:${mcol(m)};color:#fff\">${m} % maîtrisé</span>${S.read.includes(id)?'<span class=\"badge\">✓ Lu</span>':''}</div><h2 style=\"margin:8px 0 4px;font-size:21px\">${esc(c.t)}</h2><div class=\"small mut\">Sources : ${chPages(c).map(pgBtn).join('')}</div><div class=\"row\" style=\"margin-top:10px\"><button class=\"btn gold grow\" onclick=\"startChapter('${id}')\">Quiz du chapitre</button><button class=\"btn line grow\" onclick=\"markRead('${id}')\">${S.read.includes(id)?'✓ Lu':'Marquer comme lu'}</button></div></div>\n${D.rs.filter(t=>t.ch===id).map(t=>`<details class=\"card\" open><summary style=\"cursor:pointer;font-weight:800;min-height:32px\">📋 Tableau résumé du chapitre</summary>${tblHTML(t).replace('<div class=\"card\">','<div>')}</details>`).join('')}${pgs.map(p=>{const pid=p.d+':'+p.p;const ims=D.imgs.filter(i=>i.r===pid);const n=S.notes[pid];return `<section class=\"page\" id=\"p-${p.d}-${p.p}\"><span class=\"pmark\">ORL-${p.d} · Page ${p.p}</span> <span class=\"small mut\">(page imprimée ${p.i})</span>${p.ch!==id?`<span class=\"small mut\"> · partagée avec « ${esc(CH[p.ch].t)} »</span>`:''}<div class=\"pgtext\" data-pid=\"${pid}\">${md(p.t)}</div>${ims.map(im=>`<img class=\"figimg\" src=\"${IM[im.k]}\" alt=\"${esc(im.cap)}\" onclick=\"openViewer('${im.k}')\"><div class=\"cap\">${esc(im.cap)} · ${refLab(im.r)}</div>`).join('')}${n?`<div class=\"note\">📝 ${esc(n)}<div class=\"row\" style=\"margin-top:6px\"><button class=\"annot\" onclick=\"annot('${pid}')\">Modifier</button><button class=\"annot\" onclick=\"delNote('${pid}')\">Supprimer</button></div></div>`:''}<div><button class=\"annot\" onclick=\"annot('${pid}')\">✎ ${n?'Modifier la note':'Annoter'}</button></div></section>`}).join('')}\n<p class=\"small mut\">Astuce : sélectionne un passage pour le surligner ; touche un surlignage pour le retirer.</p>`+foot()};\nfunction afterChapter(p){document.querySelectorAll('.pgtext').forEach(applyHL);\n// pages partagées (lavage oreille/nez) : afficher aussi la page de début si besoin\nif(p.at){const el=document.getElementById('p-'+p.at.replace(':','-'));if(el)setTimeout(()=>el.scrollIntoView({block:'start'}),30)}}\nfunction markRead(id){if(!S.read.includes(id)){S.read.push(id);addXP(5);toast('+5 XP · chapitre lu')}save();const y=scrollY;render();scrollTo(0,y)}\nfunction startChapter(id){startQuiz(sh(qByCh(id).map(q=>q.id)),'Quiz : '+CH[id].t)}\n/* --- Annotations --- */\nfunction annot(pid){modal(`<h3 style=\"margin:0 0 8px\">Note · ${refLab(pid)}</h3><textarea id=\"mt\">${esc(S.notes[pid]||'')}</textarea><div class=\"row\" style=\"margin-top:10px\"><button class=\"btn line grow\" onclick=\"closeModal()\">Annuler</button><button class=\"btn gold grow\" onclick=\"saveNote('${pid}')\">Enregistrer</button></div>`);setTimeout(()=>$('#mt').focus(),50)}\nfunction saveNote(pid){const v=$('#mt').value.trim();if(v)S.notes[pid]=v;else delete S.notes[pid];save();closeModal();const y=scrollY;render();scrollTo(0,y);toast('Note enregistrée')}\nfunction delNote(pid){delete S.notes[pid];save();const y=scrollY;render();scrollTo(0,y)}\n/* --- Surlignage --- */\nconst HLC={y:'Important',g:'Acquis',p:'À revoir',b:'Définition'};\nlet SELR=null;\nfunction applyHL(el){const pid=el.dataset.pid;const L=S.hl[pid]||[];L.forEach(h=>wrapRange(el,h))}\nfunction wrapRange(el,h){const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let o=0,n;const seg=[];while(n=w.nextNode()){const len=n.nodeValue.length,a=o,b=o+len;if(b>h.s&&a<h.e)seg.push([n,Math.max(0,h.s-a),Math.min(len,h.e-a)]);o=b}\nseg.forEach(([node,s,e])=>{let t=node;if(s>0)t=t.splitText(s);if(e-s<t.nodeValue.length)t.splitText(e-s);const m=document.createElement('mark');m.className='hl '+h.c;m.dataset.id=h.id;m.title=HLC[h.c]+' · toucher pour retirer';t.parentNode.insertBefore(m,t);m.appendChild(t)})}\nfunction hideHL(){const b=$('#hlbar');if(b)b.style.display='none';SELR=null}\nfunction checkSel(){const s=window.getSelection();if(!s||s.isCollapsed||!s.rangeCount){return}const r=s.getRangeAt(0);const c=r.commonAncestorContainer;const el=(c.nodeType===1?c:c.parentElement).closest('.pgtext');if(!el||!r.toString().trim()){return}\nconst pre=document.createRange();pre.selectNodeContents(el);pre.setEnd(r.startContainer,r.startOffset);const st=pre.toString().length;SELR={el,s:st,e:st+r.toString().length,t:r.toString()};\nconst b=$('#hlbar');b.innerHTML=Object.entries(HLC).map(([k,l])=>`<button class=\"hlb\" style=\"background:${{y:'#FFE066',g:'#9BE5B0',p:'#F7B6CF',b:'#A9D3FF'}[k]}\" onmousedown=\"event.preventDefault()\" onclick=\"doHL('${k}')\">${l}</button>`).join('')+`<button style=\"color:#fff\" onclick=\"hideHL()\">✕</button>`;b.style.display='flex'}\nlet selT;document.addEventListener('selectionchange',()=>{clearTimeout(selT);selT=setTimeout(()=>{if(VIEW==='chapter')checkSel()},250)});\nfunction doHL(c){if(!SELR)return;const pid=SELR.el.dataset.pid;(S.hl[pid]=S.hl[pid]||[]).push({id:Date.now().toString(36),s:SELR.s,e:SELR.e,c,t:SELR.t.slice(0,200)});save();window.getSelection().removeAllRanges();hideHL();const y=scrollY;render();scrollTo(0,y);toast('Surligné : '+HLC[c])}\ndocument.addEventListener('click',e=>{const m=e.target.closest&&e.target.closest('mark.hl');if(!m)return;const pid=m.closest('.pgtext').dataset.pid;const id=m.dataset.id;modal(`<h3 style=\"margin:0 0 8px\">Retirer ce surlignage ?</h3><p class=\"small mut\">${esc((S.hl[pid]||[]).find(h=>h.id===id)?.t||'')}</p><div class=\"row\"><button class=\"btn line grow\" onclick=\"closeModal()\">Garder</button><button class=\"btn gold grow\" onclick=\"rmHL('${pid}','${id}')\">Retirer</button></div>`)});\nfunction rmHL(pid,id){S.hl[pid]=(S.hl[pid]||[]).filter(h=>h.id!==id);if(!S.hl[pid].length)delete S.hl[pid];save();closeModal();if(VIEW==='chapter'){const y=scrollY;render();scrollTo(0,y)}else render()}\n/* ===================== MODAL ===================== */\nfunction modal(h){const m=$('#modal');m.innerHTML=`<div class=\"box\">${h}</div>`;m.style.display='flex';m.onclick=e=>{if(e.target===m)closeModal()}}\nfunction closeModal(){$('#modal').style.display='none'}\n/* ===================== VISIONNEUSE ===================== */\nlet VL=[],VI=0;\nfunction openViewer(k,list){VL=list||D.imgs.map(i=>i.k);VI=Math.max(0,VL.indexOf(k));drawViewer();$('#viewer').style.display='flex'}\nfunction drawViewer(){const im=D.imgs.find(i=>i.k===VL[VI]);$('#viewer').innerHTML=`<button class=\"vx\" aria-label=\"Fermer\" onclick=\"closeViewer()\">✕</button><img src=\"${IM[im.k]}\" alt=\"${esc(im.cap)}\"><div style=\"margin-top:12px;text-align:center;max-width:520px\"><b>${esc(im.cap)}</b><div class=\"small\" style=\"opacity:.8\">${esc(CH[im.ch].t)} · ${refLab(im.r)} · ${VI+1}/${VL.length}</div></div><div class=\"vn\"><button class=\"btn line\" style=\"color:var(--ink)\" onclick=\"vStep(-1)\">← Précédente</button><button class=\"btn gold\" onclick=\"vStep(1)\">Suivante →</button></div>`}\nfunction vStep(d){VI=(VI+d+VL.length)%VL.length;drawViewer()}\nfunction closeViewer(){$('#viewer').style.display='none'}\n$('#viewer').addEventListener('click',e=>{if(e.target.id==='viewer')closeViewer()});\nlet tx=null;$('#viewer').addEventListener('touchstart',e=>{tx=e.touches[0].clientX},{passive:true});$('#viewer').addEventListener('touchend',e=>{if(tx==null)return;const dx=e.changedTouches[0].clientX-tx;if(Math.abs(dx)>50)vStep(dx<0?1:-1);tx=null});\ndocument.addEventListener('keydown',e=>{if($('#viewer').style.display==='flex'){if(e.key==='Escape')closeViewer();if(e.key==='ArrowRight')vStep(1);if(e.key==='ArrowLeft')vStep(-1)}else if(e.key==='Escape')closeModal()});\nV.gallery=()=>hdr(1)+`<h2 class=\"tt\">Galerie (${D.imgs.length} figures)</h2><div class=\"gal\">${D.imgs.map(i=>`<button onclick=\"openViewer('${i.k}')\"><img src=\"${IM[i.k]}\" alt=\"\"><b>${esc(i.cap)}</b><div class=\"mut\">${esc(CH[i.ch].t)} · ${refLab(i.r)}</div></button>`).join('')}</div>`+foot();\n/* ===================== GLOSSAIRE / TABLEAUX ===================== */\nV.glossary=({q=''})=>{const n=norm(q);const L=D.gl.filter(g=>!n||norm(g.t+' '+g.d).includes(n));let last='';\nreturn hdr(1)+`<h2 class=\"tt\">Glossaire (${D.gl.length} termes)</h2><div class=\"search\"><span>🔎</span><input id=\"gq\" value=\"${esc(q)}\" placeholder=\"Filtrer les termes\" oninput=\"clearTimeout(window._g);window._g=setTimeout(()=>{go('glossary',{q:this.value,keep:1},true);const i=$('#gq');i.focus();i.setSelectionRange(i.value.length,i.value.length)},300)\"></div>`+L.map(g=>{const l=norm(g.t)[0].toUpperCase();const h=l!==last?`<div class=\"glet\">${l}</div>`:'';last=l;return h+`<div class=\"card\" style=\"margin:6px 0;padding:12px 14px\"><b>${esc(g.t)}</b><div class=\"small\">${esc(g.d)}</div>${pgList(g.p)}</div>`}).join('')+foot()};\nfunction tblHTML(t,showCh){return `<div class=\"card\">${showCh?`<div class=\"small mut\">Bloc ${CH[t.ch].b} · <button style=\"color:var(--rasp);font-weight:700\" onclick=\"go('chapter',{id:'${t.ch}'})\">${esc(CH[t.ch].t)} ›</button></div>`:''}<b>${esc(t.t)}</b><div class=\"tbl\"><table><tr>${t.h.map(h=>`<th>${esc(h)}</th>`).join('')}</tr>${t.r.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</table></div><div style=\"margin-top:6px\">${pgList(t.p)}</div></div>`}\nV.tables=({k='res',b=''})=>hdr(1)+`<h2 class=\"tt\">Tableaux</h2><div class=\"row wrap\"><button class=\"chip ${k==='res'?'on':''}\" onclick=\"go('tables',{k:'res',keep:1},true)\">Résumés par chapitre (${D.rs.length})</button><button class=\"chip ${k==='cmp'?'on':''}\" onclick=\"go('tables',{k:'cmp',keep:1},true)\">Comparatifs (${D.tb.length})</button></div>`+(k==='res'?`<div class=\"row wrap\" style=\"margin-top:8px\"><button class=\"chip ${!b?'on':''}\" onclick=\"go('tables',{k:'res',keep:1},true)\">Tous</button>${D.blocks.map(x=>`<button class=\"chip ${b===x.id?'on':''}\" onclick=\"go('tables',{k:'res',b:'${x.id}',keep:1},true)\">Bloc ${x.id}</button>`).join('')}</div>`+D.blocks.filter(x=>!b||x.id===b).map(x=>`<div class=\"bband\" style=\"background:${x.c}\">Bloc ${x.id} · ${esc(x.t)}</div>`+D.rs.filter(t=>CH[t.ch].b===x.id).map(t=>tblHTML(t,1)).join('')).join(''):D.tb.map(t=>tblHTML(t)).join(''))+foot();\n/* ===================== QUIZ : ACCUEIL ===================== */\nconst MODES=[['qcm','QCM','🔘','#1F4A7E',['qcm']],['vf','Vrai / Faux','⚖️','#3B3F8F',['vf']],['mix','Mélange','🎲','#D69A1C',['qcm','vf','open','cas']],['open','Questions ouvertes','✍️','#2F6B5E',['open']],['cas','Cas cliniques','🩺','#E8684A',['cas']],['perso','Personnalisé','🎛️','#2E6FA3',['qcm','vf','open','cas']],['err','Refaire mes erreurs','🔁','#C0392B',null]];\nconst errIds=()=>D.qs.filter(q=>S.ans[q.id]&&!S.ans[q.id].ok).map(q=>q.id);\nV.quizhub=()=>{const tot=D.qs.length,ac=acquired();\nreturn `<div class=\"qhead\"><div class=\"brand\"><span class=\"logo\">ORL</span><span class=\"sub\">Oto-rhino-laryngologie · Lancer le quiz</span></div><div class=\"sig\">Créé par <b>Daniel Noufe</b> · INFAS</div><div class=\"search\" style=\"box-shadow:none;margin:12px 0 0\"><span>🔎</span><input id=\"gs\" placeholder=\"Rechercher une question ou une notion\" onkeydown=\"if(event.key==='Enter')doSearch(this.value)\"><button class=\"btn gold\" style=\"min-height:40px\" onclick=\"doSearch($('#gs').value)\">OK</button></div><div class=\"cnt3\"><div><b>${Math.round(100*ac/tot)} %</b>maîtrisé</div><div><b>${tot}</b>questions</div><div><b>${ac}</b>acquises</div></div></div>`+\nMODES.map(([k,l,ic,col,ty])=>{const qs=ty?D.qs.filter(q=>ty.includes(q.t)):D.qs.filter(q=>S.ans[q.id]);const n=k==='err'?errIds().length:qs.length;const p=k==='err'?(qs.length?Math.round(100*(qs.length-n)/qs.length):0):Math.round(100*qs.filter(q=>S.ans[q.id]&&S.ans[q.id].ok).length/Math.max(1,qs.length));\nreturn `<button class=\"mode\" onclick=\"startMode('${k}')\"><span class=\"ic\" style=\"background:${col}22;color:${col}\">${ic}</span><span class=\"grow\"><b>${l}</b><span class=\"small mut\" style=\"display:block\">${k==='err'?n+' erreur(s) à refaire':n+' questions'}</span><span class=\"bar\"><i style=\"width:${p}%;background:${col}\"></i></span></span><span class=\"mut\">›</span></button>`}).join('')+foot()};\nlet CFG=null;\nfunction startMode(k){if(k==='err'){const e=errIds();if(!e.length){toast('Aucune erreur à refaire 👏');return}startQuiz(sh(e),'Refaire mes erreurs');return}\nconst m=MODES.find(x=>x[0]===k);CFG={n:20,types:[...m[4]],rubs:Object.keys(RUB),chs:D.ch.map(c=>c.id),err:false,open:false,ob:{},title:m[1]};go('config')}\nV.config=()=>{const C=CFG||(CFG={n:20,types:['qcm','vf','open','cas'],rubs:Object.keys(RUB),chs:D.ch.map(c=>c.id),err:false,open:false,ob:{},title:'Personnalisé'});const pool=poolCfg();const max=pool.length;const n=Math.min(C.n,max);\nconst chk=(on,lab,act)=>`<button class=\"chk ${on?'on':''}\" onclick=\"${act}\"><i>${on?'✓':''}</i>${lab}</button>`;\nreturn hdr(1)+`<h2 class=\"tt\">Configurer : ${esc(C.title)}</h2>\n<div class=\"card\"><div class=\"row\"><b class=\"grow\">Nombre de questions</b><b style=\"font-size:22px;color:var(--rasp)\">${max?Math.max(1,n):0}</b></div><input class=\"slider\" type=\"range\" min=\"1\" max=\"${Math.max(1,max)}\" value=\"${Math.max(1,n)}\" oninput=\"CFG.n=+this.value;this.previousElementSibling.lastElementChild.textContent=this.value\" onchange=\"cfgRe()\"><div class=\"row wrap\">${[10,20,50,100,200,500].map(v=>`<button class=\"chip ${C.n===v?'on':''}\" onclick=\"CFG.n=${v};cfgRe()\">${v}</button>`).join('')}<button class=\"chip ${C.n>=9999?'on':''}\" onclick=\"CFG.n=9999;cfgRe()\">Toutes</button></div><div class=\"small mut\" style=\"margin-top:6px\">${max} questions disponibles avec ces filtres</div></div>\n<div class=\"card\"><b>Types</b><div class=\"row wrap\" style=\"margin-top:8px\">${Object.entries(TYP).map(([k,l])=>`<button class=\"chip ${C.types.includes(k)?'on':''}\" onclick=\"tg('types','${k}')\">${l}</button>`).join('')}</div>\n<b style=\"display:block;margin-top:14px\">Rubriques</b><div class=\"row wrap\" style=\"margin-top:8px\">${Object.entries(RUB).map(([k,[l,ic,col]])=>`<button class=\"chip ${C.rubs.includes(k)?'on':''}\" style=\"${C.rubs.includes(k)?`background:${col};border-color:${col}`:`border-color:${col}55`}\" onclick=\"tg('rubs','${k}')\">${ic} ${l}</button>`).join('')}</div>\n<div style=\"margin-top:12px\">${chk(C.err,'Seulement mes erreurs passées','CFG.err=!CFG.err;cfgRe()')}</div></div>\n<div class=\"card\"><button class=\"coll\" onclick=\"CFG.open=!CFG.open;cfgRe()\"><span>Chapitres <span class=\"badge\">${C.chs.length}/${D.ch.length} sélectionnés</span></span><span>${C.open?'▲':'▼'}</span></button>${C.open?`<div class=\"row\" style=\"margin-bottom:6px\"><button class=\"chip\" onclick=\"CFG.chs=D.ch.map(c=>c.id);cfgRe()\">Tous</button><button class=\"chip\" onclick=\"CFG.chs=[];cfgRe()\">Aucun</button></div>`+D.blocks.map(b=>{const cs=D.ch.filter(c=>c.b===b.id);const sel=cs.filter(c=>C.chs.includes(c.id)).length;const o=C.ob[b.id];return `<div class=\"blk\"><button class=\"coll\" style=\"min-height:46px\" onclick=\"CFG.ob['${b.id}']=!CFG.ob['${b.id}'];cfgRe()\"><span style=\"color:${b.c}\">Bloc ${b.id} · ${esc(b.t)} <span class=\"small mut\">(${sel}/${cs.length})</span></span><span>${o?'▲':'▼'}</span></button>${o?`<div class=\"row\" style=\"margin:4px 0\"><button class=\"chip\" onclick=\"blkSel('${b.id}',1)\">Tous</button><button class=\"chip\" onclick=\"blkSel('${b.id}',0)\">Aucun</button></div>`+cs.map(c=>chk(C.chs.includes(c.id),esc(c.t)+` <span class=\"small mut\">(${qByCh(c.id).length})</span>`,`tg('chs','${c.id}')`)).join(''):''}</div>`}).join(''):''}</div>\n<button class=\"btn gold full\" ${max?'':'disabled style=\"opacity:.5\"'} onclick=\"launchCfg()\">Démarrer ${max?Math.max(1,n):0} questions</button>`+foot()};\nfunction poolCfg(){const C=CFG;return D.qs.filter(q=>C.types.includes(q.t)&&C.rubs.includes(qRub(q))&&C.chs.includes(q.ch)&&(!C.err||(S.ans[q.id]&&!S.ans[q.id].ok)))}\nfunction cfgRe(){const y=scrollY;render();scrollTo(0,y)}\nfunction tg(k,v){const a=CFG[k],i=a.indexOf(v);i<0?a.push(v):a.splice(i,1);cfgRe()}\nfunction blkSel(b,on){const ids=D.ch.filter(c=>c.b===b).map(c=>c.id);CFG.chs=CFG.chs.filter(x=>!ids.includes(x));if(on)CFG.chs.push(...ids);cfgRe()}\nfunction launchCfg(){const p=sh(poolCfg());if(!p.length)return;startQuiz(p.slice(0,Math.min(CFG.n,p.length)).map(q=>q.id),CFG.title)}\n/* ===================== QUIZ ===================== */\nlet Z=null;\nfunction startQuiz(ids,title){if(!ids.length){toast('Aucune question');return}Z={ids,i:0,ans:{},ord:{},title,xp0:S.xp};S.cur=Z;save();go('quiz')}\nconst LET='ABCD';\nfunction normA(s){return norm(s).replace(/[’'`]/g,' ').replace(/[^a-z0-9,. ]/g,' ').replace(/\\b(le|la|les|l|un|une|des|du|de|d|au|aux|et|a|en)\\b/g,' ').replace(/\\s+/g,' ').trim()}\nfunction lev(a,b){const m=a.length,n=b.length;if(!m)return n;if(!n)return m;let p=Array.from({length:n+1},(_,j)=>j);for(let i=1;i<=m;i++){const c=[i];for(let j=1;j<=n;j++)c[j]=Math.min(p[j]+1,c[j-1]+1,p[j-1]+(a[i-1]===b[j-1]?0:1));p=c}return p[n]}\nconst nums=s=>(String(s).match(/\\d+(?:[.,]\\d+)?/g)||[]).map(x=>x.replace(',','.'));\nfunction checkOpen(inp,q){const u=normA(inp);if(!u)return false;const exp=nums(q.a),got=nums(inp);\nif(exp.length){const e=[...exp].sort().join('|'),g=[...got].sort().join('|');if(e!==g&&!q.alt.some(a=>!nums(a).length&&normA(a)===u))return false}\nconst vars=[q.a,...q.alt].map(normA);for(const v of vars){if(u===v)return true;const nd=v.replace(/\\s/g,''),ud=u.replace(/\\s/g,'');if(nd.length>=4&&lev(nd,ud)<=Math.max(1,Math.floor(nd.length*0.2)))return true;if(u.split(' ').length>1&&u.includes(v)&&v.length>=4)return true}\nif(q.k&&q.k.length){const w=u.split(' ');if(q.k.every(k=>{k=normA(k);return w.some(x=>x===k||(k.length>4&&lev(x,k)<=1))||u.includes(k)}))return true}\nif(!exp.length){const w=u.split(' ');if(vars.some(v=>v.length>=5&&w.some(x=>x.length>=5&&lev(x,v)<=Math.max(1,Math.floor(v.length*0.2)))))return true}\nreturn false}\nfunction answer(g){const q=QI[Z.ids[Z.i]];if(Z.ans[Z.i])return;let ok;\nif(q.t==='open'){const v=$('#oin').value;if(!v.trim()){toast('Écris ta réponse');return}ok=checkOpen(v,q);g=v}\nelse if(q.t==='vf')ok=(g==='V')===q.v;else ok=g===q.c;\nZ.ans[Z.i]={g,ok};const a=S.ans[q.id]||(S.ans[q.id]={n:0,c:0});a.n++;if(ok)a.c++;a.ok=ok;a.d=today();const d=dayObj();d.q++;if(ok)d.ok++;\nS.cur=Z;addXP(ok?10:2);save();const y=scrollY;render();scrollTo(0,y)}\nfunction imgFor(q){let L=D.imgs.filter(i=>i.ch===q.ch);if(!L.length&&D.fb[q.ch])L=D.imgs.filter(i=>i.k===D.fb[q.ch]);if(!L.length)return null;const ps=qPg(q).split(',').map(r=>r.split(':').map(Number));let best=null,bd=1e9;L.forEach(im=>{const [d,p]=im.r.split(':').map(Number);ps.forEach(([qd,qp])=>{const dd=(qd===d?0:100)+Math.abs(qp-p);if(dd<bd){bd=dd;best=im}})});return best}\nV.quiz=()=>{if(!Z||!Z.ids.length){return hdr(1)+'<p>Aucun quiz en cours.</p>'}const q=QI[Z.ids[Z.i]],f=FI[q.f],A=Z.ans[Z.i],c=CH[q.ch],[rl,ric,rcol]=RUB[f.rub];\nlet body='';\nif(q.t==='qcm'||q.t==='cas'){if(!Z.ord[Z.i]||!A)Z.ord[Z.i]=sh([0,1,2,3]);const ord=Z.ord[Z.i];body=ord.map((oi,k)=>{let cl='';if(A){if(oi===q.c)cl='ok';else if(oi===A.g)cl='ko'}return `<button class=\"opt ${cl}\" ${A?'disabled':''} onclick=\"answer(${oi})\"><span class=\"l\">${LET[k]}</span><span>${esc(q.o[oi])}</span></button>`}).join('')}\nelse if(q.t==='vf'){body=[['V','Vrai'],['F','Faux']].map(([k,l])=>{let cl='';if(A){if((k==='V')===q.v)cl='ok';else if(A.g===k)cl='ko'}return `<button class=\"opt ${cl}\" ${A?'disabled':''} onclick=\"answer('${k}')\"><span class=\"l\">${k}</span><span>${l}</span></button>`}).join('')}\nelse{body=A?`<div class=\"opt ${A.ok?'ok':'ko'}\"><span class=\"l\">✎</span><span>${esc(A.g)}</span></div>`:`<input id=\"oin\" class=\"oinput\" placeholder=\"Ta réponse (accents et majuscules ignorés)\" autocomplete=\"off\" onkeydown=\"if(event.key==='Enter')answer()\"><button class=\"btn gold full\" style=\"margin-top:10px\" onclick=\"answer()\">Valider</button>`}\nconst im=A?imgFor(q):null;const tip=S.tips[q.id];\nreturn hdr()+`<div class=\"prog\"><i style=\"width:${100*(Z.i+(A?1:0))/Z.ids.length}%\"></i></div><div class=\"row small\"><b class=\"grow\">${esc(Z.title)}</b><span class=\"mut\">${Z.i+1} / ${Z.ids.length}</span></div>\n<div class=\"qcard\"><div><span class=\"badge\" style=\"background:${BL[c.b].c};color:#fff\">${esc(c.t)}</span><span class=\"badge\">${TYP[q.t]}</span><span class=\"badge\" style=\"background:${rcol}22;color:${rcol}\">${ric} ${rl}</span><span class=\"badge\">${DIF[q.d]}</span></div><div>${pgList(f.pg)}</div>\n${q.t==='cas'?`<div class=\"situ\"><b>Situation clinique</b><br>${esc(q.s)}</div>`:''}<div class=\"qtext\">${esc(q.q)}</div>${body}\n${A?`<div class=\"verdict ${A.ok?'ok':'ko'}\">${A.ok?'✅ Bonne réponse !':'❌ Pas tout à fait.'}<span><b>Réponse attendue :</b> ${esc(answerText(q))}${q.t==='open'&&q.alt.length?` <span class=\"small mut\">(acceptées : ${esc(q.alt.join(' ; '))})</span>`:''}</span></div>\n<button class=\"btn gold full\" onclick=\"nextQ()\">${Z.i<Z.ids.length-1?'Question suivante →':'Voir le résultat →'}</button>\n${im?`<img class=\"figimg\" src=\"${IM[im.k]}\" alt=\"${esc(im.cap)}\" onclick=\"openViewer('${im.k}')\"><div class=\"cap\">${esc(im.cap)} · ${refLab(im.r)} · toucher pour agrandir</div>`:''}\n<div class=\"card why\" style=\"box-shadow:none;background:var(--bg)\"><h4>💡 Pourquoi ?</h4><div>${esc(q.x)}</div><div style=\"margin-top:8px\" class=\"small\"><b>Support de cours — pages :</b> ${pgList(f.pg)}</div><button class=\"btn line full\" style=\"margin-top:8px\" onclick=\"openRef('${f.pg.split(',')[0]}')\">📖 Ouvrir le cours</button></div>\n<div class=\"card mem\" style=\"box-shadow:none;background:var(--goldlt)\"><h4>🧠 Pour mémoriser</h4>\n<div class=\"aid\"><span class=\"i\" style=\"background:#7FE3D8\">🔑</span><div><b>Moyen mnémotechnique</b><br>${esc(f.mn)}</div></div>\n<div class=\"aid\"><span class=\"i\" style=\"background:#9BE5B0\">🧒🏾</span><div><b>Pour un enfant de 10 ans</b><br>${esc(f.kid)}</div></div>\n<div class=\"aid\"><span class=\"i\" style=\"background:#A9D3FF\">🔄</span><div><b>Reformulation</b><br>${esc(f.ref)}</div></div>\n<div class=\"aid\"><span class=\"i\" style=\"background:#F7B6CF\">➡️</span><div><b>Schéma fléché</b><br><span class=\"schema\">${esc(f.sch)}</span></div></div></div>\n<div class=\"tipline\"><span>💬 Astuce de mémorisation${tip?' : <b style=\"color:var(--ink)\">'+esc(tip)+'</b>':''}</span><button onclick=\"tipEdit('${q.id}')\">${tip?'Modifier':'Ajouter'}</button></div>`:''}</div>\n<div class=\"qnav\"><button class=\"btn line\" ${Z.i?'':'disabled style=\"opacity:.4\"'} onclick=\"prevQ()\">← Précédente</button><button class=\"btn dark\" onclick=\"quitQ()\">Quitter</button><button class=\"btn line\" onclick=\"nextQ()\">Suivante →</button></div>`+foot()};\nfunction nextQ(){if(Z.i<Z.ids.length-1){Z.i++;S.cur=Z;save();go('quiz',{n:Z.i},true)}else finishQ()}\nfunction prevQ(){if(Z.i>0){Z.i--;S.cur=Z;save();go('quiz',{n:Z.i},true)}}\nfunction quitQ(){S.cur=Z;save();toast('Quiz sauvegardé : reprise possible depuis l\\'accueil');go('home',{},true)}\nfunction finishQ(){const R=Z;V._last=R;S.cur=null;addXP(20);save();go('result',{r:Date.now()},true)}\nconst MSG=p=>p>=80?'Excellent ! Tu maîtrises ce contenu 🏆':p>=60?'Très bien, encore un petit effort 💪':p>=40?'Bon début : refais tes erreurs pour consolider 📚':'Courage ! Relis le cours puis réessaie 🌱';\nV.result=()=>{const R=V._last;if(!R)return V.home();const n=R.ids.length,ok=Object.values(R.ans).filter(a=>a.ok).length,p=Math.round(100*ok/n);const errs=R.ids.map((id,i)=>[QI[id],R.ans[i]]).filter(([q,a])=>!a||!a.ok);V._errs=errs.map(e=>e[0].id);\nreturn hdr()+`<div class=\"card res\"><div class=\"mut\">${esc(R.title)}</div><div class=\"big\">${ok}/${n}</div><div style=\"font-size:22px;font-weight:800;color:${mcol(p)}\">${p} %</div><p>${MSG(p)}</p><div class=\"small mut\">+${S.xp-R.xp0} XP gagnés (dont +20 quiz terminé)</div></div>\n${errs.length?`<button class=\"btn gold full\" onclick=\"startQuiz(sh(V._errs),'Refaire les erreurs')\">🔁 Refaire les erreurs (${errs.length})</button>`:''}\n<h2 class=\"tt\">Erreurs et questions non répondues (${errs.length})</h2><div class=\"card list\">${errs.map(([q,a])=>`<div class=\"it\"><div class=\"small mut\">${esc(CH[q.ch].t)} · ${TYP[q.t]}</div><b>${esc(q.q)}</b><div>${a?'Ta réponse : '+esc(q.t==='open'?a.g:q.t==='vf'?(a.g==='V'?'Vrai':'Faux'):q.o[a.g])+'<br>':'<i class=\"mut\">Non répondue</i><br>'}<span style=\"color:var(--ok);font-weight:700\">Bonne réponse : ${esc(answerText(q))}</span></div>${pgList(qPg(q))}</div>`).join('')||'<p>Aucune erreur 🎉</p>'}</div>\n<div class=\"row\"><button class=\"btn line grow\" onclick=\"go('quizhub')\">Autre quiz</button><button class=\"btn dark grow\" onclick=\"go('home')\">Accueil</button></div>`+foot()};\nfunction tipEdit(id){modal(`<h3 style=\"margin:0 0 8px\">Astuce de mémorisation</h3><textarea id=\"mt\" placeholder=\"Ton moyen à toi pour retenir cette question\">${esc(S.tips[id]||'')}</textarea><div class=\"row\" style=\"margin-top:10px\"><button class=\"btn line grow\" onclick=\"closeModal()\">Annuler</button><button class=\"btn gold grow\" onclick=\"saveTip('${id}')\">Enregistrer</button></div>`)}\nfunction saveTip(id){const v=$('#mt').value.trim();if(v)S.tips[id]=v;else delete S.tips[id];save();closeModal();if(VIEW==='quiz'||VIEW==='mine'){const y=scrollY;render();scrollTo(0,y)}toast('Astuce enregistrée')}\n/* ===================== RÉVISER ===================== */\nV.revise=()=>{const due=D.fiches.filter(f=>!S.cards[f.id]||S.cards[f.id].r!=='k').length;\nreturn hdr()+`<h2 class=\"tt\">Réviser</h2>`+[['❓','Quiz',D.qs.length+' questions, 7 modes',\"go('quizhub')\",'#1F4A7E'],['🩺','Cas cliniques',D.qs.filter(q=>q.t==='cas').length+' situations',\"startMode('cas')\",'#E8684A'],['🃏','Cartes à revoir (type examen)',D.fiches.length+' cartes · '+due+' à travailler · série réglable',\"go('flash',{})\",'#B07A12'],['❌','Mes erreurs',errIds().length+' question(s)',\"go('errors')\",'#C0392B'],['🖼️','Galerie',D.imgs.length+' figures du cours',\"go('gallery')\",'#2F6B5E']].map(([ic,l,s,a,c])=>`<button class=\"mode\" onclick=\"${a}\"><span class=\"ic\" style=\"background:${c}22;color:${c}\">${ic}</span><span class=\"grow\"><b>${l}</b><span class=\"small mut\" style=\"display:block\">${s}</span></span><span class=\"mut\">›</span></button>`).join('')+foot()};\nlet FL=null;\nlet FN=20;\nfunction flashSeries(ch){const L=D.fiches.filter(f=>!ch||f.ch===ch);const w=f=>{const c=S.cards[f.id];return !c?1:c.r==='r'?0:c.r==='d'?2:3};return L.map(f=>[f,w(f),Math.random()]).sort((a,b)=>a[1]-b[1]||a[2]-b[2]).slice(0,Math.min(FN,L.length)).map(x=>x[0].id)}\nV.flash=({ch=''})=>{if(!FL||FL.ch!==ch)FL={ch,ids:flashSeries(ch),i:0,back:false};const tot=D.fiches.filter(f=>!ch||f.ch===ch).length;const cur=Math.min(FN,tot);\nconst top=hdr(1)+`<h2 class=\"tt\">Cartes à revoir</h2><div class=\"card\" style=\"padding:10px 14px\"><label class=\"small mut\">Filtrer par chapitre</label><select style=\"width:100%;min-height:46px;border-radius:14px;border:2px solid var(--line);background:var(--card);color:var(--ink);font:inherit;padding:0 10px\" onchange=\"FL=null;go('flash',{ch:this.value,keep:1},true)\"><option value=\"\">Tous les chapitres (${D.fiches.length} cartes)</option>${D.ch.map(c=>`<option value=\"${c.id}\" ${c.id===ch?'selected':''}>${esc(c.t)}</option>`).join('')}</select>\n<div class=\"row\" style=\"margin-top:12px\"><b class=\"grow\">Nombre de cartes par série</b><b id=\"fnv\" style=\"font-size:22px;color:var(--rasp)\">${cur}</b></div>\n<input class=\"slider\" type=\"range\" min=\"1\" max=\"${tot}\" value=\"${cur}\" aria-label=\"Nombre de cartes\" oninput=\"$('#fnv').textContent=this.value\" onchange=\"setFN(+this.value)\">\n<div class=\"row wrap\">${[10,20,50].filter(v=>v<tot).map(v=>`<button class=\"chip ${cur===v?'on':''}\" onclick=\"setFN(${v})\">${v}</button>`).join('')}<button class=\"chip ${cur===tot?'on':''}\" onclick=\"setFN(${tot})\">Toutes (${tot})</button></div></div>`;\nif(FL.i>=FL.ids.length)return top+`<div class=\"card res\"><div class=\"big\">✓</div><p>Série terminée !</p><button class=\"btn gold full\" onclick=\"FL=null;render()\">Nouvelle série de ${cur} cartes</button></div>`+foot();\nconst f=FI[FL.ids[FL.i]],c=CH[f.ch],st=S.cards[f.id];\nreturn top+`<div class=\"row small\"><b class=\"grow\">Carte ${FL.i+1} / ${FL.ids.length}</b>${st?`<span class=\"badge\">${{k:'Connu',d:'Difficile',r:'À revoir'}[st.r]}</span>`:'<span class=\"badge\">Nouvelle</span>'}</div>\n<button class=\"flash ${FL.back?'':'front'}\" onclick=\"FL.back=!FL.back;render()\">${FL.back?`<div class=\"small mut\">${esc(c.t)}</div><div style=\"font-weight:700;margin:6px 0 10px\">${esc(f.b)}</div><div class=\"small\"><b>🔑</b> ${esc(f.mn)}</div><div class=\"small\" style=\"margin-top:6px\"><b>🧒🏾</b> ${esc(f.kid)}</div><div class=\"small\" style=\"margin-top:6px\"><b>🔄</b> ${esc(f.ref)}</div><div class=\"small schema\" style=\"margin-top:6px\">➡️ ${esc(f.sch)}</div>`:`<div class=\"small\" style=\"opacity:.8\">${esc(c.t)} · ${RUB[f.rub][1]} ${RUB[f.rub][0]}</div><div style=\"font-size:20px;font-weight:800;margin-top:10px\">${esc(f.f)}</div><div class=\"small\" style=\"opacity:.75;margin-top:16px\">Touche pour retourner la carte</div>`}</button>\n<div style=\"margin:8px 0\">${pgList(f.pg)}</div>\n${FL.back?`<div class=\"row\"><button class=\"btn grow\" style=\"background:var(--ok);color:#fff\" onclick=\"rate('k')\">Connu</button><button class=\"btn grow\" style=\"background:var(--mid);color:#fff\" onclick=\"rate('d')\">Difficile</button><button class=\"btn grow\" style=\"background:var(--bad);color:#fff\" onclick=\"rate('r')\">À revoir</button></div>`:''}`+foot()};\nfunction setFN(n){FN=n;FL=null;const y=scrollY;render();scrollTo(0,y);toast('Série de '+FL.ids.length+' cartes')}\nfunction rate(r){const f=FL.ids[FL.i];S.cards[f]={r,d:today()};addXP({k:10,d:6,r:3}[r]);FL.i++;FL.back=false;save();render();scrollTo(0,0)}\nV.errors=()=>{const e=errIds().map(id=>QI[id]);return hdr(1)+`<h2 class=\"tt\">Mes erreurs (${e.length})</h2>${e.length?`<button class=\"btn gold full\" onclick=\"startMode('err')\">🔁 Refaire mes erreurs</button>`:''}<div class=\"card list\">${e.map(q=>`<div class=\"it\"><div class=\"small mut\">${esc(CH[q.ch].t)} · ${TYP[q.t]}</div><b>${esc(q.q)}</b><div style=\"color:var(--ok);font-weight:700\">${esc(answerText(q))}</div>${pgList(qPg(q))}</div>`).join('')||'<p>Aucune erreur enregistrée. Lance un quiz !</p>'}</div>`+foot()};\n/* ===================== STATS ===================== */\nV.stats=({m='w'})=>{const days=m==='w'?7:30;const L=[];for(let i=days-1;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const k=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');L.push([d,(S.daily[k]||{}).q||0])}\nconst mx=Math.max(1,...L.map(x=>x[1]));const mi=L.findIndex(x=>x[1]===mx&&mx>0);const tot=Object.values(S.daily).reduce((a,d)=>a+d.q,0),okk=Object.values(S.daily).reduce((a,d)=>a+d.ok,0);\nconst J=['D','L','M','M','J','V','S'];\nreturn hdr()+`<div class=\"pills\"><div class=\"pill\"><b>${fmtT(S.time)}</b>temps d'étude</div><div class=\"pill\"><b>${mastered()}/${D.ch.length}</b>chapitres maîtrisés</div><div class=\"pill\"><b>${acquired()}/${D.qs.length}</b>questions acquises</div></div>\n<div class=\"card\"><div class=\"row\"><b class=\"grow\">Questions répondues</b><button class=\"chip ${m==='w'?'on':''}\" onclick=\"go('stats',{m:'w',keep:1},true)\">Hebdo</button><button class=\"chip ${m==='m'?'on':''}\" onclick=\"go('stats',{m:'m',keep:1},true)\">Mensuel</button></div>\n<div class=\"hist\">${L.map((x,i)=>`<div class=\"${i===mi?'max':''}\" style=\"height:${Math.max(2,100*x[1]/mx)}%\">${i===mi?`<span>${x[1]}</span>`:''}</div>`).join('')}</div><div class=\"hlab\">${L.map((x,i)=>`<span>${m==='w'?J[x[0].getDay()]:(i%5===4?x[0].getDate():'')}</span>`).join('')}</div>${mi>=0?`<div class=\"small mut\" style=\"margin-top:6px\">Maximum : ${mx} questions le ${L[mi][0].toLocaleDateString('fr-FR')}</div>`:''}</div>\n<div class=\"mot\"><div><b>🔥 ${S.xp}</b>XP</div><div><b>⚡ ${S.streak}</b>jours de série</div><div><b>🎯 ${tot?Math.round(100*okk/tot):0} %</b>réussite</div></div>\n<h2 class=\"tt\">Maîtrise par chapitre</h2><div class=\"card\">${D.ch.map(c=>{const p=mastery(c.id);return `<button class=\"mrow\" onclick=\"go('chapter',{id:'${c.id}'})\"><div class=\"row small\"><span class=\"grow\">${esc(c.t)}</span><b style=\"color:${mcol(p)}\">${p} %</b></div><div class=\"bar\"><i style=\"width:${p}%;background:${mcol(p)}\"></i></div></button>`}).join('')}</div>`+foot()};\n/* ===================== PROFIL ===================== */\nV.profile=()=>{const l=lvl(S.xp);return hdr()+`<div class=\"card\" style=\"text-align:center\"><div class=\"av\" style=\"margin:0 auto;width:84px;height:84px;font-size:46px;background:var(--goldlt)\">${S.av}</div><div style=\"font-size:20px;font-weight:800;margin-top:8px\">${esc(S.name||'Ton prénom')}</div><div class=\"small mut\">Niveau ${l} · ${S.xp} XP · 🔥 ${S.streak} jour(s)</div>\n<div class=\"row\" style=\"margin-top:12px\"><input id=\"nm\" type=\"text\" value=\"${esc(S.name)}\" placeholder=\"Ton prénom\" style=\"flex:1;min-height:48px;border-radius:14px;border:2px solid var(--line);background:var(--bg);color:var(--ink);font:inherit;padding:0 12px\"><button class=\"btn gold\" onclick=\"S.name=$('#nm').value.trim();save();render();toast('Prénom enregistré')\">OK</button></div>\n<h3 class=\"st\">Choisir un avatar</h3><div class=\"row wrap\" style=\"justify-content:center\">${AVS.map(a=>`<button class=\"chip ${S.av===a?'on':''}\" style=\"font-size:22px;min-width:52px;min-height:48px\" onclick=\"S.av='${a}';save();render()\">${a}</button>`).join('')}</div></div>\n<div class=\"card\"><b>Règles des XP</b><div class=\"small\" style=\"margin-top:6px\">Bonne réponse <b>+10</b> · mauvaise réponse <b>+2</b> · quiz terminé <b>+20</b><br>Carte Connu <b>+10</b> · Difficile <b>+6</b> · À revoir <b>+3</b> · chapitre lu <b>+5</b><br>Un niveau tous les <b>300 XP</b>.</div></div>\n${[['📝','Mes ajouts & sauvegarde',\"go('mine')\"],['📖','Sommaire',\"go('sommaire')\"],['📊','Tableaux résumés',\"go('tables')\"],['🔤','Glossaire',\"go('glossary')\"],['🖼️','Galerie',\"go('gallery')\"]].map(([i,l,a])=>`<button class=\"mode\" onclick=\"${a}\"><span class=\"ic\" style=\"background:var(--goldlt)\">${i}</span><b class=\"grow\">${l}</b><span class=\"mut\">›</span></button>`).join('')}`+foot()};\nV.mine=()=>{const tips=Object.entries(S.tips),notes=Object.entries(S.notes),hls=Object.entries(S.hl).flatMap(([p,L])=>L.map(h=>[p,h]));\nreturn hdr(1)+`<h2 class=\"tt\">Mes ajouts & sauvegarde</h2>\n<div class=\"card\"><b>Sauvegarde</b><p class=\"small mut\">Ta progression est enregistrée dans ce navigateur. Exporte-la pour la garder ou la transférer.</p><div class=\"row wrap\"><button class=\"btn gold grow\" onclick=\"exportJ()\">⬇ Exporter (JSON)</button><label class=\"btn line grow\" style=\"cursor:pointer\">⬆ Importer<input type=\"file\" accept=\"application/json,.json\" style=\"display:none\" onchange=\"importJ(this)\"></label></div><button class=\"btn line full\" style=\"margin-top:10px;color:var(--bad)\" onclick=\"resetAsk()\">Réinitialiser toute la progression</button></div>\n<h3 class=\"st\">Astuces (${tips.length})</h3><div class=\"card list\">${tips.map(([id,t])=>`<div class=\"it\"><div class=\"small mut\">${esc(QI[id]?QI[id].q:id)}</div><b>${esc(t)}</b><div><button class=\"annot\" onclick=\"tipEdit('${id}')\">Modifier</button><button class=\"annot\" onclick=\"delete S.tips['${id}'];save();render()\">Supprimer</button></div></div>`).join('')||'<p class=\"mut small\">Ajoute une astuce sous la correction d\\'une question.</p>'}</div>\n<h3 class=\"st\">Notes de cours (${notes.length})</h3><div class=\"card list\">${notes.map(([p,t])=>`<div class=\"it\">${pgBtn(p)}<div style=\"white-space:pre-wrap\">${esc(t)}</div><button class=\"annot\" onclick=\"delete S.notes['${p}'];save();render()\">Supprimer</button></div>`).join('')||'<p class=\"mut small\">Touche « Annoter » sous une page du cours.</p>'}</div>\n<h3 class=\"st\">Surlignages (${hls.length})</h3><div class=\"card list\">${hls.map(([p,h])=>`<div class=\"it\">${pgBtn(p)} <span class=\"badge\">${HLC[h.c]}</span><div><mark class=\"hl ${h.c}\" style=\"cursor:default\">${esc(h.t)}</mark></div><button class=\"annot\" onclick=\"rmHL('${p}','${h.id}')\">Retirer</button></div>`).join('')||'<p class=\"mut small\">Sélectionne un passage du cours pour le surligner.</p>'}</div>`+foot()};\nfunction exportJ(){const b=new Blob([JSON.stringify({app:'ORL-INFAS-L3',v:1,date:new Date().toISOString(),data:S},null,1)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='ORL_progression_'+today()+'.json';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);toast('Progression exportée')}\nfunction importJ(inp){const f=inp.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const j=JSON.parse(r.result);const d=j.data||j;if(typeof d!=='object'||!('xp' in d)||!('ans' in d))throw 0;S=Object.assign(blank(),d);save();render();toast('Progression importée ✓')}catch(e){toast('Fichier invalide : choisis un export JSON de cette appli')}};r.readAsText(f)}\nfunction resetAsk(){modal(`<h3 style=\"margin:0 0 8px\">Tout réinitialiser ?</h3><p class=\"small\">XP, réponses, cartes, notes, surlignages et astuces seront effacés. Pense à exporter avant.</p><div class=\"row\"><button class=\"btn line grow\" onclick=\"closeModal()\">Annuler</button><button class=\"btn grow\" style=\"background:var(--bad);color:#fff\" onclick=\"doReset()\">Réinitialiser</button></div>`)}\nfunction doReset(){try{localStorage.removeItem(KEY)}catch(e){}S=blank();Z=null;FL=null;closeModal();go('home',{},true);toast('Progression réinitialisée')}\n/* ===================== DÉMARRAGE ===================== */\ndocument.addEventListener('visibilitychange',save);\nrender();\nif(!S.name&&!S.xp)setTimeout(()=>modal(`<h3 style=\"margin:0 0 6px\">Bienvenue 👋🏾</h3><p class=\"small mut\">Comment t'appelles-tu ? (modifiable ensuite dans Profil)</p><input id=\"fn\" type=\"text\" placeholder=\"Ton prénom\"><div class=\"row\" style=\"margin-top:10px\"><button class=\"btn line grow\" onclick=\"closeModal()\">Plus tard</button><button class=\"btn gold grow\" onclick=\"S.name=$('#fn').value.trim();save();closeModal();render()\">Commencer</button></div>`),300);\n<%/script>\n</body>\n</html>\n";
